"""Master tools module for the TB-v2 pipeline (flattened, single-file).

Every Trial Balance pipeline tool function lives in this module. Generated by
flattening backend/tools/<domain>/*.py + backend/agent/pipeline_tool.py +
backend/agent/canonical_schema.py into one file, mirroring TB-v1's tools.py.

Layout: shared infrastructure -> canonical schema constants -> shared helpers
-> tool functions grouped by former domain. Domain tags passed to
@pipeline_tool(name, domain=...) feed TOOL_REGISTRY, which backend/agent.py
reads instead of walking the filesystem.
"""

