def _write_schedule_appendix(doc, manifest, add_body, add_note, add_table):
    """Section 25 -- the index of every sheet in the workbook.

    This is the guarantee behind the cross-referencing requirement. Sections above
    cite the sheets relevant to them; this lists every sheet without exception, so no
    schedule can exist in the workbook without being named in this document.
    """
    doc.add_heading("25. Detailed Appendices and Full TB Schedules", level=1)
    sheets = manifest.get("sheets", [])
    workbook = manifest.get("workbook")

    if not sheets:
        add_body(
            "No accompanying workbook was produced for this run, so there are no detailed "
            "schedules to reference. Every population summarised above is limited to what "
            "this document itself shows."
        )
        return

    add_body(
        f"The accompanying workbook {workbook} contains {len(sheets)} schedule(s). Sections "
        "above are deliberately summarised; each cites the schedule holding its complete "
        "population. Every sheet in the workbook appears in the table below."
    )
    add_table(
        ["Sheet", "Rows", "Supports section", "Contents"],
        [[s["name"], f"{s['rows']:,}", str(s["section"]), s["contains"]]
         for s in sorted(sheets, key=lambda x: (x["section"], x["name"]))],
    )

    unregistered = manifest.get("unregistered_sheets", [])
    if unregistered:
        add_note(
            "The workbook also contains sheet(s) not in the schedule registry: "
            f"{', '.join(unregistered)}. These are not cross-referenced above — add them to "
            "backend/tools/_report_schedules.py::SCHEDULES so they are."
        )

def _write_front_sections(doc, out_dir, manifest, add_body, add_note, add_table,
                          add_bullets, safe_fmt, sections):
    def close(section):
        line = reference_line(manifest, section)
        if line:
            add_note(line)

    if 4 in sections:
        doc.add_heading("4. Financial-Statement Reconstruction", level=1)
        stats = _load(out_dir, "financial_snapshot_statistics.json")
        if stats:
            add_body("Balance-sheet and profit-and-loss totals rebuilt from the trial balance's "
                     "own Schedule III grouping, to the hierarchy level the mapping supports.")
            add_table(["Statement head", "Amount"], [
                ["Total assets", safe_fmt(stats.get("total_assets", 0))],
                ["Total liabilities", safe_fmt(stats.get("total_liabilities", 0))],
                ["Total equity", safe_fmt(stats.get("total_equity", 0))],
                ["Total revenue", safe_fmt(stats.get("total_revenue", 0))],
                ["Total expenses", safe_fmt(stats.get("total_expenses", 0))],
            ])
        else:
            _unavailable(add_note, "Financial-statement reconstruction",
                         "build_financial_snapshot did not run for this dataset.")
        add_body("Notes to the accounts are not reconstructed. Disclosure content is not carried "
                 "in a trial balance, so only the primary statement heads can be rebuilt here.")
        close(4)

    if 5 in sections:
        doc.add_heading("5. Mapping and Classification Quality", level=1)
        note = _load(out_dir, "normalisation_note.json")
        if note:
            pop = note.get("row_population", {})
            add_table(["Measure", "Value"], [
                ["Rows in canonical TB", f"{pop.get('rows_in_canonical_tb', 0):,}"],
                ["Mapped accounts", f"{pop.get('mapped_accounts', 0):,}"],
                ["Unmapped / unmatched", f"{pop.get('unmapped_or_unmatched_accounts', 0):,}"],
                ["Mapped percentage", f"{pop.get('mapped_percentage', 0)}%"],
            ])
            add_note("Relationship, ratio and counterpart analytics degrade in proportion to "
                     "unmapped coverage. An unclear account is never force-mapped to close the "
                     "gap -- the chart of accounts is requested instead.")
        else:
            _unavailable(add_note, "Mapping quality",
                         "build_normalisation_note did not run for this dataset.")
        close(5)

    if 7 in sections:
        doc.add_heading("7. Standalone Analytical Review", level=1)
        ds = _load(out_dir, "data_sufficiency.json")
        add_body("This is a single-period review. Movement and variance analytics that require a "
                 "comparative period are not performed here; a prior-period trial balance enables "
                 "them through the comparative report.")
        if ds:
            add_note(f"Data sufficiency: {ds.get('grade', 'Unknown')}. {ds.get('rationale', '')}")
            disabled = ds.get("disabled_checks", [])
            if disabled:
                doc.add_heading("Checks unavailable or weakened on this dataset", level=2)
                add_bullets(disabled[:12])
        close(7)

    if 9 in sections:
        doc.add_heading("9. Ratio and Relationship Analytics", level=1)
        ratios = _load(out_dir, "audit_ratio_pack.json")
        if ratios:
            doc.add_heading("Audit-analytical ratios", level=2)
            add_table(["Ratio", "Value", "Basis"],
                      [[k.replace("_", " ").title(),
                        r.get("value_pct") or "not computed",
                        r.get("formula", "")]
                       for k, r in (ratios.get("ratios") or {}).items()])
            add_note("A ratio whose component could not be located is reported as not computed "
                     "with the component named. Approximating it would present an unvalidated "
                     "figure under a real metric's name.")
        rel = _load(out_dir, "relationship_expectations.json")
        if rel:
            doc.add_heading("Expected relationships", level=2)
            add_table(["Relationship", "Status", "Observed"],
                      [[r["name"], r["status"].replace("_", " "),
                        f"{r.get('observed_ratio', 0):.2%}" if r.get("observed_ratio") is not None else "—"]
                       for r in rel.get("results", [])])
        cp = _load(out_dir, "counterpart_screen.json")
        if cp:
            doc.add_heading("Missing counterparts", level=2)
            add_body("The audit signal is the ABSENT counterpart. A material head whose expected "
                     "pair is missing or trivially small is a completeness question.")
            add_table(["Relationship", "Source head", "Source", "Counterpart"],
                      [[f["relationship_id"], f.get("source_head", ""),
                        safe_fmt(f.get("source_balance", 0)), safe_fmt(f.get("target_balance", 0))]
                       for f in cp.get("finding_records", [])])
        if not any((ratios, rel, cp)):
            _unavailable(add_note, "Ratio and relationship analytics",
                         "None of the ratio or relationship screens ran for this dataset.")
        close(9)

    if 11 in sections:
        doc.add_heading("11. Assertion-Level Risk Assessment", level=1)
        aem = _load(out_dir, "assertion_evidence_map.json")
        if aem:
            summ = aem.get("summary", {})
            add_body(
                f"{summ.get('exceptions_mapped', 0)} exception(s) mapped to the assertions their "
                f"account area exposes. {summ.get('generic_evidence_replaced', 0)} carried generic "
                "evidence derived from which engine flagged them; those now name the specific "
                "records that resolve the assertion."
            )
            by_area = summ.get("by_account_area", {})
            if by_area:
                add_table(["Account area", "Exceptions"],
                          [[k.replace("_", " ").title(), str(v)] for k, v in by_area.items()])
            if summ.get("unclassified"):
                add_note(f"{summ['unclassified']} exception(s) could not be matched to an account "
                         "area and carry information-request evidence only -- a mapping is never "
                         "forced to close that gap.")
        else:
            _unavailable(add_note, "Assertion-level assessment",
                         "build_assertion_evidence_map did not run for this dataset.")
        close(11)


# ---- from backend/tools/_shared.py ----
NUMBER_WORDS = {1: "One", 2: "Two", 3: "Three", 4: "Four", 5: "Five",
                6: "Six", 7: "Seven", 8: "Eight", 9: "Nine", 10: "Ten"}

_ESTIMATION_PACK = load_pack("estimation")

FCY_KEYWORDS = tuple(_ESTIMATION_PACK["foreign_currency"])

def safe_fmt(val) -> str:
    """Formats a value as a thousands-separated integer string, falling back to str().

    A residual below 1 (e.g. a 3.05e-5 Dr-Cr rounding difference) is shown at full
    precision instead of collapsing to "0" -- TB-R20: blanket :,.0f rounding made a
    genuine nonzero control-total residual read as a perfect tie-out in the report,
    while the Excel workbook (which keeps the raw float in the cell, display format
    aside) showed the true value."""
    try:
        f = float(val)
    except (TypeError, ValueError):
        return str(val)
    if 0 < abs(f) < 1:
        return f"~0 (residual: {f:.6f})"
    return f"{f:,.0f}"

def resolve_severity(rule_score: float, abs_amount: float, clearly_trivial: float) -> str:
    """Single severity function -- TB-R05/R16/R17: severity must never be computed
    independently in more than one place (a report renderer must always render this
    verbatim, never re-tier it), and must never rate MEDIUM+ on an amount below the
    clearly-trivial threshold regardless of how many rule-engines fired on it.

    rule_score: composite weighted score from triggered detection rules (unchanged
    tiering: >75 Critical, >=50 High, >=25 Medium, >0 Low, else Information Request).
    abs_amount: the finding's absolute closing balance / amount at risk.
    clearly_trivial: materiality's clearly-trivial threshold for this engagement."""
    if clearly_trivial and abs_amount < clearly_trivial:
        return "Low" if rule_score > 0 else "Information Request"
    if rule_score > 75:
        return "Critical"
    if rule_score >= 50:
        return "High"
    if rule_score >= 25:
        return "Medium"
    if rule_score > 0:
        return "Low"
    return "Information Request"

def hierarchy_path(row: dict) -> str:
    """Builds an on-the-fly display path from the new canonical head/sub-head columns,
    skipping any segment that is missing. Per canonical_schema.py, hierarchy_path/
    hierarchy_level are deliberately NOT persisted columns — every consumer derives this."""
    segs = [row.get("bs_pl"), row.get("main_head"), row.get("sub_head_1"), row.get("sub_head_2")]
    parts = [str(s).strip() for s in segs if s not in (None, "") and str(s).strip().lower() != "none"]
    return " > ".join(parts)

def classify_row(row: dict) -> tuple:
    """Best-effort (head, sub, note) classification for a canonical TB row under the new
    schema (bs_pl/main_head/sub_head_1/sub_head_2/account_type/mapped_status).

    Replaces TB-v1's `_NOTE_TO_FSLI` reclassification table, which existed only to patch
    known bugs in the old pipeline's own fs_head rollup (e.g. CWIP rolled under Equity).
    The new schema's main_head/account_type are trusted directly instead.

    `head` is normalized to one of Assets/Liabilities/Equity/Revenue/Expenses/Unmapped where
    recognizable from account_type or main_head; otherwise the raw label (or a bs_pl-derived
    Balance Sheet/Profit & Loss fallback) is used verbatim so the report never crashes, it
    just shows whatever classification label upstream actually produced.
    """
    status = str(row.get("mapped_status") or "").upper()
    if status in (MAPPED_STATUS_UNMAPPED, MAPPED_STATUS_UNMATCHED):
        note = row.get("sub_head_1") or row.get("main_head") or row.get("sub_head_2") or "Unmapped"
        return "Unmapped", "Unmapped", str(note)

    head = None
    for source in (row.get("account_type"), row.get("main_head")):
        s = str(source).strip() if source not in (None, "") else ""
        if not s or s.lower() == "none":
            continue
        low = s.lower()
        if "asset" in low:
            head = "Assets"
        elif "liab" in low:
            head = "Liabilities"
        elif "equity" in low:
            head = "Equity"
        elif "revenue" in low or "income" in low:
            head = "Revenue"
        elif "expense" in low or "expenditure" in low:
            head = "Expenses"
        else:
            head = s
        break

    if head is None:
        bs_pl = str(row.get("bs_pl") or "").strip().upper()
        if bs_pl.startswith("BS"):
            head = "Balance Sheet"
        elif bs_pl.startswith("PL") or "P&L" in bs_pl or "P & L" in bs_pl:
            head = "Profit & Loss"
        else:
            head = "Unmapped"

    sub = row.get("sub_head_1") or row.get("main_head") or head
    return head, str(sub), hierarchy_path(row)

def load_canonical_tb(path, numeric_cols=None) -> Optional[pl.DataFrame]:
    """Loads a canonical_tb.parquet with numeric coercion and adds report_head/report_sub/
    report_note columns derived via classify_row(). Returns None if the file is absent or
    fails to parse — callers should treat that as 'section unavailable', not fatal."""
    if not path:
        return None
    p = Path(path)
    if not p.exists():
        return None
    try:
        df = pl.read_parquet(p)
    except Exception:
        return None

    cols = numeric_cols or CANONICAL_TB_NUMERIC_COLUMNS
    exprs = [
        (pl.col(c).cast(pl.Float64, strict=False).fill_null(0.0).alias(c) if c in df.columns else pl.lit(0.0).alias(c))
        for c in cols
    ]
    df = df.with_columns(exprs)

    if "gl_code" in df.columns:
        df = df.filter(pl.col("gl_code").is_not_null())

    if df.is_empty():
        return df.with_columns(
            [
                pl.lit(None, dtype=pl.Utf8).alias("report_head"),
                pl.lit(None, dtype=pl.Utf8).alias("report_sub"),
                pl.lit(None, dtype=pl.Utf8).alias("report_note"),
            ]
        )

    classified = [classify_row(r) for r in df.iter_rows(named=True)]
    df = df.with_columns(
        [
            pl.Series("report_head", [c[0] for c in classified]),
            pl.Series("report_sub", [c[1] for c in classified]),
            pl.Series("report_note", [c[2] for c in classified]),
        ]
    )
    return df

def movement_flag(abs_amount, overall_materiality, performance_materiality) -> Optional[str]:
    """Classifies an absolute movement against materiality thresholds — CRITICAL (>=2x
    overall), HIGH (>=overall), MEDIUM (>=performance), else None (not material enough)."""
    if overall_materiality and abs_amount >= overall_materiality * 2:
        return "CRITICAL"
    if overall_materiality and abs_amount >= overall_materiality:
        return "HIGH"
    if performance_materiality and abs_amount >= performance_materiality:
        return "MEDIUM"
    return None

def control_totals(df: Optional[pl.DataFrame]) -> Optional[dict]:
    """Deterministic control-total checks (debit=credit, tie-out, duplicates, zero rows)."""
    if df is None or df.is_empty():
        return None
    total_debit = float(df["debit"].sum()) if "debit" in df.columns else 0.0
    total_credit = float(df["credit"].sum()) if "credit" in df.columns else 0.0
    sum_closing = float(df["closing_balance"].sum()) if "closing_balance" in df.columns else 0.0
    # height - n_unique matches pandas Series.duplicated().sum() semantics (counts
    # occurrences BEYOND the first per value), unlike polars' own is_duplicated()
    # which flags every occurrence including the first.
    dup_count = int(df.height - df["gl_code"].n_unique()) if "gl_code" in df.columns else 0
    zero_rows = 0
    if {"opening_balance", "closing_balance", "debit", "credit"}.issubset(set(df.columns)):
        zero_rows = df.filter(
            (pl.col("opening_balance") == 0)
            & (pl.col("closing_balance") == 0)
            & (pl.col("debit") == 0)
            & (pl.col("credit") == 0)
        ).height
    return {
        "total_debit": total_debit,
        "total_credit": total_credit,
        "difference": total_debit - total_credit,
        "sum_closing": sum_closing,
        "duplicate_gl_codes": dup_count,
        "fully_zero_rows": zero_rows,
    }

def movement_rows_from_canonical(df, om, perf_mat, exclude_heads=("Revenue", "Expenses", "Suspense", "Unmapped"), limit=20) -> list:
    """Balance-sheet opening-to-closing movement, flagged against materiality — Revenue/
    Expense accounts are excluded since they structurally run from nil to their full-year
    figure and are not 'movement' in the single-period risk sense."""
    if df is None or df.is_empty() or "report_head" not in df.columns:
        return []
    exclude = {h.lower() for h in exclude_heads}
    rows = []
    for r in df.iter_rows(named=True):
        head = str(r.get("report_head", "") or "")
        if head.lower() in exclude:
            continue
        ob = float(r.get("opening_balance", 0.0))
        cb = float(r.get("closing_balance", 0.0))
        mov = cb - ob
        flag = movement_flag(abs(mov), om, perf_mat)
        if not flag:
            continue
        rows.append({
            "gl_code": r.get("gl_code", ""),
            "gl_name": r.get("gl_name", ""),
            "fs_head": head,
            "opening": ob,
            "closing": cb,
            "movement": mov,
            "flag": flag,
        })
    sev_order = {"CRITICAL": 3, "HIGH": 2, "MEDIUM": 1}
    rows.sort(key=lambda x: (sev_order.get(x["flag"], 0), abs(x["movement"])), reverse=True)
    return rows[:limit]

_OFFSETTING_PAIR_TOLERANCE_PCT = 1.0

def concentration_rows_from_canonical(df, threshold_pct=5.0, limit=15, clearly_trivial=0.0) -> list:
    """Accounts individually exceeding threshold_pct of their report_head's total absolute
    closing balance.

    TB-R14 (denominator degeneracy): a report_head with only one non-trivial account
    trivially produces a ~100% "concentration" finding that says nothing about risk --
    skipped entirely rather than surfaced as a false artefact.

    TB-R13 (offsetting contra pairs): two near-equal-and-opposite accounts in the same
    head (e.g. a recovery/allocation pair) each individually cross the threshold and used
    to render as two separate findings, even though their combined effect nets close to
    nil. Such pairs are collapsed into one annotated finding instead."""
    if df is None or df.is_empty() or "report_head" not in df.columns:
        return []
    head_totals = dict(
        df.group_by("report_head").agg(pl.col("closing_balance").abs().sum().alias("total")).iter_rows()
    )
    head_material_counts: dict = {}
    if clearly_trivial:
        head_material_counts = dict(
            df.filter(pl.col("closing_balance").abs() > clearly_trivial)
            .group_by("report_head").agg(pl.len().alias("n")).iter_rows()
        )

    rows = []
    for r in df.iter_rows(named=True):
        head = str(r.get("report_head", "") or "")
        total = head_totals.get(head, 0.0)
        if not total:
            continue
        if clearly_trivial and head_material_counts.get(head, 0) <= 1:
            continue
        cb = float(r.get("closing_balance", 0.0))
        pct = abs(cb) / total * 100
        if pct >= threshold_pct:
            rows.append({
                "gl_code": r.get("gl_code", ""),
                "gl_name": r.get("gl_name", ""),
                "fs_head": head,
                "closing": cb,
                "pct": pct,
            })

    rows = _collapse_offsetting_pairs(rows)
    rows.sort(key=lambda x: x["pct"], reverse=True)
    return rows[:limit]

def _collapse_offsetting_pairs(rows: list) -> list:
    """Merges near-equal-and-opposite-sign row pairs within the same fs_head into one
    annotated finding, keeping the larger-magnitude account's pct for "why this was
    flagged" while reporting the combined net effect."""
    used = set()
    merged = []
    for i, a in enumerate(rows):
        if i in used:
            continue
        pair_found = False
        for j in range(i + 1, len(rows)):
            if j in used:
                continue
            b = rows[j]
            if b["fs_head"] != a["fs_head"] or (a["closing"] >= 0) == (b["closing"] >= 0):
                continue
            hi, lo = (abs(a["closing"]), abs(b["closing"])) if abs(a["closing"]) >= abs(b["closing"]) else (abs(b["closing"]), abs(a["closing"]))
            if hi == 0:
                continue
            if (hi - lo) / hi * 100 > _OFFSETTING_PAIR_TOLERANCE_PCT:
                continue
            primary, secondary = (a, b) if abs(a["closing"]) >= abs(b["closing"]) else (b, a)
            net = a["closing"] + b["closing"]
            merged.append({
                **primary,
                "offsetting_pair": True,
                "paired_gl_code": secondary["gl_code"],
                "paired_gl_name": secondary["gl_name"],
                "net_closing": net,
                "note": (
                    f"Offsetting pair with {secondary['gl_name']} ({secondary['gl_code']}) -- "
                    f"combined net impact {net:,.0f}, close to nil."
                ),
            })
            used.add(i)
            used.add(j)
            pair_found = True
            break
        if not pair_found:
            merged.append(a)
    return merged

_ESTIMATION_RISK_KEYWORDS = tuple(_ESTIMATION_PACK["estimation_risk"])

def is_estimation_risk_account(gl_name) -> bool:
    """TB-R12/R15: accounts whose carrying value rests on management estimate/judgment
    (acquisition cost, CWIP, exploration cost, impairment provisions) rather than a
    transactable market price. A dormant/no-movement pattern on these is not "structurally
    expected" the way a fully-depreciated fixed asset is -- the balance could be materially
    wrong for years with no transaction ever surfacing it."""
    name_lower = str(gl_name or "").lower()
    return any(kw in name_lower for kw in _ESTIMATION_RISK_KEYWORDS)

def dormant_rows_from_canonical(df, limit=15) -> list:
    """Accounts with zero debit/credit movement in the period but a non-zero closing
    balance. Each row is tagged `is_estimation_risk` (TB-R15) so renderers can split
    "structurally expected, no movement" (share capital, fully-depreciated assets) from
    large estimation-prone balances that warrant confirmation regardless of size."""
    if df is None or df.is_empty() or not {"debit", "credit", "closing_balance"}.issubset(set(df.columns)):
        return []
    dormant = df.filter((pl.col("debit") == 0) & (pl.col("credit") == 0) & (pl.col("closing_balance") != 0))
    if dormant.is_empty():
        return []
    dormant = dormant.with_columns(pl.col("closing_balance").abs().alias("_abs")).sort("_abs", descending=True)
    return [
        {
            "gl_code": r.get("gl_code", ""),
            "gl_name": r.get("gl_name", ""),
            "fs_head": r.get("report_head", ""),
            "closing": float(r.get("closing_balance", 0.0)),
            "is_estimation_risk": is_estimation_risk_account(r.get("gl_name")),
        }
        for r in dormant.head(limit).iter_rows(named=True)
    ]

def resolve_entity_and_fy(tb_meta: dict, manifest: Optional[dict] = None) -> tuple:
    """Best-effort entity label + FY label for report titles/headers.

    Prefers the structured fields load_tb_from_db.py writes into tb_metadata.json
    (entity_name/company_name/financial_year) -- real MAIN document fields, not a
    guess. Falls back to regex-parsing the uploaded file's name (the only signal
    available for an upload-sourced run, e.g. "OVRL_TB_FY2025-26_31.03.2026.xlsx")
    when the structured fields aren't present. Without this, every report builder
    fell back to a literal "Unknown Source" title/header for DB-sourced runs, since
    no tool wrote tb_metadata.json at all before load_tb_from_db.py started doing so.

    Returns (entity_label, fy_label, source_file)."""
    manifest = manifest or {}
    source_file = tb_meta.get("source_file") or manifest.get("source_file") or "Unknown Source"

    entity_label = tb_meta.get("company_name") or tb_meta.get("entity_name")
    fy_label = tb_meta.get("financial_year")

    if not entity_label or not fy_label:
        stem = Path(source_file).stem if source_file else "Unknown Entity"
        if not fy_label:
            fy_match = re.search(r"FY\s*[\d\-/]+", stem, re.IGNORECASE)
            fy_label = fy_match.group(0).upper() if fy_match else fy_label
        if not entity_label:
            tokens = re.split(r"[_\-\s]+", stem)
            entity_candidates = [t for t in tokens if t.isalpha() and t.upper() == t and len(t) > 1]
            entity_label = entity_candidates[-1] if entity_candidates else stem

    return entity_label, (fy_label or ""), source_file

def resolve_artifact_path(provided_path, out_dir: Path, default_filename: str) -> Path:
    """Resolve a possibly-missing/optional input path against a default filename in out_dir.

    Also corrects a wrong-format path (e.g. an LLM passing the .json sibling of a tool that
    writes both .parquet and .json, like fsli_summary.json instead of fsli_summary.parquet)
    back to the canonical default_filename in out_dir, when that canonical file actually
    exists -- SINGLE_TB uses one shared output_dir per run (see system_prompt.py's
    Artifact-Passing Convention), so the canonical filename is always the authoritative
    location for that artifact type once its producing tool has run."""
    default_path = out_dir / default_filename
    if not provided_path:
        return default_path
    p = Path(provided_path)
    if p.is_dir() or not p.exists():
        return default_path
    if p.suffix != default_path.suffix and default_path.exists():
        return default_path
    return p

def safe_load_json(path) -> dict:
    """Load JSON, returning {} on any failure (missing file, parse error)."""
    if not path:
        return {}
    p = Path(path)
    if not p.exists():
        return {}
    try:
        with open(p, "r", encoding="utf-8", errors="replace") as f:
            return json.load(f)
    except Exception:
        return {}

def safe_load_parquet(path) -> pl.DataFrame:
    """Load a parquet file, returning an empty DataFrame on any failure."""
    if not path:
        return pl.DataFrame()
    p = Path(path)
    if not p.exists():
        return pl.DataFrame()
    try:
        return pl.read_parquet(p)
    except Exception:
        return pl.DataFrame()

def first_present_column(df: pl.DataFrame, candidates, default=None):
    """Return the first column name from `candidates` present in df, else `default`."""
    for c in candidates:
        if c in df.columns:
            return c
    return default

def row_fsli(row, default="Unmapped") -> str:
    """Resolve the FSLI grouping key for a canonical TB row: sub_head_1, falling back to main_head."""
    for key in ("sub_head_1", "main_head"):
        val = row.get(key)
        if val is not None and str(val).strip() and str(val).strip().lower() != "nan":
            return str(val).strip()
    return default

def row_fs_head(row, default="Unmapped") -> str:
    """Resolve the top-level FS head for a canonical TB row: main_head."""
    val = row.get("main_head")
    if val is not None and str(val).strip() and str(val).strip().lower() != "nan":
        return str(val).strip()
    return default

def sign_convention_stats(df) -> Optional[dict]:
    """Counts accounts sitting opposite their report_head's normal balance side — a broad
    screen for contra/provision/clearing accounts, not a misclassification finding itself."""
    if df is None or df.is_empty() or "report_head" not in df.columns:
        return None
    heads_lower = pl.col("report_head").cast(pl.Utf8).str.to_lowercase()
    debit_side = df.filter(heads_lower.is_in(list(normal_debit_heads())))
    credit_side = df.filter(heads_lower.is_in(list(normal_credit_heads())))
    debit_flip = int((debit_side["closing_balance"] < 0).sum())
    credit_flip = int((credit_side["closing_balance"] > 0).sum())
    return {
        "debit_total": len(debit_side), "debit_flip": debit_flip,
        "debit_flip_pct": round(debit_flip / len(debit_side) * 100, 1) if len(debit_side) else 0.0,
        "credit_total": len(credit_side), "credit_flip": credit_flip,
        "credit_flip_pct": round(credit_flip / len(credit_side) * 100, 1) if len(credit_side) else 0.0,
    }

def find_fsli_component(df, keywords) -> Optional[dict]:
    """Shallowest FSLI node whose node_name contains any keyword (case-insensitive
    substring), as {"balance", "node_name", "hierarchy_level"}, or None.

    Taking the SHALLOWEST match is what avoids double-counting a subtotal together
    with its own children -- e.g. "Current assets" and "Trade receivables" both
    match a "current asset"/"receivable" search in a rolled-up hierarchy.

    Promoted here from build_financial_ratios.py::_find_component: the counterpart,
    relationship-expectation, statutory and audit-ratio screens all need the same
    matcher, and copying it four times would recreate exactly the duplication the
    knowledge packs exist to remove.
    """
    if df is None or df.is_empty() or "node_name" not in df.columns:
        return None
    mask = pl.any_horizontal([
        pl.col("node_name").cast(pl.Utf8).str.to_lowercase().str.contains(kw, literal=True).fill_null(False)
        for kw in keywords
    ])
    matches = df.filter(mask)
    if matches.is_empty():
        return None
    row = matches.sort("hierarchy_level").row(0, named=True)
    return {
        "balance": abs(float(row.get("closing_balance", 0.0))),
        "node_name": row.get("node_name"),
        "hierarchy_level": row.get("hierarchy_level"),
    }

def gl_total_by_keywords(tb_df, keywords, exclude=()) -> dict:
    """Fallback matcher over the canonical TB itself, for when the FSLI hierarchy
    carries no matching node (unmapped or thinly-mapped TBs).

    Scans gl_name, main_head and sub_head_1 -- a real account's currency/statutory
    nature often shows in its grouping text rather than its own ledger name (the
    same finding that drove build_entity_profile to widen its FX scan).

    `exclude` drops rows matching those terms even when a keyword hit. Needed
    because a contra account's grouping text matches its parent head: "Accumulated
    Depreciation on Plant" sits under "Property, Plant and Equipment" AND contains
    "depreciation", so without exclusion it inflates both sides of the depreciation
    proxy at once.

    Returns {"balance", "account_count", "accounts"} with balance as the ABSOLUTE
    sum, so a debit-and-credit pair inside one keyword group does not net to zero
    and read as "head absent".
    """
    empty = {"balance": 0.0, "account_count": 0, "accounts": []}
    if tb_df is None or tb_df.is_empty():
        return empty

    cols = [c for c in ("gl_name", "main_head", "sub_head_1", "sub_head_2") if c in tb_df.columns]
    if not cols:
        return empty

    mask = pl.lit(False)
    for col in cols:
        lowered = pl.col(col).cast(pl.Utf8).str.to_lowercase().fill_null("")
        for kw in keywords:
            mask = mask | lowered.str.contains(kw, literal=True)

    if exclude:
        excl = pl.lit(False)
        for col in cols:
            lowered = pl.col(col).cast(pl.Utf8).str.to_lowercase().fill_null("")
            for term in exclude:
                excl = excl | lowered.str.contains(term, literal=True)
        mask = mask & ~excl

    matches = tb_df.filter(mask)
    if matches.is_empty():
        return empty

    return {
        "balance": float(matches["closing_balance"].abs().sum()),
        "account_count": matches.height,
        "accounts": [
            {
                "gl_code": str(r.get("gl_code") or ""),
                "gl_name": str(r.get("gl_name") or ""),
                "closing_balance": round(float(r.get("closing_balance") or 0.0), 2),
            }
            for r in matches.sort(pl.col("closing_balance").abs(), descending=True)
                            .head(10).iter_rows(named=True)
        ],
    }


# ---- from backend/tools/reasoning/_safe_wording.py ----
_LANGUAGE_PACK = load_pack("language")

_SAFE_WORDING_RULES = [
    (r["pattern"], r["replacement"]) for r in _LANGUAGE_PACK["phrase_substitutions"]
]

_ASSURANCE_WORDS = list(_LANGUAGE_PACK["assurance_words"])

SAFE_WORDING_DISCLAIMER = _LANGUAGE_PACK["mandatory_disclaimer"]

def apply_safe_wording(text: str, append_disclaimer: bool = True) -> str:
    """Deterministic post-processing pass: substitutes banned assurance-language
    phrases for safe risk-indicator phrasing (word-boundary regex, not naive
    str.replace), then appends the mandatory disclaimer verbatim unless
    append_disclaimer=False (use False for per-finding text where the
    disclaimer should be attached once at the payload level instead --
    see SAFE_WORDING_DISCLAIMER). Called by every narrative-producing tool
    before it returns text -- never rely on the LLM prompt alone."""
    if not text:
        return SAFE_WORDING_DISCLAIMER if append_disclaimer else text

    filtered = text
    substitutions = 0
    for pattern in _ASSURANCE_WORDS:
        filtered, n = re.subn(pattern, "", filtered, flags=re.IGNORECASE)
        substitutions += n
    for pattern, replacement in _SAFE_WORDING_RULES:
        filtered, n = re.subn(pattern, replacement, filtered, flags=re.IGNORECASE)
        substitutions += n

    if substitutions:
        # An unusually high count on one run is itself a signal the
        # underlying narrative-generation prompt is drifting toward
        # assurance language -- log, never silently drop.
        logger.info("apply_safe_wording: %d substitution(s) made", substitutions)

    filtered = re.sub(r"[ \t]{2,}", " ", filtered).strip()

    if append_disclaimer:
        filtered = f"{filtered} {SAFE_WORDING_DISCLAIMER}" if filtered else SAFE_WORDING_DISCLAIMER

    return filtered


# ---- from backend/tools/chat/_shared.py ----
def require_file(path: str, label: str) -> str:
    if not path or not Path(path).exists():
        raise PipelineFileError(str(path), label)
    return path


# ---- from backend/tools/comparison/_shared.py ----
def _classify_fsli(row):
    """Maps a canonical TB row to a (FS Head, FSLI, Note) triple derived directly
    from main_head/sub_head_1/sub_head_2 — there is no persisted hierarchy_path or
    per-note override table in the new canonical schema."""
    status = str(row.get("mapped_status") or "").upper()
    if status != MAPPED_STATUS_MAPPED:
        return "Unmapped", "Unmapped", str(row.get("sub_head_2") or "")
    fs_head = str(row.get("main_head") or "Unmapped").strip() or "Unmapped"
    fsli = str(row.get("sub_head_1") or row.get("sub_head_2") or "Unclassified").strip()
    note = str(row.get("sub_head_2") or "")
    return fs_head, fsli, note

def _load_canonical_tb_for_report(canonical_path):
    """Loads canonical_tb.parquet, coerces numerics, adds report_fs_head/report_fsli/report_note."""
    df = pl.read_parquet(canonical_path)
    if "gl_code" in df.columns:
        df = df.filter(pl.col("gl_code").is_not_null())
    df = df.with_columns(
        [
            (
                pl.col(c).cast(pl.Float64, strict=False).fill_null(0.0).alias(c)
                if c in df.columns
                else pl.lit(0.0).alias(c)
            )
            for c in ["opening_balance", "debit", "credit", "closing_balance"]
        ]
    )
    classified = [_classify_fsli(r) for r in df.iter_rows(named=True)]
    df = df.with_columns(
        [
            pl.Series("report_fs_head", [c[0] for c in classified]),
            pl.Series("report_fsli", [c[1] for c in classified]),
            pl.Series("report_note", [c[2] for c in classified]),
        ]
    )
    if "business area" not in df.columns:
        df = df.with_columns(pl.lit("").alias("business area"))
    return df

def _fy_label(tb_metadata_path, fallback):
    """Extracts an 'FY 2025-26' style label from a tb_metadata.json's source_file name."""
    import json
    try:
        with open(tb_metadata_path, "r") as f:
            meta = json.load(f)
        src = meta.get("source_file", "")
        m = re.search(r"FY\s*(\d{2})[-_](\d{2})", src, re.IGNORECASE)
        if m:
            return f"FY 20{m.group(1)}-{m.group(2)}"
    except Exception:
        pass
    return fallback

def _load_canonical_tb(out_dir, filename="canonical_tb.parquet"):
    """Loads a canonical TB parquet with numeric coercion; returns None if absent."""
    p = Path(out_dir) / filename
    if not p.exists():
        return None
    try:
        df = pl.read_parquet(p)
        df = df.with_columns(
            [
                pl.col(col).cast(pl.Float64, strict=False).fill_null(0.0)
                for col in ("opening_balance", "closing_balance", "debit", "credit")
                if col in df.columns
            ]
        )
        return df
    except Exception:
        return None

def _concentration_rows_from_canonical(df, threshold_pct=5.0, limit=15):
    """Accounts individually exceeding threshold_pct of their FS Head's total absolute closing balance."""
    if df is None or df.is_empty() or "main_head" not in df.columns:
        return []
    head_totals = dict(
        df.group_by("main_head").agg(pl.col("closing_balance").abs().sum().alias("total")).iter_rows()
    )
    rows = []
    for r in df.iter_rows(named=True):
        head = str(r.get("main_head", "") or "")
        total = head_totals.get(head, 0.0)
        if not total:
            continue
        cb = float(r.get("closing_balance", 0.0))
        pct = abs(cb) / total * 100
        if pct >= threshold_pct:
            rows.append({
                "gl_code": r.get("gl_code", ""),
                "gl_name": r.get("gl_name", ""),
                "fs_head": head,
                "closing": cb,
                "pct": pct,
            })
    rows.sort(key=lambda x: x["pct"], reverse=True)
    return rows[:limit]

def _dormant_rows_from_canonical(df, limit=15):
    """Accounts with zero debit/credit movement in the period but a non-zero closing balance."""
    if df is None or df.is_empty() or not {"debit", "credit", "closing_balance"}.issubset(set(df.columns)):
        return []
    dormant = df.filter((pl.col("debit") == 0) & (pl.col("credit") == 0) & (pl.col("closing_balance") != 0))
    if dormant.is_empty():
        return []
    dormant = dormant.with_columns(pl.col("closing_balance").abs().alias("_abs")).sort("_abs", descending=True)
    return [
        {
            "gl_code": r.get("gl_code", ""),
            "gl_name": r.get("gl_name", ""),
            "fs_head": r.get("main_head", ""),
            "closing": float(r.get("closing_balance", 0.0)),
        }
        for r in dormant.head(limit).iter_rows(named=True)
    ]

_TITLE_FONT = Font(bold=True, size=16, color="FF1F3864")

_SUBTITLE_FONT = Font(size=10, color="FF595959")

_SECTION_FONT = Font(bold=True, size=10, color="FF44546A")

_TBL_HDR_FILL = PatternFill("solid", fgColor="FF1F3864")

_TBL_HDR_FONT = Font(bold=True, size=10, color="FFFFFFFF")

_ZEBRA_FILL = PatternFill("solid", fgColor="FFF2F2F2")

_THIN_SIDE = Side(style="thin")

_CELL_BORDER = Border(left=_THIN_SIDE, right=_THIN_SIDE, top=_THIN_SIDE, bottom=_THIN_SIDE)

_ACC_FMT = r'#,##0;\(#,##0\);\-'

_PCT_FMT = r'0.00\%'

def _write_sheet_title(ws, title, subtitle, span_cols):
    ws.cell(row=1, column=1, value=title).font = _TITLE_FONT
    ws.merge_cells(start_row=1, start_column=1, end_row=1, end_column=max(span_cols, 1))
    if subtitle:
        ws.cell(row=2, column=1, value=subtitle).font = _SUBTITLE_FONT
        ws.merge_cells(start_row=2, start_column=1, end_row=2, end_column=max(span_cols, 1))

def _write_section_header(ws, row, text):
    ws.cell(row=row, column=1, value=text).font = _SECTION_FONT
    return row + 1

def _write_table(ws, start_row, headers, rows, formats=None):
    for j, h in enumerate(headers, start=1):
        c = ws.cell(row=start_row, column=j, value=h)
        c.font = _TBL_HDR_FONT
        c.fill = _TBL_HDR_FILL
        c.border = _CELL_BORDER
        c.alignment = Alignment(horizontal="center", vertical="center")
    for i, row_vals in enumerate(rows):
        r = start_row + 1 + i
        zebra = (i % 2 == 1)
        for j, val in enumerate(row_vals, start=1):
            c = ws.cell(row=r, column=j, value=val)
            c.border = _CELL_BORDER
            c.font = Font(size=10)
            if zebra:
                c.fill = _ZEBRA_FILL
            fmt = formats[j - 1] if formats and j - 1 < len(formats) else None
            if fmt:
                c.number_format = fmt
                c.alignment = Alignment(horizontal="right")
            else:
                c.alignment = Alignment(horizontal="left")
    return start_row + 1 + len(rows)

def _set_col_widths(ws, widths):
    for col_letter, width in widths.items():
        ws.column_dimensions[col_letter].width = width

_SEVERITY_COLORS___shared = {
    "CRITICAL": RGBColor(0xC0, 0x00, 0x00),
    "HIGH": RGBColor(0xE0, 0x00, 0x00),
    "MEDIUM": RGBColor(0xE8, 0x7C, 0x00),
    "MED": RGBColor(0xE8, 0x7C, 0x00),
    "LOW": RGBColor(0xC9, 0xA6, 0x00),
    "INFORMATION REQUEST": RGBColor(0x1A, 0x1A, 0x1A),
}

_NUMBER_WORDS = {1: "One", 2: "Two", 3: "Three", 4: "Four", 5: "Five",
                  6: "Six", 7: "Seven", 8: "Eight", 9: "Nine", 10: "Ten"}

def _apply_report_styles(doc):
    """Applies the firm's customised TB audit report typography — Times New Roman
    throughout (18pt dark blue title, 16/14/12pt black headings, 12pt body)."""
    normal = doc.styles["Normal"]
    normal.font.name = "Times New Roman"
    normal.font.size = Pt(12)

    try:
        body = doc.styles["Body Text"]
        body.font.name = "Times New Roman"
        body.font.size = Pt(12)
    except KeyError:
        pass

    try:
        list_bullet = doc.styles["List Bullet"]
        list_bullet.font.name = "Times New Roman"
        list_bullet.font.size = Pt(12)
    except KeyError:
        pass

    title = doc.styles["Title"]
    title.font.name = "Times New Roman"
    title.font.size = Pt(18)
    title.font.bold = True
    title.font.color.rgb = RGBColor(0x17, 0x36, 0x5D)

    heading_color = RGBColor(0x00, 0x00, 0x00)
    for name, size in (("Heading 1", 16), ("Heading 2", 14), ("Heading 3", 12)):
        try:
            style = doc.styles[name]
        except KeyError:
            continue
        style.font.name = "Times New Roman"
        style.font.size = Pt(size)
        style.font.bold = True
        style.font.color.rgb = heading_color

def _add_page_number_field___shared(paragraph):
    """Inserts a Word PAGE field (auto-updating page number) into a paragraph."""
    from docx.oxml import OxmlElement
    from docx.oxml.ns import qn

    run = paragraph.add_run()
    run.font.size = Pt(9)
    run.font.name = "Times New Roman"
    fld_begin = OxmlElement("w:fldChar")
    fld_begin.set(qn("w:fldCharType"), "begin")
    instr = OxmlElement("w:instrText")
    instr.set(qn("xml:space"), "preserve")
    instr.text = "PAGE"
    fld_end = OxmlElement("w:fldChar")
    fld_end.set(qn("w:fldCharType"), "end")
    run._r.append(fld_begin)
    run._r.append(instr)
    run._r.append(fld_end)

def _setup_page_layout___shared(doc, header_left: str, header_right: str):
    """Applies page setup — Portrait A4, 1.0in margins — plus a header (left:
    generation date-time, right: entity/year) and a footer with a centred,
    auto-numbered page count starting at 1."""
    from docx.enum.section import WD_ORIENT
    from docx.enum.text import WD_ALIGN_PARAGRAPH, WD_TAB_ALIGNMENT
    from docx.oxml import OxmlElement
    from docx.oxml.ns import qn
    from docx.shared import Inches, Mm

    section = doc.sections[0]
    section.orientation = WD_ORIENT.PORTRAIT
    section.page_width = Mm(210)
    section.page_height = Mm(297)
    section.top_margin = Inches(1.0)
    section.bottom_margin = Inches(1.0)
    section.left_margin = Inches(1.0)
    section.right_margin = Inches(1.0)
    section.header_distance = Inches(0.3)
    section.footer_distance = Inches(0.3)

    sect_pr = section._sectPr
    pg_num_type = OxmlElement("w:pgNumType")
    pg_num_type.set(qn("w:start"), "1")
    sect_pr.append(pg_num_type)

    usable_width = section.page_width - section.left_margin - section.right_margin

    header = section.header
    header.is_linked_to_previous = False
    hp = header.paragraphs[0] if header.paragraphs else header.add_paragraph()
    hp.text = ""
    hp.paragraph_format.tab_stops.add_tab_stop(usable_width, WD_TAB_ALIGNMENT.RIGHT)
    run_left = hp.add_run(header_left)
    run_left.font.size = Pt(9)
    run_left.font.name = "Times New Roman"
    hp.add_run("\t")
    run_right = hp.add_run(header_right)
    run_right.font.size = Pt(9)
    run_right.font.name = "Times New Roman"
    run_right.bold = True

    footer = section.footer
    footer.is_linked_to_previous = False
    fp = footer.paragraphs[0] if footer.paragraphs else footer.add_paragraph()
    fp.text = ""
    fp.alignment = WD_ALIGN_PARAGRAPH.CENTER
    _add_page_number_field___shared(fp)

def _docx_add_table___shared(doc, headers, rows, cell_pt=8, header_pt=10):
    """Adds a Table Grid table with a bold header row, matching the template's table styling."""
    if not rows:
        doc.add_paragraph("No data available for this table.", style="Body Text")
        return None
    table = doc.add_table(rows=1, cols=len(headers))
    table.style = "Table Grid"
    for i, h in enumerate(headers):
        cell = table.rows[0].cells[i]
        cell.text = ""
        run = cell.paragraphs[0].add_run(str(h))
        run.bold = True
        run.font.size = Pt(header_pt)
        run.font.name = "Segoe UI"
    for row_vals in rows:
        row = table.add_row()
        for i, v in enumerate(row_vals):
            cell = row.cells[i]
            cell.text = ""
            run = cell.paragraphs[0].add_run(str(v))
            run.font.size = Pt(cell_pt)
            run.font.name = "Segoe UI"
    doc.add_paragraph("", style="Body Text")
    return table

def _docx_add_note(doc, text, style="Body Text"):
    """Adds an italicised note paragraph."""
    p = doc.add_paragraph(style=style)
    run = p.add_run(text)
    run.italic = True
    run.font.color.rgb = RGBColor(0x00, 0x00, 0x00)

def _docx_add_severity_heading___shared(doc, prefix: str, severity: str, title: str, level: int = 2):
    """Adds a Heading-style paragraph where the '[SEVERITY]' token is colour-coded."""
    style_name = f"Heading {level}"
    h = doc.add_paragraph(style=style_name)
    h.add_run(f"{prefix}. [")
    sev_run = h.add_run(severity)
    sev_run.font.color.rgb = _SEVERITY_COLORS___shared.get(severity.upper(), RGBColor(0x00, 0x00, 0x00))
    h.add_run(f"] {title}")
    return h

def _docx_add_subtitle(doc, text):
    """Adds a small grey subtitle line beneath the report title (period/date range)."""
    p = doc.add_paragraph()
    run = p.add_run(text)
    run.font.name = "Times New Roman"
    run.font.size = Pt(11)
    run.font.color.rgb = RGBColor(0x7F, 0x7F, 0x7F)
    run.italic = True

def _docx_add_notice(doc, text):
    """Adds the small grey 'Notice to the reader' paragraph beneath the title block."""
    p = doc.add_paragraph()
    run = p.add_run(text)
    run.font.name = "Times New Roman"
    run.font.size = Pt(10)
    run.font.color.rgb = RGBColor(0x59, 0x59, 0x59)

def _docx_add_lead_bullet(doc, lead, rest):
    """Adds a bulleted line with a bold navy lead phrase, e.g. 'Concentration — <detail>'."""
    p = doc.add_paragraph(style="List Bullet")
    lead_run = p.add_run(f"{lead} — ")
    lead_run.bold = True
    lead_run.font.color.rgb = RGBColor(0x17, 0x36, 0x5D)
    p.add_run(rest)

def _write_limitations_section(doc, source_desc: str, comparative: bool = False):
    """Writes the 'Limitations & No-Opinion Statement' bullet list."""
    doc.add_heading("24. Limitations & No-Opinion Statement", level=1)
    scope = "the two trial balance files and the grouping workbook supplied" if comparative else "the trial balance file and the grouping workbook supplied"
    doc.add_paragraph(f"This review is mechanical and confined entirely to {scope}:")
    bullets = [
        "No assurance opinion — it does not constitute an audit, review, or any other assurance "
        "engagement under any professional standard.",
        "No corroboration performed — no vouching, confirmation, analytical corroboration against "
        "external data, or management inquiry was performed.",
        "Grouping not independently verified — classifications rely on the GL Grouping workbook as "
        "supplied and have not been independently verified against statutory financial statements.",
    ]
    if not comparative:
        bullets.append(
            "Single-period scope — with only one period available, this review cannot distinguish "
            "ordinary year-on-year change from a genuine anomaly — a comparative (PY vs CY) review is "
            "recommended once a prior-period file is available."
        )
    bullets.append("No rescaling — figures are presented exactly as extracted from source, unscaled.")
    for b in bullets:
        doc.add_paragraph(b, style="List Bullet")
    doc.add_paragraph("This document should be read alongside, not instead of, full substantive audit procedures.")




# ============================================================================
# DOMAIN: canonical
# ============================================================================

def _fallback_classify(gl_code: str, gl_name: str, standard: str):
    """Best-effort main_head guess for GL rows the grouping join left
    UNMATCHED, via GL-code range keywords then GL-name keywords, snapped
    against the closed taxonomy's own main_head vocabulary (find_main_head)
    so a fallback classification still lands on a real Schedule III head
    instead of free text. Returns {"bs_pl", "main_head", "account_type"} or
    None if nothing resolves."""
    gl_code = str(gl_code) if gl_code else ""
    gl_name = str(gl_name).lower() if gl_name else ""

    candidates = []
    if gl_code.isdigit() and len(gl_code) >= 5:
        candidates.append(
            {"1": "Non-current assets", "2": "Non-current liabilities", "3": "Equity",
             "4": "Revenue from operations", "5": "Expenses"}.get(gl_code[0])
        )

    assets_kw = ["cash", "bank", "receivable", "inventory", "asset", "prepaid", "advance", "deposit", "cwip"]
    liab_kw = ["payable", "loan", "borrowing", "provision", "liability", "tax", "duty", "creditor"]
    rev_kw = ["sales", "revenue", "income", "interest received"]
    exp_kw = ["expense", "cost", "purchase", "salary", "wage", "depreciation", "fee", "rent", "repair", "consumption"]
    eq_kw = ["capital", "reserve", "surplus", "retained earning"]
    if any(kw in gl_name for kw in assets_kw):
        candidates.append("Non-current assets")
        candidates.append("Current assets")
    if any(kw in gl_name for kw in liab_kw):
        candidates.append("Non-current liabilities")
        candidates.append("Current liabilities")
    if any(kw in gl_name for kw in rev_kw):
        candidates.append("Revenue from operations")
    if any(kw in gl_name for kw in exp_kw):
        candidates.append("Expenses")
    if any(kw in gl_name for kw in eq_kw):
        candidates.append("Equity")

    for candidate in candidates:
        if not candidate:
            continue
        match = find_main_head(candidate, standard)
        if match:
            return {
                "bs_pl": match["bs_pl"],
                "main_head": match["main_head"],
                "account_type": derive_account_type(match["bs_pl"], match["main_head"], standard),
            }
    return None

@pipeline_tool("build_canonical_tb", domain="canonical")
def build_canonical_tb(
    manifest_file: str,
    ground_truth_file: str,
    metadata_file: str = None,
    output_dir: str = None,
    llm_client=None,
    tb_excel_path: str = None,
    tb_doc_id: str = None,
    company_details: dict = None,
):
    """Constructs the Canonical Trial Balance by combining Parsed Trial Balance and
    Grouping Ground Truth. Writes exactly CANONICAL_TB_ALL_COLUMNS to canonical_tb.parquet.
    Pass company_details ({company_name, fy_start, fy_end, financial_year}) so tb_doc_id
    matches the deterministic company+FY scheme already used by MAIN documents; without
    it, tb_doc_id falls back to a hash of tb_excel_path's bytes."""
    errors = []
    artifacts = []

    manifest_path = Path(manifest_file)
    if not manifest_path.exists():
        errors.append({"type": "FileNotFoundError", "file": manifest_file})
        return {"execution_status": "FAILED", "errors": errors, "message": "Manifest file not found."}

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    worksheets = manifest.get("worksheets", [])
    tb_ws = next((ws for ws in worksheets if ws.get("role") == "TRIAL_BALANCE"), None)

    if not tb_ws:
        errors.append({"type": "DataError", "error": "No TRIAL_BALANCE worksheets in manifest"})
        return {"execution_status": "FAILED", "errors": errors, "message": "Manifest missing TRIAL_BALANCE worksheets."}

    tb_path = Path(tb_ws["parquet"])
    map_file = tb_ws.get("column_mapping_file")

    if not map_file:
        errors.append({"type": "DataError", "error": "Missing column_mapping_file"})
        return {"execution_status": "FAILED", "errors": errors, "message": "Manifest missing column_mapping_file for TRIAL_BALANCE."}

    gt_path = Path(ground_truth_file)

    if not tb_path.exists():
        errors.append({"type": "FileNotFoundError", "file": str(tb_path)})
        return {"execution_status": "FAILED", "errors": errors, "message": "TB file not found."}
    if not gt_path.exists():
        errors.append({"type": "FileNotFoundError", "file": str(gt_path)})
        return {"execution_status": "FAILED", "errors": errors, "message": "Ground truth file not found."}

    tb_df = pl.read_parquet(tb_path)
    gt_df = pl.read_parquet(gt_path)

    if tb_df.is_empty():
        errors.append({"type": "DataError", "error": "Empty TB file"})
        return {"execution_status": "FAILED", "errors": errors, "message": "TB file is empty."}

    map_path = Path(map_file)
    if not map_path.exists():
        errors.append({"type": "FileNotFoundError", "file": str(map_path)})
        return {"execution_status": "FAILED", "errors": errors, "message": "Column mapping file not found."}

    with open(map_path, "r", encoding="utf-8") as f:
        mapping = json.load(f)

    gl_code_col = mapping.get("gl_code")
    if not gl_code_col or gl_code_col not in tb_df.columns:
        errors.append({"type": "InvalidColumnError", "error": "MISSING_GL_CODE_COLUMN"})
        return {
            "execution_status": "FAILED",
            "errors": errors,
            "message": f"GL code column missing or invalid. Mapping: {mapping}. Columns: {tb_df.columns}",
        }

    # Filter out subtotal/total rows before canonicalization to avoid duplicate GL errors
    gl_name_col = mapping.get("gl_name")
    if gl_name_col and gl_name_col in tb_df.columns:
        name_lower = pl.col(gl_name_col).cast(pl.Utf8).str.to_lowercase().str.strip_chars()
        mask = ~pl.any_horizontal([name_lower.str.starts_with(t) for t in _TOTAL_PREFIXES])
        tb_df = tb_df.filter(mask)

    missing_columns = []
    canonical_source_cols = ["gl_name", "opening_balance", "debit", "credit", "closing_balance"]

    tb_df = tb_df.with_columns(
        [pl.col(gl_code_col).alias("original_gl_code"), pl.col(gl_code_col).alias("gl_code")]
    )

    for c_col in canonical_source_cols:
        orig_col = mapping.get(c_col)
        if orig_col and orig_col in tb_df.columns:
            tb_df = tb_df.with_columns(pl.col(orig_col).alias(c_col))
        else:
            tb_df = tb_df.with_columns(pl.lit(None).alias(c_col))
            missing_columns.append(c_col)

    tb_df = tb_df.with_columns(
        pl.col("original_gl_code").map_elements(_normalize_gl_code, return_dtype=pl.Utf8).alias("canonical_gl_code")
    )

    if "gl_code" not in gt_df.columns:
        errors.append({"type": "SchemaError", "error": "INVALID_GROUND_TRUTH_SCHEMA"})
        return {"execution_status": "FAILED", "errors": errors, "message": "Ground truth missing gl_code."}

    if "canonical_gl_code" not in gt_df.columns:
        gt_df = gt_df.with_columns(
            pl.col("gl_code").map_elements(_normalize_gl_code, return_dtype=pl.Utf8).alias("canonical_gl_code")
        )

    tb_vc = (
        tb_df.filter(pl.col("canonical_gl_code").is_not_null())
        .group_by("canonical_gl_code").agg(pl.len().alias("n"))
    )
    if not tb_vc.is_empty() and tb_vc["n"].max() > 1:
        duplicates = tb_vc.filter(pl.col("n") > 1)["canonical_gl_code"].to_list()
        errors.append({"type": "IntegrityError", "error": "DUPLICATE_GL_CODE_IN_TB", "details": duplicates[:5]})
        return {"execution_status": "FAILED", "errors": errors, "message": "Duplicate GL codes found in TB."}

    gt_vc = (
        gt_df.filter(pl.col("canonical_gl_code").is_not_null())
        .group_by("canonical_gl_code").agg(pl.len().alias("n"))
    )
    if not gt_vc.is_empty() and gt_vc["n"].max() > 1:
        duplicates = gt_vc.filter(pl.col("n") > 1)["canonical_gl_code"].to_list()
        errors.append({"type": "Warning", "error": "DUPLICATE_GL_CODE_IN_GROUPING", "details": duplicates[:5]})
        # Auto-heal: keep the first occurrence of duplicated canonical GL codes to prevent join explosion
        gt_df = gt_df.unique(subset=["canonical_gl_code"], keep="first")

    grouping_join_cols = ["canonical_gl_code", "bs_pl", "main_head", "sub_head_1", "sub_head_2", "account_type", "mapped_status"]
    gt_df = gt_df.with_columns(
        [pl.lit(None).alias(col) for col in grouping_join_cols if col not in gt_df.columns]
    )
    gt_join = gt_df.select(grouping_join_cols)

    canonical_tb = tb_df.join(gt_join, on="canonical_gl_code", how="left")

    # Standard (AS/IND_AS) resolved by extract_grouping_mapping, persisted
    # alongside the ground truth it produced -- read it back so the fallback
    # pass snaps against the same taxonomy, not a mismatched default.
    standard = "IND_AS"
    structure_path = gt_path.parent / "grouping_structure.json"
    if structure_path.exists():
        try:
            with open(structure_path, "r", encoding="utf-8") as f:
                standard = json.load(f).get("standard") or standard
        except (json.JSONDecodeError, OSError):
            pass

    # Fallback mapping: GL rows the grouping join left UNMATCHED/UNMAPPED get a
    # best-effort classification from GL-code range / GL-name keywords, snapped
    # against the closed taxonomy's own main_head vocabulary (never invented text).
    # Rows with no grouping-join match at all (mapped_status is null post-join)
    # were never even attempted -- UNMATCHED. Rows the grouping join resolved
    # to UNMAPPED already went through taxonomy snapping in
    # extract_grouping_mapping and failed there. Both cases are handled in one
    # pass: `was_unmatched` captures the pre-fallback state so a fallback
    # failure preserves the distinction instead of collapsing both into one
    # status -- same outcome as the old two-pass (tag-then-fallback) version.
    fallback_rows = []
    for row in canonical_tb.iter_rows(named=True):
        row = dict(row)
        if row.get("mapped_status") != MAPPED_STATUS_MAPPED:
            was_unmatched = row.get("mapped_status") is None
            match = _fallback_classify(row.get("canonical_gl_code"), row.get("gl_name"), standard)
            if match:
                row["bs_pl"] = match["bs_pl"]
                row["account_type"] = match["account_type"]
                if not row.get("main_head"):
                    row["main_head"] = match["main_head"]
                row["mapped_status"] = MAPPED_STATUS_MAPPED
            else:
                row["mapped_status"] = MAPPED_STATUS_UNMATCHED if was_unmatched else MAPPED_STATUS_UNMAPPED
        fallback_rows.append(row)
    canonical_tb = pl.DataFrame(fallback_rows, schema=canonical_tb.schema)

    # tb_doc_id: explicit override > company+FY scheme (matches MAIN documents)
    # > hash of original TB workbook bytes > hash of TB parquet bytes.
    company_details = company_details or {}
    fallback_bytes = (
        Path(tb_excel_path).read_bytes()
        if tb_excel_path and Path(tb_excel_path).exists()
        else tb_path.read_bytes()
    )
    resolved_tb_doc_id = tb_doc_id or build_tb_doc_id(
        company_name=company_details.get("company_name"),
        fy_start=company_details.get("fy_start"),
        fy_end=company_details.get("fy_end"),
        financial_year=company_details.get("financial_year"),
        fallback_bytes=fallback_bytes,
    )
    canonical_tb = canonical_tb.with_columns(pl.lit(resolved_tb_doc_id).alias("tb_doc_id"))

    canonical_tb = canonical_tb.with_columns(
        [pl.col(col).cast(pl.Float64, strict=False).fill_null(0.0) for col in CANONICAL_TB_NUMERIC_COLUMNS]
    )

    canonical_tb = canonical_tb.filter(pl.col("gl_code").is_not_null())

    # custom_field_1/2/3 are reserved/not-yet-defined -- passed through verbatim
    # if the caller supplied them via company_details, else left null. No
    # business logic assigned here; this is passthrough plumbing only.
    canonical_tb = canonical_tb.with_columns(
        [pl.lit(company_details.get(col)).alias(col) for col in CANONICAL_TB_OPTIONAL_COLUMNS]
    )

    # Exactly the 13 required canonical columns plus the 3 optional passthrough
    # columns, in canonical order -- no hierarchy_path/hierarchy_level/
    # mapping_confidence/parent_line_item/fs_head/source_sheet/source_row.
    canonical_tb = canonical_tb.select(CANONICAL_TB_ALL_COLUMNS)

    schema_errors, canonical_tb = validate_dataframe_schema(canonical_tb, "build_canonical_tb")
    if schema_errors:
        errors.extend(schema_errors)

    out_dir = resolve_output_dir(output_dir)
    os.makedirs(out_dir, exist_ok=True)

    parquet_path = out_dir / "canonical_tb.parquet"
    canonical_tb.write_parquet(parquet_path)
    artifacts.append(str(parquet_path.resolve()))

    total_rows = len(canonical_tb)
    mapped_rows = int((canonical_tb["mapped_status"] == MAPPED_STATUS_MAPPED).sum())
    unmapped_rows = total_rows - mapped_rows
    mapping_pct = (mapped_rows / total_rows * 100) if total_rows > 0 else 0

    summary = {
        "tb_doc_id": resolved_tb_doc_id,
        "total_tb_rows": total_rows,
        "mapped_rows": mapped_rows,
        "unmapped_rows": unmapped_rows,
        "mapping_percentage": round(mapping_pct, 2),
        "missing_columns": missing_columns,
    }

    summary_path = out_dir / "mapping_summary.json"
    with open(summary_path, "w", encoding="utf-8") as f:
        json.dump(summary, f, indent=4)
    artifacts.append(str(summary_path.resolve()))

    return {
        "execution_status": "SUCCESS",
        "pipeline_status": "SUCCESS",
        "can_continue": True,
        "message": f"Successfully built canonical TB. Mapped {mapped_rows} GL codes. Coverage: {mapping_pct:.1f}%",
        "artifacts": artifacts,
        "errors": errors,
    }


GRADE_INFO_REQUEST = "Information request only"

GRADE_LOW = "Low"

GRADE_MEDIUM = "Medium"

GRADE_HIGH = "High"

@pipeline_tool("build_data_sufficiency_grade", domain="canonical")
def build_data_sufficiency_grade(
    layer1_results_file: str,
    canonical_tb_file: str = None,
    comparative_data_present: bool = False,
    output_dir: str = None,
) -> dict:
    """Grade Trial Balance data sufficiency (Low/Medium/High/Information request only) and list weakened/unavailable checks."""
    results_path = Path(layer1_results_file)
    if not results_path.exists():
        raise PipelineFileError(str(results_path), "Layer-1 validation results")

    with open(results_path, "r", encoding="utf-8") as f:
        layer1_results = json.load(f)

    halted_blocking = [r for r in layer1_results if r.get("status") == "HALTED" and r.get("severity") == "Blocking"]
    skipped = [r for r in layer1_results if r.get("status") == "SKIPPED"]

    mapped_pct = None
    if canonical_tb_file:
        canon_path = Path(canonical_tb_file)
        if canon_path.exists():
            canon_df = pl.read_parquet(canon_path)
            if not canon_df.is_empty() and "mapped_status" in canon_df.columns:
                mapped_pct = float((canon_df["mapped_status"] == MAPPED_STATUS_MAPPED).sum()) / canon_df.height * 100

    _MAPPED_PCT_HIGH, _MAPPED_PCT_MEDIUM = mapping_confidence_thresholds()

    if halted_blocking:
        grade = GRADE_INFO_REQUEST
        rationale = (
            f"{len(halted_blocking)} Blocking rule(s) HALTED "
            f"({', '.join(r['rule'] for r in halted_blocking)}) -- the trial balance does not "
            "foot internally; substantive analysis should not proceed until corrected."
        )
    elif mapped_pct is None:
        grade = GRADE_LOW
        rationale = "No canonical/grouping-mapped Trial Balance supplied -- only raw Layer-1 screens can run."
    elif mapped_pct >= _MAPPED_PCT_HIGH and comparative_data_present:
        grade = GRADE_HIGH
        rationale = f"{mapped_pct:.0f}% of GL accounts mapped to a chart of accounts, plus comparative-period data supplied."
    elif mapped_pct >= _MAPPED_PCT_MEDIUM:
        grade = GRADE_MEDIUM
        rationale = f"{mapped_pct:.0f}% of GL accounts mapped to a chart of accounts."
    else:
        grade = GRADE_LOW
        rationale = (
            f"Only {mapped_pct:.0f}% of GL accounts mapped to a chart of accounts -- most "
            "group/relationship checks cannot run reliably."
        )

    disabled_checks = [f"{r['rule']} ({r['rule_name']}): {r['message']}" for r in skipped]
    if not comparative_data_present:
        disabled_checks.append(
            "Movement/variance year-on-year checks -- no comparative-period data supplied."
        )

    out_dir = resolve_output_dir(output_dir)
    out_dir.mkdir(parents=True, exist_ok=True)
    out_path = out_dir / "data_sufficiency.json"
    payload = {
        "grade": grade,
        "rationale": rationale,
        "mapped_percentage": mapped_pct,
        "disabled_checks": disabled_checks,
        "halted_blocking_rules": [r["rule"] for r in halted_blocking],
    }
    with open(out_path, "w", encoding="utf-8") as f:
        json.dump(payload, f, indent=4)

    return {
        "execution_status": "SUCCESS",
        "pipeline_status": "SUCCESS",
        "can_continue": True,
        "message": f"Data sufficiency: {grade}. {len(disabled_checks)} check(s) unavailable or weakened.",
        "artifacts": [str(out_path)],
        "errors": [],
        "grade": grade,
    }


_NOT_EVIDENCED = "Not evidenced by any artifact in this run -- confirm against the original export."

def _rule(layer1, rule_id: str) -> dict:
    if not isinstance(layer1, list):
        return {}
    return next((r for r in layer1 if r.get("rule") == rule_id), {})

@pipeline_tool("build_normalisation_note", domain="canonical")
def build_normalisation_note(
    canonical_tb_file: str,
    layer1_results_file: str = None,
    engagement_context_file: str = None,
    grouping_statistics_file: str = None,
    source_file_name: str = None,
    output_dir: str = None,
    **kwargs,
) -> dict:
    """Assemble the normalisation note the specification requires before any audit
    finding: source system and file, sign convention and how it was resolved, currency
    and scale, period, arithmetic residual, rows removed as subtotals, mapped versus
    unmapped account counts, and every caveat that qualifies the figures downstream.

    Built from artifacts the run actually produced, so it records what happened rather
    than what was intended; anything not evidenced is stated as not evidenced. Writes
    normalisation_note.json."""
    out_dir = resolve_output_dir(output_dir)
    out_dir.mkdir(parents=True, exist_ok=True)

    tb_path = Path(canonical_tb_file)
    if not tb_path.exists():
        raise PipelineFileError(str(tb_path), "Canonical TB (supply canonical_tb_file)")

    df = load_canonical_tb(tb_path)
    if df is None:
        raise PipelineFileError(str(tb_path), "Canonical TB could not be parsed")

    warnings, caveats = [], []

    l1_path = Path(layer1_results_file) if layer1_results_file else out_dir / "layer1_results.json"
    layer1 = safe_load_json(l1_path) if l1_path.exists() else None
    if layer1 is None:
        warnings.append(
            "layer1_results.json not available -- sign convention, scale and period could not be "
            "evidenced. Run validate_layer1_tb for a re-performable note."
        )

    ctx_path = (Path(engagement_context_file) if engagement_context_file
                else out_dir / "engagement_context.json")
    ctx = safe_load_json(ctx_path) if ctx_path.exists() else {}

    # ── sign convention (TB-000) ──────────────────────────────────────────────
    tb000 = _rule(layer1, "TB-000")
    sign = {
        "assumed_convention": "closing_balance is debit-positive",
        "verification_rule": "TB-000 (normal-side keyword anchors)",
        "status": tb000.get("status", "NOT_RUN"),
        "finding": tb000.get("message", _NOT_EVIDENCED),
    }
    if tb000.get("status") == "WARNING":
        caveats.append(
            "Sign convention was not confirmed by TB-000. Every downstream figure assumes "
            "debit-positive; if the export uses the opposite convention, variance direction and "
            "abnormal-sign findings are inverted."
        )

    # ── currency and scale (TB-026) ───────────────────────────────────────────
    tb026 = _rule(layer1, "TB-026")
    scale = {
        "currency": ctx.get("currency", "unknown"),
        "scale": ctx.get("scale", "unknown"),
        "verification_rule": "TB-026 (currency and unit declared once and consistent)",
        "status": tb026.get("status", "NOT_RUN"),
        "finding": tb026.get("message", _NOT_EVIDENCED),
        "rescaling_applied": "none -- figures are used exactly as supplied (sec 4.1)",
    }
    if tb026.get("status") != "PASS":
        caveats.append(
            "Currency and unit were not confirmed. Materiality, ratios and risk ranking are all "
            "scale-sensitive; a figure stated in thousands but read as units is wrong by 1,000x. "
            "sec 3.2 says final materiality should not be computed until scale is confirmed."
        )

    # ── period and source system ──────────────────────────────────────────────
    tb025, tb029 = _rule(layer1, "TB-025"), _rule(layer1, "TB-029")
    provenance = {
        "source_file": source_file_name or ctx.get("source_system") or _NOT_EVIDENCED,
        "source_system": ctx.get("source_system", "unknown"),
        "period_end": ctx.get("period_end") or _NOT_EVIDENCED,
        "period_rule_status": tb025.get("status", "NOT_RUN"),
        "period_finding": tb025.get("message", _NOT_EVIDENCED),
        "extraction_trail_rule_status": tb029.get("status", "NOT_RUN"),
        "extraction_trail_finding": tb029.get("message", _NOT_EVIDENCED),
        "consolidation_basis": ctx.get("consolidation_basis", "unknown"),
    }
    if tb029.get("status") != "PASS":
        caveats.append(
            "Source system and extraction trail are not identifiable, so this note cannot be "
            "fully re-performed against the original export -- the test sec 4.6 sets for it."
        )

    # ── arithmetic integrity ──────────────────────────────────────────────────
    totals = control_totals(df) or {}
    integrity_rules = {
        rid: {"status": _rule(layer1, rid).get("status", "NOT_RUN"),
              "message": _rule(layer1, rid).get("message", _NOT_EVIDENCED)}
        for rid in ("TB-005", "TB-009", "TB-010", "TB-011")
    }
    halted = [rid for rid, r in integrity_rules.items() if r["status"] == "HALTED"]
    if halted:
        caveats.append(
            f"Arithmetic integrity rule(s) {', '.join(halted)} HALTED -- the trial balance does "
            "not foot internally. Substantive analysis should not be relied on until a corrected "
            "export is obtained."
        )

    # ── rows excluded and mapping coverage ────────────────────────────────────
    grp_path = (Path(grouping_statistics_file) if grouping_statistics_file
                else out_dir / "grouping_statistics.json")
    grp = safe_load_json(grp_path) if grp_path.exists() else {}

    status_col = df["mapped_status"].to_list() if "mapped_status" in df.columns else []
    mapped = sum(1 for s in status_col if str(s).upper() == MAPPED_STATUS_MAPPED)
    unmapped = sum(1 for s in status_col if str(s).upper() in (MAPPED_STATUS_UNMAPPED, MAPPED_STATUS_UNMATCHED))
    total_rows = df.height
    mapped_pct = (mapped / total_rows * 100) if total_rows else 0.0

    if mapped_pct < 80:
        caveats.append(
            f"Only {mapped_pct:.0f}% of accounts carry a confirmed FSLI mapping. Relationship, "
            "ratio and counterpart analytics degrade in proportion, and sec 1.2 forbids forcing a "
            "mapping to close the gap -- request the chart of accounts instead."
        )

    transformations = [
        {"step": "Subtotal and total rows removed",
         "detail": grp.get("total_rows_removed", _NOT_EVIDENCED),
         "rationale": "Retaining a subtotal alongside its children double-counts (sec 4.6 step 2)."},
        {"step": "Sign standardisation",
         "detail": sign["assumed_convention"],
         "rationale": "Every downstream rule assumes this convention; TB-000 sanity-checks it."},
        {"step": "Numeric coercion",
         "detail": "opening_balance / debit / credit / closing_balance cast to float, nulls to 0.0",
         "rationale": "Raw exports carry text, blanks and formatted numbers in numeric columns."},
        {"step": "Rescaling",
         "detail": "None applied",
         "rationale": "sec 4.1 -- never silently rescale."},
        {"step": "Ledger separation",
         "detail": ctx.get("consolidation_basis", "unknown"),
         "rationale": "Mixing Ind AS, tax and consolidation ledgers compares unlike balances (sec 4.6 step 5)."},
    ]

    note = {
        "purpose": (
            "Records every transformation applied to the trial balance before analysis, so a "
            "team member can independently re-perform it from the original ERP export "
            "(spec sec 4.6). This note precedes all audit findings (sec 4.2 step 10)."
        ),
        "generated_at": datetime.datetime.now().isoformat(),
        "provenance": provenance,
        "sign_convention": sign,
        "currency_and_scale": scale,
        "arithmetic_integrity": {
            "control_totals": totals,
            "rules": integrity_rules,
            "halted_rules": halted,
        },
        "row_population": {
            "rows_in_canonical_tb": total_rows,
            "mapped_accounts": mapped,
            "unmapped_or_unmatched_accounts": unmapped,
            "mapped_percentage": round(mapped_pct, 2),
            "grouping_statistics": grp or _NOT_EVIDENCED,
        },
        "transformations_applied": transformations,
        "caveats": caveats or ["No qualifying caveats identified from the artifacts available."],
        "knowledge_pack_versions": pack_versions(),
        "re_performance_test": (
            "A reviewer holding the original export should be able to reproduce the canonical TB "
            "row count, control totals and mapped percentage above. If they cannot, this note is "
            "incomplete and the difference must be investigated before relying on any finding."
        ),
        "safe_limitation": SAFE_WORDING_DISCLAIMER,
    }

    out_path = out_dir / "normalisation_note.json"
    with atomic_write(out_path) as tmp:
        Path(tmp).write_text(json.dumps(note, indent=2, default=str), encoding="utf-8")

    return {
        "execution_status": "SUCCESS",
        "pipeline_status": "WARNING" if (caveats and caveats[0] != note["caveats"][0]) or warnings else "SUCCESS",
        "can_continue": True,
        "message": (
            f"Normalisation note: {total_rows} row(s), {mapped_pct:.0f}% mapped, "
            f"{len(halted)} halted integrity rule(s), {len(caveats)} caveat(s) qualifying "
            "downstream figures."
        ),
        "artifacts": [str(out_path.resolve())],
        "errors": [],
        "warnings": warnings,
    }


_SIGN_CONVENTION_MIN_ANCHORS = 3

_SIGN_CONVENTION_AGREEMENT_THRESHOLD = 0.7

def _check_sign_convention(df: pl.DataFrame) -> tuple:
    """TB-000 fallback heuristic: infer whether this file's positive
    closing_balance means debit or credit, via normal-side keyword anchors,
    and sanity-check internal consistency. Never itself a HALT -- this is a
    sanity check on the sign convention already assumed by every other rule
    in this file (closing_balance is debit-positive by construction), not an
    override of it. Returns (status, message)."""
    debit_normal_anchors = debit_anchors()
    credit_normal_anchors = credit_anchors()
    debit_anchored = 0
    debit_positive = 0
    credit_anchored = 0
    credit_negative = 0

    for row in df.iter_rows(named=True):
        name = str(row.get("gl_name") or "").lower()
        if not name:
            continue
        # closing_balance may still be raw/string here -- TB-000 runs before
        # TB-004's numeric coercion (this heuristic only needs sign, not the
        # coerced-with-tolerance value TB-004 produces), so parse defensively
        # rather than assume a numeric type.
        try:
            closing = float(row.get("closing_balance") or 0)
        except (TypeError, ValueError):
            continue
        is_debit = any(kw in name for kw in debit_normal_anchors)
        is_credit = any(kw in name for kw in credit_normal_anchors)
        if is_debit and not is_credit:
            debit_anchored += 1
            if closing > 0:
                debit_positive += 1
        elif is_credit and not is_debit:
            credit_anchored += 1
            if closing < 0:
                credit_negative += 1

    if debit_anchored < _SIGN_CONVENTION_MIN_ANCHORS or credit_anchored < _SIGN_CONVENTION_MIN_ANCHORS:
        return "WARNING", (
            f"Not enough recognizable ledger names to confirm sign convention "
            f"(debit anchors={debit_anchored}, credit anchors={credit_anchored}, need >= {_SIGN_CONVENTION_MIN_ANCHORS} each)."
        )

    debit_agreement = debit_positive / debit_anchored
    credit_agreement = credit_negative / credit_anchored

    if debit_agreement >= _SIGN_CONVENTION_AGREEMENT_THRESHOLD and credit_agreement >= _SIGN_CONVENTION_AGREEMENT_THRESHOLD:
        return "PASS", (
            f"Sign convention: positive = debit (confirmed by {debit_anchored} debit-anchor and "
            f"{credit_anchored} credit-anchor accounts, agreement {debit_agreement:.0%}/{credit_agreement:.0%})."
        )

    inverse_debit_agreement = 1 - debit_agreement
    inverse_credit_agreement = 1 - credit_agreement
    if (
        inverse_debit_agreement >= _SIGN_CONVENTION_AGREEMENT_THRESHOLD
        and inverse_credit_agreement >= _SIGN_CONVENTION_AGREEMENT_THRESHOLD
    ):
        return "WARNING", (
            "Sign convention: this file appears to use the opposite convention (credit-positive/"
            "debit-negative) from what downstream tools assume (debit-positive) -- variance direction "
            "and zero-sum results may be misleading."
        )

    return "WARNING", (
        f"Sign convention could not be confirmed -- debit-anchor agreement {debit_agreement:.0%}, "
        f"credit-anchor agreement {credit_agreement:.0%} -- signs look inconsistent/mixed."
    )

def _extract_tb_sheets_raw(tb_excel_path: str, tb_column_mapping: dict = None) -> dict:
    """
    Loads a TB workbook and returns every TRIAL_BALANCE-classified sheet as one
    concatenated dataframe with standardized columns, before any parquet conversion
    or grouping join happens. Reuses the same header-detection and column-mapping
    utilities process_input_documents uses, without touching that function.

    Per-sheet Excel reading/header-detection and the returned working
    dataframe both run on polars, sharing the same primitives as
    process_input_documents.py.
    """
    path = Path(tb_excel_path)
    ext = _validate_input_file(path)
    workbook = _load_workbook(path, ext)

    sheets_info = _enumerate_sheets(workbook, ext, path)
    if not sheets_info:
        raise ValueError("EMPTY_WORKBOOK")

    classifier = WorksheetClassifier()
    tb_frames = []
    mapping_issues = []

    for sheet_info in sheets_info:
        try:
            df = _extract_sheet_dataframe(workbook, sheet_info["name"], ext, path)
        except Exception:
            continue

        if df.is_empty():
            continue
        # Bail-out check only -- see process_input_documents.py's identical
        # comment for why this must not mutate `df` (a leading blank row has
        # to stay in place for header-row-index detection to count positions
        # the same way the old pandas path did).
        if df.filter(~pl.all_horizontal([pl.col(c).is_null() for c in df.columns])).is_empty():
            continue

        non_null_cols = [c for c in df.columns if df[c].null_count() < df.height]
        if not non_null_cols:
            continue
        df = df.select(non_null_cols)

        data_start = 0
        found = _find_header(df)
        if found:
            header_idx, two_row = found
            header = [_norm___ingest_shared(v) for v in df.row(header_idx)]
            data_start = header_idx + (2 if two_row else 1)

            if two_row:
                sub = [_norm___ingest_shared(v) for v in df.row(header_idx + 1)]
                top = _ffill(header)
                width = max(len(header), len(sub))
                merged = []
                for i in range(width):
                    raw_top = header[i] if i < len(header) else ""
                    sub_i = sub[i] if i < len(sub) else ""
                    if not raw_top and not sub_i:
                        merged.append("")
                        continue
                    top_i = top[i] if i < len(top) else ""
                    merged.append(" ".join(x for x in (top_i, sub_i) if x).strip())
                df = df.rename(dict(zip(df.columns, _dedupe_names(merged))))
            else:
                df = df.rename(dict(zip(df.columns, _dedupe_names(header))))

            df = df.slice(data_start, df.height - data_start)
        else:
            df, _generated = _generate_headers_if_missing(df)

        df = _normalize_duplicate_columns(df)
        df = df.with_row_index("_rownum").with_columns(
            [
                pl.lit(sheet_info["name"]).alias("source_sheet"),
                (pl.col("_rownum") + data_start).alias("source_row"),
            ]
        ).drop("_rownum")

        classification = classifier.classify_worksheet(df)
        if classification["role"] != "TRIAL_BALANCE":
            continue

        mapping = _generate_column_mapping(df, agent_provided_mapping=tb_column_mapping)

        missing_fields = [
            field for field in ("gl_code", "closing_balance")
            if not mapping.get(field) or mapping.get(field) not in df.columns
        ]
        if missing_fields:
            mapping_issues.append({"sheet": sheet_info["name"], "missing_fields": missing_fields})

        def _col(field, default=None):
            col_name = mapping.get(field)
            if col_name and col_name in df.columns:
                return df[col_name].to_list()
            return [default] * df.height

        tb_frames.append(
            pl.DataFrame(
                {
                    "gl_code": _col("gl_code", default=None),
                    "gl_name": _col("gl_name", default=None),
                    "opening_balance": _col("opening_balance", default=0.0),
                    "debit": _col("debit", default=0.0),
                    "credit": _col("credit", default=0.0),
                    "closing_balance": _col("closing_balance", default=0.0),
                    "source_sheet": df["source_sheet"].to_list(),
                    "source_row": df["source_row"].to_list(),
                }
            )
        )

    if not tb_frames:
        raise ValueError("NO_TRIAL_BALANCE_SHEET")

    raw_df = pl.concat(tb_frames, how="vertical_relaxed")

    # Drop trailing total/empty rows: rows with both GL Code and GL Name blank,
    # or blank GL Code paired with a GL Name that reads as a "total" row.
    keep = []
    for row in raw_df.iter_rows(named=True):
        c = str(row.get("gl_code", "")).strip() if row.get("gl_code") is not None else ""
        n = str(row.get("gl_name", "")).strip() if row.get("gl_name") is not None else ""

        is_blank_code = c == "" or c.lower() == "nan"
        is_blank_name = n == "" or n.lower() == "nan"
        is_total_name = "total" in n.lower()

        keep.append(not ((is_blank_code and is_blank_name) or (is_blank_code and is_total_name)))

    filtered_df = raw_df.filter(pl.Series(keep))

    return {"dataframe": filtered_df, "mapping_issues": mapping_issues}

def _extract_tb_rows_from_canonical(canonical_tb_file: str) -> dict:
    """Builds the same working dataframe shape _extract_tb_sheets_raw produces
    (gl_code, gl_name, opening_balance, debit, credit, closing_balance,
    source_sheet, source_row), sourced from an already-materialized canonical
    Parquet instead of a raw workbook. Required columns are always present by
    construction (canonical_schema.CANONICAL_TB_COLUMNS), so mapping_issues is
    always empty here -- TB-001 always PASSes for this input mode."""
    canon_path = Path(canonical_tb_file)
    if not canon_path.exists():
        raise PipelineFileError(str(canon_path), "Canonical Trial Balance (supply canonical_tb_file from load_tb_from_db/build_canonical_tb)")

    canon_df = pl.read_parquet(canon_path)
    missing = [c for c in CANONICAL_TB_COLUMNS if c not in canon_df.columns]
    if missing:
        raise ValueError(f"CANONICAL_SCHEMA_MISMATCH: missing columns {missing}")

    if canon_df.is_empty():
        raise ValueError("NO_TRIAL_BALANCE_SHEET")

    working_df = pl.DataFrame(
        {
            "gl_code": canon_df["gl_code"].to_list(),
            "gl_name": canon_df["gl_name"].to_list(),
            "opening_balance": canon_df["opening_balance"].to_list(),
            "debit": canon_df["debit"].to_list(),
            "credit": canon_df["credit"].to_list(),
            "closing_balance": canon_df["closing_balance"].to_list(),
            "source_sheet": ["canonical_tb"] * canon_df.height,
            "source_row": list(range(canon_df.height)),
        }
    )
    return {"dataframe": working_df, "mapping_issues": []}

@pipeline_tool("validate_layer1_tb", domain="canonical")
def validate_layer1_tb(
    tb_excel_path: str = None,
    tb_column_mapping: dict = None,
    canonical_tb_file: str = None,
    output_dir: str = None,
    expected_financial_year: str = None,
    source_system: str = None,
    extraction_date: str = None,
):
    """
    Executes the complete Layer 1 Trial Balance validation, sourced either from
    a raw TB Excel/CSV file (tb_excel_path, before any parquet conversion or
    grouping join happens) or from an already-materialized canonical
    Parquet (canonical_tb_file -- the DB-sourced / live-template-sourced path,
    which has no raw workbook). Exactly one of the two must be provided.
    expected_financial_year/source_system/extraction_date are optional
    caller-supplied context (TB-025/TB-029) -- this tool never extracts them
    from the file itself; absent, those rules report WARNING, not HALTED.
    """
    errors = []
    artifacts = []

    if not tb_excel_path and not canonical_tb_file:
        errors.append({"type": "InvalidArguments", "error": "Provide either tb_excel_path or canonical_tb_file."})
        return {"execution_status": "FAILED", "errors": errors, "message": "No Trial Balance input provided."}
    if tb_excel_path and canonical_tb_file:
        errors.append({"type": "InvalidArguments", "error": "Provide only one of tb_excel_path or canonical_tb_file, not both."})
        return {"execution_status": "FAILED", "errors": errors, "message": "Ambiguous Trial Balance input."}

    if tb_excel_path:
        tb_path = Path(tb_excel_path)
        if not tb_path.exists():
            errors.append({"type": "FileNotFoundError", "file": str(tb_path)})
            return {"execution_status": "FAILED", "errors": errors, "message": "TB Excel file not found."}
        try:
            extraction = _extract_tb_sheets_raw(tb_excel_path, tb_column_mapping)
        except ValueError as e:
            errors.append({"type": "TBExtractionError", "error": str(e)})
            return {"execution_status": "FAILED", "errors": errors, "message": f"Failed to read TB Excel: {e}"}
    else:
        try:
            extraction = _extract_tb_rows_from_canonical(canonical_tb_file)
        except ValueError as e:
            errors.append({"type": "TBExtractionError", "error": str(e)})
            return {"execution_status": "FAILED", "errors": errors, "message": f"Failed to read canonical Trial Balance: {e}"}

    df = extraction["dataframe"]
    mapping_issues = extraction["mapping_issues"]

    if df.is_empty():
        errors.append({"type": "DataError", "error": "Empty Trial Balance"})
        return {"execution_status": "FAILED", "errors": errors, "message": "Trial Balance is empty."}

    df = df.with_row_index("_rownum")

    results = []
    findings = []

    def add_result(rule_id, rule_name, status, severity, message, evidence=None, affected_rows=None):
        if affected_rows is None:
            affected_rows = []
        results.append(
            {
                "rule": rule_id,
                "rule_name": rule_name,
                "status": status,
                "severity": severity,
                "message": message,
                "evidence": evidence,
                "affected_rows": affected_rows,
            }
        )

    def add_findings(rule_id, rule_name, severity, status, gl_code, gl_name, source_sheet, source_row, message):
        findings.append(
            {
                "rule_id": rule_id,
                "rule_name": rule_name,
                "severity": severity,
                "status": status,
                "gl_code": gl_code,
                "gl_name": gl_name,
                "source_sheet": source_sheet,
                "source_row": source_row,
                "message": message,
            }
        )

    # TB-000: Sign convention -- real anchor-keyword heuristic (see
    # _check_sign_convention above), replacing the old always-PASS stub.
    # Never HALTED: this sanity-checks the debit-positive convention every
    # other rule in this file already assumes, it doesn't gate on it.
    sign_status, sign_message = _check_sign_convention(df)
    add_result("TB-000", "Sign convention documented and consistent", sign_status, "Blocking", sign_message)

    # TB-001: Required columns identified
    if mapping_issues:
        add_result("TB-001", "All required columns present", "HALTED", "Blocking", f"Could not identify required columns on sheet(s): {mapping_issues}")
    else:
        add_result("TB-001", "All required columns present", "PASS", "Blocking", "All columns identified.")

    # TB-002: GL Code mandatory
    blanks = df.filter(pl.col("gl_code").is_null() | (pl.col("gl_code") == ""))
    if not blanks.is_empty():
        rows = blanks["_rownum"].to_list()
        add_result("TB-002", "GL Code mandatory and non-blank", "HALTED", "Blocking", "Blank GL codes found.", affected_rows=rows)
        for row in blanks.iter_rows(named=True):
            add_findings("TB-002", "GL Code mandatory", "Blocking", "HALTED", None, row.get("gl_name"), row.get("source_sheet"), row.get("source_row"), "Blank GL code")
    else:
        add_result("TB-002", "GL Code mandatory and non-blank", "PASS", "Blocking", "No blank GL codes.")

    # TB-003: GL Code unique
    counts = df.group_by("gl_code").agg(pl.len().alias("_count"))
    dupes = counts.filter(pl.col("_count") > 1)["gl_code"].to_list()
    if dupes:
        affected = df.filter(pl.col("gl_code").is_in(dupes))
        add_result("TB-003", "GL Code unique", "HALTED", "Blocking", "Duplicate GL codes found.", affected_rows=affected["_rownum"].to_list())
        for row in affected.iter_rows(named=True):
            add_findings("TB-003", "GL Code unique", "Blocking", "HALTED", row.get("gl_code"), row.get("gl_name"), row.get("source_sheet"), row.get("source_row"), "Duplicate GL code")
    else:
        add_result("TB-003", "GL Code unique", "PASS", "Blocking", "GL codes are unique.")

    # TB-004: Numeric columns valid
    num_cols = ["opening_balance", "debit", "credit", "closing_balance"]
    df = df.with_columns([pl.col(c).cast(pl.Float64, strict=False).fill_null(0.0) for c in num_cols])
    add_result("TB-004", "Numeric columns valid", "PASS", "Blocking", "Numeric columns coerced from raw Excel.")

    # TB-005: Closing = Opening + Dr - Cr
    tolerance = 5.0
    df = df.with_columns(
        (pl.col("opening_balance") + pl.col("debit") - pl.col("credit")).alias("_expected")
    ).with_columns(
        (pl.col("closing_balance") - pl.col("_expected")).alias("_diff")
    ).with_columns(
        pl.max_horizontal(
            pl.col("opening_balance").abs() + pl.col("debit").abs() + pl.col("credit").abs(),
            pl.col("closing_balance").abs(),
            pl.col("_expected").abs(),
        ).alias("_activity_base")
    ).with_columns(
        pl.when(pl.col("_activity_base") > 0)
        .then((pl.col("_diff").abs() / pl.col("_activity_base")) * 100)
        .otherwise(0.0)
        .alias("_diff_pct")
    )

    mismatches = df.filter(pl.col("_diff_pct") > tolerance)
    warnings = df.filter((pl.col("_diff_pct") > 0) & (pl.col("_diff_pct") <= tolerance))

    if not mismatches.is_empty():
        add_result("TB-005", "Closing Balance = Opening Balance + Debit - Credit", "WARNING", "Warning", "Real mismatches outside tolerance.", affected_rows=mismatches["_rownum"].to_list())
        for row in mismatches.iter_rows(named=True):
            add_findings("TB-005", "Closing Balance = Opening Balance + Debit - Credit", "Warning", "WARNING", row.get("gl_code"), row.get("gl_name"), row.get("source_sheet"), row.get("source_row"), "Mismatch outside tolerance")
    elif not warnings.is_empty():
        add_result("TB-005", "Closing Balance = Opening Balance + Debit - Credit", "WARNING", "Warning", "Rounding drift within tolerance.", affected_rows=warnings["_rownum"].to_list())
    else:
        add_result("TB-005", "Closing Balance = Opening Balance + Debit - Credit", "PASS", "Blocking", "All rows tie out.")

    df = df.drop(["_expected", "_diff", "_activity_base", "_diff_pct"])

    # TB-009: Total Dr = Total Cr
    tot_dr = float(df["debit"].sum())
    tot_cr = float(df["credit"].sum())
    diff_tot = abs(tot_dr - tot_cr)
    base = max(abs(tot_dr), abs(tot_cr))
    diff_pct_tot = (diff_tot / base * 100) if base > 0 else 0

    if diff_pct_tot > 5.0:
        add_result("TB-009", "Total Debit equals Total Credit", "HALTED", "Blocking", f"Dr={tot_dr}, Cr={tot_cr}, diff={diff_tot}")
    elif diff_pct_tot > 0:
        add_result("TB-009", "Total Debit equals Total Credit", "WARNING", "Warning", f"Dr={tot_dr}, Cr={tot_cr}, diff={diff_tot}")
    else:
        add_result("TB-009", "Total Debit equals Total Credit", "PASS", "Blocking", "Debits equal Credits.")

    # TB-010: Sum Opening = 0
    tot_open = float(df["opening_balance"].sum())
    base_open = float(df["opening_balance"].abs().sum())
    diff_pct_open = (abs(tot_open) / base_open * 100) if base_open > 0 else 0
    if diff_pct_open > 5.0:
        add_result("TB-010", "Sum of Opening Balances equals zero", "HALTED", "Blocking", f"Sum={tot_open}")
    elif diff_pct_open > 0:
        add_result("TB-010", "Sum of Opening Balances equals zero", "WARNING", "Warning", f"Sum={tot_open}")
    else:
        add_result("TB-010", "Sum of Opening Balances equals zero", "PASS", "Blocking", "Sum is 0.")

    # TB-011: Sum Closing = 0
    tot_close = float(df["closing_balance"].sum())
    base_close = float(df["closing_balance"].abs().sum())
    diff_pct_close = (abs(tot_close) / base_close * 100) if base_close > 0 else 0
    if diff_pct_close > 5.0:
        add_result("TB-011", "Sum of Closing Balances equals zero", "HALTED", "Blocking", f"Sum={tot_close}")
    elif diff_pct_close > 0:
        add_result("TB-011", "Sum of Closing Balances equals zero", "WARNING", "Warning", f"Sum={tot_close}")
    else:
        add_result("TB-011", "Sum of Closing Balances equals zero", "PASS", "Blocking", "Sum is 0.")

    # TB-015: Activity but closes at zero
    act_zero = df.filter(
        ((pl.col("debit") != 0) | (pl.col("credit") != 0)) & (pl.col("closing_balance") == 0)
    )
    if not act_zero.is_empty():
        add_result("TB-015", "Activity during period but closes at zero", "WARNING", "Info", "Some accounts close at zero.", affected_rows=act_zero["_rownum"].to_list())
        for row in act_zero.iter_rows(named=True):
            add_findings("TB-015", "Activity but closes at zero", "Info", "WARNING", row.get("gl_code"), row.get("gl_name"), row.get("source_sheet"), row.get("source_row"), "Closes at zero")
    else:
        add_result("TB-015", "Activity during period but closes at zero", "PASS", "Info", "None found.")

    # TB-025: Period matches the audit/comparison engagement period. This tool
    # has no title-block/period-label extraction of its own -- if the caller
    # supplies expected_financial_year, the period is recorded as
    # caller-asserted (not independently verified from file content, stated
    # plainly rather than pretending to be verified); otherwise WARNING.
    if expected_financial_year:
        add_result(
            "TB-025", "Period matches the audit/comparison engagement period", "PASS", "Blocking",
            f"Engagement period supplied by caller: {expected_financial_year} (not independently verified from file content).",
        )
    else:
        add_result(
            "TB-025", "Period matches the audit/comparison engagement period", "WARNING", "Blocking",
            "Engagement period not supplied -- cannot confirm period match.",
        )

    # TB-026: Currency and unit of measure declared once and consistent. This
    # pipeline has no currency column anywhere in its canonical schema (single
    # target-currency assumption baked into ingestion) -- always WARNING per
    # the spec's own "no currency column mapped -> WARNING, assume target,
    # continue" step. Scale-outlier sub-check: any single row's magnitude far
    # outside the file's own scale suggests a wrong-scale entry.
    nonzero_closing = df.filter(pl.col("closing_balance") != 0)["closing_balance"].abs()
    scale_outliers = []
    if nonzero_closing.len() >= 5:
        median_mag = float(nonzero_closing.median())
        if median_mag > 0:
            outlier_rows = df.filter((pl.col("closing_balance").abs() > median_mag * 1000) & (pl.col("closing_balance") != 0))
            scale_outliers = outlier_rows["_rownum"].to_list()
    if scale_outliers:
        add_result(
            "TB-026", "Currency and unit of measure declared once and consistent", "WARNING", "Blocking",
            "No currency column tracked -- assuming target currency throughout. "
            f"{len(scale_outliers)} row(s) are >1000x the file's median closing-balance magnitude -- possible wrong-scale entry.",
            affected_rows=scale_outliers,
        )
    else:
        add_result(
            "TB-026", "Currency and unit of measure declared once and consistent", "WARNING", "Blocking",
            "No currency column tracked -- assuming target currency throughout. No scale outliers detected.",
        )

    # TB-029: Source system and extraction trail identifiable.
    if source_system or extraction_date:
        add_result(
            "TB-029", "TB source system and extraction trail identifiable", "PASS", "Warning",
            f"Source system: {source_system or 'not supplied'}. Extraction date: {extraction_date or 'not supplied'}.",
        )
    else:
        add_result(
            "TB-029", "TB source system and extraction trail identifiable", "WARNING", "Warning",
            "No source system or extraction date supplied.",
        )

    # Layer 4 -- Formula Flag (presence-only, informational). Only meaningful
    # against the raw workbook (a canonical Parquet has no formulas by
    # construction); requires a second, separate raw read of the workbook
    # (see _detect_formula_cells) since every value-loading path elsewhere
    # uses data_only=True and can never see formula text. Never counts toward
    # "flagged rows" in any summary metric -- formula presence alone is
    # informational, not a validation failure.
    layer4_result = {"has_formulas": False, "total_formula_cells": 0, "cells_by_sheet": {}}
    if tb_excel_path:
        formula_cells = _detect_formula_cells(Path(tb_excel_path))
        total_formula_cells = sum(len(cells) for cells in formula_cells.values())
        layer4_result = {
            "has_formulas": total_formula_cells > 0,
            "total_formula_cells": total_formula_cells,
            "cells_by_sheet": formula_cells,
        }

    # SKIPPED rules — TB-013 and TB-016 require the grouping join, which runs
    # after this tool (before build_canonical_tb).
    skipped_rules = [
        ("TB-006", "Opening Balance sign matches Group", "Blocking", "Missing master data"),
        ("TB-007", "Closing Balance sign matches Group", "Warning", "Missing master data"),
        ("TB-008", "Balance direction that should never occur", "Warning", "Missing master data"),
        ("TB-012", "Assets = Liabilities + Equity", "Blocking", "Missing master data"),
        ("TB-013", "Each GL Code maps to exactly one Group", "Blocking", "Requires grouping join — runs before build_canonical_tb"),
        ("TB-014", "Group values restricted to approved master", "Blocking", "Missing master data"),
        ("TB-016", "No duplicate GL Code + Group", "Blocking", "Requires grouping join — runs before build_canonical_tb"),
        ("TB-017", "Expected mandatory heads present", "Warning", "Missing master data"),
        ("TB-018", "Suspense carries non-zero", "Warning", "Missing master data"),
        ("TB-019", "Rounding stays within tolerance", "Info", "Missing threshold"),
        ("TB-020", "Tax-related heads sign", "Warning", "Missing master data"),
        ("TB-024", "Total Income - Total Expense = Net P/L", "Blocking", "Missing P/L figure"),
        ("TB-027", "Numeric columns contain static values", "Warning", "Formula data lost in canonical parquet"),
        ("TB-031", "Control/branch flagged", "Warning", "Missing sub-ledger"),
        ("TB-032", "P&L accounts carry no Opening Balance", "Warning", "Missing P&L tagging"),
    ]

    for rule_id, rule_name, sev, reason in skipped_rules:
        add_result(rule_id, rule_name, "SKIPPED", sev, reason)

    status_counts = {"PASS": 0, "WARNING": 0, "HALTED": 0, "SKIPPED": 0}

    for r in results:
        st = r["status"]
        status_counts[st] = status_counts.get(st, 0) + 1

    if status_counts["HALTED"] > 0:
        overall = "HALTED"
    elif status_counts["WARNING"] > 0:
        overall = "WARNING"
    else:
        overall = "PASS"

    out_dir = resolve_output_dir(output_dir)
    os.makedirs(out_dir, exist_ok=True)

    results_file = out_dir / "layer1_results.json"
    findings_file = out_dir / "layer1_findings.parquet"
    summary_file = out_dir / "layer1_summary.json"

    with open(results_file, "w") as f:
        json.dump(results, f, indent=4)
    artifacts.append(str(results_file.resolve()))

    summary = {
        "rules_executed": len(results),
        "pass": status_counts["PASS"],
        "warning": status_counts["WARNING"],
        "halted": status_counts["HALTED"],
        "skipped": status_counts["SKIPPED"],
        "overall_status": overall,
        "layer4_result": layer4_result,
    }
    with open(summary_file, "w") as f:
        json.dump(summary, f, indent=4)
    artifacts.append(str(summary_file.resolve()))

    findings_cols = ["rule_id", "rule_name", "severity", "status", "gl_code", "gl_name", "source_sheet", "source_row", "message"]
    if findings:
        findings_df = pl.DataFrame(findings)
    else:
        findings_df = pl.DataFrame(schema={c: pl.Utf8 for c in findings_cols})

    schema_errors, findings_df = validate_dataframe_schema(findings_df, "validate_layer1_tb")
    if schema_errors:
        errors.extend(schema_errors)

    findings_df.write_parquet(findings_file)
    artifacts.append(str(findings_file.resolve()))

    # Force pipeline to continue even if validation halted by downgrading HALTED to WARNING
    safe_pipeline_status = "WARNING" if overall == "HALTED" else overall

    passed = status_counts["PASS"]
    halted = status_counts["HALTED"]
    warn_count = status_counts["WARNING"]

    msg_parts = [f"Layer 1 Validation completed: {passed} passed, {halted} halted, {warn_count} warnings."]

    if halted > 0 or warn_count > 0:
        failed_details = []
        for r in results:
            if r["status"] in ("HALTED", "WARNING"):
                failed_details.append(f"{r['rule_name']} ({r['status']})")
        if failed_details:
            msg_parts.append("Issues found in: " + ", ".join(failed_details))

    final_message = " ".join(msg_parts)

    return {
        "execution_status": "SUCCESS",
        "pipeline_status": safe_pipeline_status,
        "message": final_message,
        "artifacts": artifacts,
        "errors": errors,
        "layer4_result": layer4_result,
    }




# ============================================================================
# DOMAIN: chat
# ============================================================================

@pipeline_tool("chat_get_account_balance", domain="chat")
def chat_get_account_balance(canonical_tb_file: str, gl_code: str = None, gl_name_contains: str = None) -> dict:
    """Look up a GL account's balance in canonical_tb.parquet by exact gl_code or a gl_name substring."""
    df = pl.read_parquet(require_file(canonical_tb_file, "canonical TB"))

    if gl_code:
        matches = df.filter(pl.col("gl_code").cast(pl.Utf8) == str(gl_code))
    elif gl_name_contains:
        matches = df.filter(
            pl.col("gl_name").cast(pl.Utf8).str.to_lowercase().str.contains(gl_name_contains.lower(), literal=True).fill_null(False)
        )
    else:
        return {
            "execution_status": "FAILED",
            "pipeline_status": "WARNING",
            "message": "Provide gl_code or gl_name_contains.",
            "data": None,
            "artifacts": [],
        }

    if matches.is_empty():
        return {
            "execution_status": "FAILED",
            "pipeline_status": "WARNING",
            "message": "No matching account found.",
            "data": None,
            "artifacts": [],
        }

    return {
        "execution_status": "SUCCESS",
        "pipeline_status": "SUCCESS",
        "artifacts": [],
        "message": f"Found {len(matches)} matching account(s).",
        "data": matches.row(0, named=True) if len(matches) == 1 else matches.to_dicts(),
    }


_RATIO_NAMES = (
    "revenue_to_assets", "current", "quick", "debt_equity",
    "interest_coverage", "gross_margin", "net_margin", "roce",
)

@pipeline_tool("chat_get_financial_ratios", domain="chat")
def chat_get_financial_ratios(financial_ratios_file: str, ratio_name: str = None) -> dict:
    """Look up one audit ratio by name (current, quick, debt_equity, interest_coverage,
    gross_margin, net_margin, roce, revenue_to_assets), or all of them if ratio_name is
    omitted. Reads financial_ratios.json (produced by build_financial_ratios)."""
    path = require_file(financial_ratios_file, "Financial ratios (financial_ratios.json)")
    with open(path, "r", encoding="utf-8") as f:
        data = json.load(f)

    ratios = data.get("ratios", {})

    if ratio_name:
        if ratio_name not in _RATIO_NAMES:
            return {
                "execution_status": "FAILED",
                "pipeline_status": "WARNING",
                "message": f"Unknown ratio_name {ratio_name!r}. Valid values: {', '.join(_RATIO_NAMES)}.",
                "data": None,
                "artifacts": [],
            }
        ratio = ratios.get(ratio_name)
        if not ratio:
            return {
                "execution_status": "FAILED",
                "pipeline_status": "WARNING",
                "message": f"Ratio {ratio_name!r} not present in this run's financial_ratios.json.",
                "data": None,
                "artifacts": [],
            }
        return {
            "execution_status": "SUCCESS",
            "pipeline_status": "SUCCESS",
            "artifacts": [],
            "message": f"{ratio_name} = {ratio.get('value')} ({ratio.get('formula')})." if ratio.get("value") is not None
                       else f"{ratio_name} could not be computed -- missing component(s): {', '.join(ratio.get('components_missing', []))}.",
            "data": {ratio_name: ratio},
        }

    return {
        "execution_status": "SUCCESS",
        "pipeline_status": "SUCCESS",
        "artifacts": [],
        "message": f"Returning all {len(ratios)} ratio(s).",
        "data": ratios,
    }


_GROUP_COLUMNS__chat_get_fsli_breakdown = ["main_head", "sub_head_1", "sub_head_2", "fs_head", "line_item", "hierarchy_path"]

@pipeline_tool("chat_get_fsli_breakdown", domain="chat")
def chat_get_fsli_breakdown(fsli_summary_file: str, fsli_group: str = None) -> dict:
    """Look up FSLI hierarchy nodes, optionally filtered by main_head/sub_head_1/sub_head_2 substring."""
    df = pl.read_parquet(require_file(fsli_summary_file, "FSLI summary"))

    present_group_cols = [c for c in _GROUP_COLUMNS__chat_get_fsli_breakdown if c in df.columns]

    if fsli_group and present_group_cols:
        needle = fsli_group.lower()
        mask = pl.any_horizontal(
            [pl.col(c).cast(pl.Utf8).str.to_lowercase().str.contains(needle, literal=True).fill_null(False) for c in present_group_cols]
        )
        matches = df.filter(mask)
    else:
        matches = df

    if matches.is_empty():
        return {
            "execution_status": "FAILED",
            "pipeline_status": "WARNING",
            "message": "No matching FSLI node found.",
            "data": None,
            "artifacts": [],
        }

    return {
        "execution_status": "SUCCESS",
        "pipeline_status": "SUCCESS",
        "artifacts": [],
        "message": f"Found {len(matches)} matching FSLI node(s).",
        "data": matches.to_dicts(),
    }


@pipeline_tool("chat_get_reasoning", domain="chat")
def chat_get_reasoning(reasoning_file: str, limit: int = 5) -> dict:
    """Return the executive summary and top observations from an audit or comparison reasoning file, for grounding chat answers."""
    path = require_file(reasoning_file, "reasoning file")
    with open(path, "r", encoding="utf-8") as f:
        data = json.load(f)

    exec_summary = data.get("summary", {}).get("executive_summary", "")
    # audit_reasoning.json (single-TB) uses "audit_observations"; comparison_reasoning.json uses "observations".
    obs_list = data.get("audit_observations") or data.get("observations") or []

    previews = []
    for item in obs_list[:limit]:
        obs = item.get("observation", item) if isinstance(item, dict) else {}
        previews.append({
            "observation_id": obs.get("observation_id"),
            "title": obs.get("title"),
            "executive_summary": obs.get("executive_summary"),
            "priority": obs.get("priority"),
            "conclusion": obs.get("conclusion"),
        })

    return {
        "execution_status": "SUCCESS",
        "pipeline_status": "SUCCESS",
        "artifacts": [],
        "message": f"Loaded reasoning summary with {len(obs_list)} total observation(s); returning top {len(previews)}.",
        "data": {
            "executive_summary": exec_summary,
            "observations": previews,
            "total_observations": len(obs_list),
        },
    }


@pipeline_tool("chat_get_top_exceptions", domain="chat")
def chat_get_top_exceptions(consolidated_exceptions_file: str, severity: str = None, limit: int = 10) -> dict:
    """Return the top-scoring consolidated exceptions, optionally filtered by severity."""
    path = require_file(consolidated_exceptions_file, "consolidated exceptions")
    with open(path, "r", encoding="utf-8") as f:
        data = json.load(f)

    exceptions = data.get("exceptions", []) or []

    if severity:
        exceptions = [
            exc for exc in exceptions
            if str(exc.get("scoring", {}).get("severity", "")).lower() == severity.lower()
        ]

    if not exceptions:
        return {
            "execution_status": "FAILED",
            "pipeline_status": "WARNING",
            "message": "No matching exceptions found.",
            "data": None,
            "artifacts": [],
        }

    exceptions = sorted(
        exceptions,
        key=lambda exc: exc.get("scoring", {}).get("composite_score", 0.0),
        reverse=True,
    )
    top = exceptions[:limit]

    return {
        "execution_status": "SUCCESS",
        "pipeline_status": "SUCCESS",
        "artifacts": [],
        "message": f"Found {len(top)} exception(s) (of {len(exceptions)} matching).",
        "data": top,
    }


_GROUP_COLUMNS__chat_get_variance_for_account = ["fsli_group", "main_head", "sub_head_1", "line_item"]

@pipeline_tool("chat_get_variance_for_account", domain="chat")
def chat_get_variance_for_account(comparison_variance_file: str, gl_code: str = None, fsli_group: str = None) -> dict:
    """Look up PY/CY variance for a GL account by code, or all accounts within an FSLI group."""
    df = pl.read_parquet(require_file(comparison_variance_file, "comparison variance"))

    if gl_code and "gl_code" in df.columns:
        matches = df.filter(pl.col("gl_code").cast(pl.Utf8) == str(gl_code))
    elif fsli_group:
        group_col = next((c for c in _GROUP_COLUMNS__chat_get_variance_for_account if c in df.columns), None)
        if group_col:
            needle = fsli_group.lower()
            matches = df.filter(
                pl.col(group_col).cast(pl.Utf8).str.to_lowercase().str.contains(needle, literal=True).fill_null(False)
            )
        else:
            matches = df.head(0)
    else:
        return {
            "execution_status": "FAILED",
            "pipeline_status": "WARNING",
            "message": "Provide gl_code or fsli_group.",
            "data": None,
            "artifacts": [],
        }

    if matches.is_empty():
        return {
            "execution_status": "FAILED",
            "pipeline_status": "WARNING",
            "message": "No matching variance record found.",
            "data": None,
            "artifacts": [],
        }

    return {
        "execution_status": "SUCCESS",
        "pipeline_status": "SUCCESS",
        "artifacts": [],
        "message": f"Found {len(matches)} matching variance record(s).",
        "data": matches.row(0, named=True) if len(matches) == 1 else matches.to_dicts(),
    }


_DELTA_TYPES = ("new", "removed", "zero-movement", "reclassified", "material-variance")

_RECLASS_COLS = ("main_head", "sub_head_1", "sub_head_2")

def _apply_text_filter__chat_query_comparison(rows: list, needle: str, keys: tuple) -> list:
    if not needle:
        return rows
    n = needle.lower()
    return [r for r in rows if any(n in str(r.get(k, "") or "").lower() for k in keys)]

def _resolve_materiality_threshold(materiality_file, materiality_tier):
    """Mirrors run_comparison_variance.py's own materiality_file -> thresholds resolution
    (backend/tools/comparison/run_comparison_variance.py) so this stays the one convention
    for reading materiality.json, not a second one invented here."""
    if not materiality_file or not Path(materiality_file).exists():
        return None
    with open(materiality_file, "r", encoding="utf-8") as f:
        mat_data = json.load(f)
    thresholds = mat_data.get("thresholds", {})
    return float(thresholds.get(materiality_tier, 0.0)) or None

def _delta_new_removed(structural_delta_file, which, canonical_tb_file, materiality_file, materiality_tier, filter_, limit):
    path = require_file(structural_delta_file, "Structural delta (structural_delta.json)")
    with open(path, "r", encoding="utf-8") as f:
        data = json.load(f)
    key = "new_ledgers" if which == "new" else "removed_ledgers"
    rows = list(data.get(key, []) or [])

    # structural_delta.json's new_ledgers/removed_ledgers carry only gl_code/gl_name (no
    # balance, verified schema) -- join against the matching period's canonical TB whenever
    # it's supplied, both to surface closing_balance (useful regardless of materiality) and
    # to make a materiality_file threshold filter possible in this same call.
    threshold = None
    if canonical_tb_file and Path(canonical_tb_file).exists():
        tb_df = pl.read_parquet(canonical_tb_file)
        if {"gl_code", "closing_balance"}.issubset(tb_df.columns):
            balances = dict(tb_df.select(["gl_code", "closing_balance"]).iter_rows())
            for r in rows:
                r["closing_balance"] = balances.get(r.get("gl_code"))

        threshold = _resolve_materiality_threshold(materiality_file, materiality_tier)
        if threshold is not None:
            rows = [r for r in rows if r.get("closing_balance") is not None and abs(r["closing_balance"]) >= threshold]

    rows = _apply_text_filter__chat_query_comparison(rows, filter_, ("gl_code", "gl_name"))
    label = f"{which} GL codes" if threshold is None else f"{which} GL codes (above {materiality_tier} materiality, {threshold:,.2f})"
    return rows[:limit], label

def _delta_zero_movement(comparison_variance_file, filter_, limit):
    path = require_file(comparison_variance_file, "Comparison variance (comparison_variance.parquet)")
    df = pl.read_parquet(path)
    matches = df.filter(pl.col("flag") == "NO_CHANGE") if "flag" in df.columns else df.head(0)
    rows = _apply_text_filter__chat_query_comparison(matches.to_dicts(), filter_, ("gl_code", "gl_name"))
    return rows[:limit], "zero-movement (identical YoY closing balance) accounts"

def _delta_material_variance(comparison_variance_file, flag, filter_, limit):
    path = require_file(comparison_variance_file, "Comparison variance (comparison_variance.parquet)")
    df = pl.read_parquet(path)
    if flag:
        matches = df.filter(pl.col("flag") == flag.upper())
    else:
        matches = df.filter(pl.col("flag").is_in(["CRITICAL", "HIGH", "MEDIUM"])) if "flag" in df.columns else df.head(0)
    matches = matches.sort("variance", descending=True) if "variance" in matches.columns else matches
    rows = _apply_text_filter__chat_query_comparison(matches.to_dicts(), filter_, ("gl_code", "gl_name"))
    return rows[:limit], f"material-variance accounts (flag={flag or 'CRITICAL/HIGH/MEDIUM'})"

def _delta_reclassified(py_canonical_tb_file, cy_canonical_tb_file, filter_, limit):
    py_path = require_file(py_canonical_tb_file, "PY canonical TB (py/canonical_tb.parquet)")
    cy_path = require_file(cy_canonical_tb_file, "CY canonical TB (cy/canonical_tb.parquet)")
    py_df = pl.read_parquet(py_path)
    cy_df = pl.read_parquet(cy_path)

    keep_cols = ["gl_code", "gl_name", "closing_balance"] + list(_RECLASS_COLS)
    py_slim = py_df.select([c for c in keep_cols if c in py_df.columns]).rename(
        {c: f"py_{c}" for c in keep_cols if c in py_df.columns and c != "gl_code"}
    )
    cy_slim = cy_df.select([c for c in keep_cols if c in cy_df.columns]).rename(
        {c: f"cy_{c}" for c in keep_cols if c in cy_df.columns and c != "gl_code"}
    )
    joined = cy_slim.join(py_slim, on="gl_code", how="inner")

    present_reclass_cols = [c for c in _RECLASS_COLS if f"py_{c}" in joined.columns and f"cy_{c}" in joined.columns]
    if not present_reclass_cols:
        return [], "reclassified GL codes (PY vs CY FSLI mapping change)"

    # fill_null before comparing: two nulls (e.g. both sub_head_2 unset) must compare equal,
    # not evaluate to a null/ambiguous mask that could silently drop or include a row.
    changed_mask = pl.any_horizontal(
        [
            pl.col(f"py_{c}").cast(pl.Utf8).fill_null("") != pl.col(f"cy_{c}").cast(pl.Utf8).fill_null("")
            for c in present_reclass_cols
        ]
    )
    changed = joined.filter(changed_mask)
    if "py_closing_balance" in changed.columns and "cy_closing_balance" in changed.columns:
        changed = changed.with_columns(
            (pl.col("cy_closing_balance") - pl.col("py_closing_balance")).alias("balance_delta")
        )
    rows = _apply_text_filter__chat_query_comparison(changed.to_dicts(), filter_, ("gl_code", "gl_name"))
    rows.sort(key=lambda r: abs(r.get("balance_delta") or 0.0), reverse=True)
    return rows[:limit], "reclassified GL codes (PY vs CY FSLI mapping change)"

@pipeline_tool("chat_query_comparison", domain="chat")
def chat_query_comparison(
    delta_type: str,
    filter: str = None,
    flag: str = None,
    limit: int = 20,
    structural_delta_file: str = None,
    comparison_variance_file: str = None,
    py_canonical_tb_file: str = None,
    cy_canonical_tb_file: str = None,
    materiality_file: str = None,
    materiality_tier: str = "overall",
) -> dict:
    """PY-vs-CY comparison lookups. `delta_type` determines which file parameter(s) you must
    supply -- pass only what's listed, extra file params for other delta_types are ignored:
    'new' -- requires `structural_delta_file` (GL codes present in CY only). Optionally also
    supply `cy_canonical_tb_file` to include each code's real closing_balance in the results,
    and `materiality_file` (+ optional `materiality_tier`, default "overall") together with it
    to filter to only codes whose |closing_balance| is at or above that real threshold --
    this is the only way to answer "new AND above materiality" in one call; there is no other
    way to discover materiality.json's actual threshold value, so don't guess one.
    'removed' -- same as 'new' but requires `py_canonical_tb_file` instead (removed codes only
    exist in PY) for the closing_balance/materiality join.
    'zero-movement' -- requires `comparison_variance_file` (identical YoY closing balance).
    'material-variance' -- requires `comparison_variance_file` (variance flagged CRITICAL/
    HIGH/MEDIUM, optionally narrowed to one `flag`).
    'reclassified' -- requires BOTH `py_canonical_tb_file` and `cy_canonical_tb_file` (same
    GL code, different main_head/sub_head_1/sub_head_2 between PY and CY, with the balance
    delta) -- this is the one delta_type that does NOT read structural_delta_file or
    comparison_variance_file at all.
    `filter` narrows results by a case-insensitive substring on GL code/name."""
    if delta_type not in _DELTA_TYPES:
        return {
            "execution_status": "FAILED",
            "pipeline_status": "WARNING",
            "message": f"Unknown delta_type {delta_type!r}. Valid values: {', '.join(_DELTA_TYPES)}.",
            "data": None,
            "artifacts": [],
        }

    if delta_type in ("new", "removed"):
        period_tb_file = cy_canonical_tb_file if delta_type == "new" else py_canonical_tb_file
        rows, label = _delta_new_removed(structural_delta_file, delta_type, period_tb_file, materiality_file, materiality_tier, filter, limit)
    elif delta_type == "zero-movement":
        rows, label = _delta_zero_movement(comparison_variance_file, filter, limit)
    elif delta_type == "material-variance":
        rows, label = _delta_material_variance(comparison_variance_file, flag, filter, limit)
    else:
        rows, label = _delta_reclassified(py_canonical_tb_file, cy_canonical_tb_file, filter, limit)

    if not rows:
        return {
            "execution_status": "FAILED",
            "pipeline_status": "WARNING",
            "message": f"No matching {label} found.",
            "data": None,
            "artifacts": [],
        }

    return {
        "execution_status": "SUCCESS",
        "pipeline_status": "SUCCESS",
        "artifacts": [],
        "message": f"Found {len(rows)} {label}.",
        "data": rows,
    }


_CATEGORIES = (
    "duplicate_gl_code", "duplicate_description", "sign_anomaly",
    "sensitive_keyword", "negative_balance", "dormant", "mapping_integrity",
)

_GENERIC_DESC_KEYWORDS = ("misc", "miscellaneous", "others", "other", "sundry", "temporary", "temp", "n/a", "na", "-", "tbd")

_DUP_DESC_RE = re.compile(r"GL '([^']+)' \(([^)]*)\) and GL '([^']+)' \(([^)]*)\)")

_EXPECTED_POSITIVE_KEYWORDS = ("inventory", "stock", "receivable", "debtor", "fixed asset", "property, plant", "ppe")

def _filter_rows(rows: list, needle: str, keys: tuple) -> list:
    if not needle:
        return rows
    n = needle.lower()
    return [r for r in rows if any(n in str(r.get(k, "") or "").lower() for k in keys)]

def _category_duplicate_gl_code(layer1_findings_file, filter_, limit):
    path = require_file(layer1_findings_file, "Layer-1 findings (layer1_findings.parquet)")
    df = pl.read_parquet(path)
    matches = df.filter(pl.col("rule_id").is_in(["TB-002", "TB-003"])) if "rule_id" in df.columns else df.head(0)
    rows = _filter_rows(matches.to_dicts(), filter_, ("gl_code", "gl_name"))
    # The label flows into both the "Found N result(s) for {label}" and "No matching results
    # for {label}" messages below -- state the scope explicitly in both cases, not just when
    # results exist, since a false "clean, checked" reading on a 0-result answer is the more
    # dangerous failure mode (same class as the N12 vendor-lookup guardrail gap).
    return rows[:limit], (
        "duplicate/blank GL code (TB-002/TB-003 -- flat GL-code uniqueness only; this "
        "schema has no cost-centre/division/circle dimension, so a duplicate check cannot "
        "be scoped by one)"
    )

def _category_duplicate_description(canonical_tb_file, anomaly_findings_file, filter_, limit):
    rows = []
    if anomaly_findings_file and Path(anomaly_findings_file).exists():
        with open(anomaly_findings_file, "r", encoding="utf-8") as f:
            data = json.load(f)
        for finding in data.get("findings", []) or []:
            if finding.get("rule_id") != "TB-030":
                continue
            m = _DUP_DESC_RE.search(finding.get("description", ""))
            if m:
                rows.append({
                    "check": "fuzzy_duplicate_pair", "gl_code_a": m.group(1), "gl_name_a": m.group(2),
                    "gl_code_b": m.group(3), "gl_name_b": m.group(4), "similarity": finding.get("trigger_value"),
                })
            else:
                rows.append({"check": "fuzzy_duplicate_pair", "gl_code": finding.get("account"), "description": finding.get("description")})

    if canonical_tb_file and Path(canonical_tb_file).exists():
        df = pl.read_parquet(canonical_tb_file)
        if "gl_name" in df.columns:
            generic = df.filter(
                pl.col("gl_name").cast(pl.Utf8).str.strip_chars().str.to_lowercase().is_in(list(_GENERIC_DESC_KEYWORDS))
                | pl.col("gl_name").is_null()
                | (pl.col("gl_name").cast(pl.Utf8).str.strip_chars() == "")
            )
            for r in generic.select(["gl_code", "gl_name"]).to_dicts():
                rows.append({"check": "generic_or_blank_description", **r})

    rows = _filter_rows(rows, filter_, ("gl_code", "gl_name", "gl_code_a", "gl_code_b"))
    return rows[:limit], "duplicate/generic/blank description (TB-030 + keyword scan)"

def _category_sign_anomaly(layer1_results_file, filter_, limit):
    path = require_file(layer1_results_file, "Layer-1 results (layer1_results.json)")
    with open(path, "r", encoding="utf-8") as f:
        results = json.load(f)
    matches = [r for r in results if r.get("rule") == "TB-000"]
    return matches[:limit], "sign convention contrary to normal nature (TB-000)"

def _category_sensitive_keyword(sensitive_accounts_file, sensitive_category, filter_, limit):
    path = require_file(sensitive_accounts_file, "Sensitive accounts (sensitive_accounts.parquet)")
    df = pl.read_parquet(path)
    matches = df
    if sensitive_category and "category" in df.columns:
        matches = matches.filter(pl.col("category") == sensitive_category)
    rows = _filter_rows(matches.to_dicts(), filter_, ("gl_code", "gl_name", "account"))
    label = f"sensitive accounts (category={sensitive_category})" if sensitive_category else "sensitive accounts (all categories)"
    return rows[:limit], label

def _category_negative_balance(canonical_tb_file, filter_, limit):
    df = load_canonical_tb(canonical_tb_file)
    if df is None or df.is_empty() or "report_head" not in df.columns:
        return [], "negative balances in structurally-expected-positive accounts"
    needle_expr = pl.any_horizontal(
        [pl.col("gl_name").cast(pl.Utf8).str.to_lowercase().str.contains(kw, literal=True).fill_null(False) for kw in _EXPECTED_POSITIVE_KEYWORDS]
    )
    matches = df.filter(
        (pl.col("report_head") == "Assets") & needle_expr & (pl.col("closing_balance") < 0)
    )
    rows = _filter_rows(matches.select(["gl_code", "gl_name", "report_head", "report_sub", "closing_balance"]).to_dicts(), filter_, ("gl_code", "gl_name"))
    return rows[:limit], "negative balances in structurally-expected-positive accounts (inventory/receivables/fixed assets)"

def _category_dormant(canonical_tb_file, filter_, limit):
    df = load_canonical_tb(canonical_tb_file)
    rows = dormant_rows_from_canonical(df, limit=max(limit, 50))
    rows = _filter_rows(rows, filter_, ("gl_code", "gl_name"))
    return rows[:limit], "dormant accounts (zero period movement, non-zero closing balance)"

def _category_mapping_integrity(grouping_statistics_file, filter_, limit):
    path = require_file(grouping_statistics_file, "Grouping statistics (grouping_statistics.json)")
    with open(path, "r", encoding="utf-8") as f:
        stats = json.load(f)
    dup_count = stats.get("duplicate_gls", 0)
    row = {
        "duplicate_gls_collapsed": dup_count,
        "note": (
            "grouping_ground_truth.parquet enforces one row per gl_code by construction, so a GL "
            "code cannot map to more than one FS line item in this artifact. This count is how many "
            "GL codes had multiple candidate mappings during grouping and were collapsed to the "
            "first match -- the closest available signal to a 1:many mapping concern."
            if dup_count else
            "No GL codes had multiple candidate mappings collapsed during grouping."
        ),
    }
    return [row], "GL-to-FS-line-item mapping integrity"

@pipeline_tool("chat_query_flags", domain="chat")
def chat_query_flags(
    category: str,
    canonical_tb_file: str = None,
    layer1_findings_file: str = None,
    layer1_results_file: str = None,
    anomaly_findings_file: str = None,
    sensitive_accounts_file: str = None,
    grouping_statistics_file: str = None,
    sensitive_category: str = None,
    filter: str = None,
    limit: int = 20,
) -> dict:
    """Look up which accounts triggered a rule/flag check. `category` determines which file
    param(s) you must supply -- pass only what's listed, other file params are ignored:
    'duplicate_gl_code' -- requires `layer1_findings_file` (NOT layer1_results_file --
    that's the aggregate rule-level file, this needs the per-row findings file).
    'duplicate_description' -- requires `anomaly_findings_file`; optionally add
    `canonical_tb_file` too for the generic-term (Misc/Others/Sundry) keyword scan.
    'sign_anomaly' -- requires `layer1_results_file` (NOT layer1_findings_file -- TB-000 is
    an aggregate-only check, it never appears in the per-row findings file).
    'sensitive_keyword' -- requires `sensitive_accounts_file`; optionally narrow with
    `sensitive_category` (e.g. related_party/grant_subsidy/prior_period_item).
    'negative_balance' or 'dormant' -- requires `canonical_tb_file`.
    'mapping_integrity' -- requires `grouping_statistics_file`.
    `filter` narrows results by a case-insensitive substring on GL code/name."""
    if category not in _CATEGORIES:
        return {
            "execution_status": "FAILED",
            "pipeline_status": "WARNING",
            "message": f"Unknown category {category!r}. Valid categories: {', '.join(_CATEGORIES)}.",
            "data": None,
            "artifacts": [],
        }

    dispatch = {
        "duplicate_gl_code": lambda: _category_duplicate_gl_code(layer1_findings_file, filter, limit),
        "duplicate_description": lambda: _category_duplicate_description(canonical_tb_file, anomaly_findings_file, filter, limit),
        "sign_anomaly": lambda: _category_sign_anomaly(layer1_results_file, filter, limit),
        "sensitive_keyword": lambda: _category_sensitive_keyword(sensitive_accounts_file, sensitive_category, filter, limit),
        "negative_balance": lambda: _category_negative_balance(canonical_tb_file, filter, limit),
        "dormant": lambda: _category_dormant(canonical_tb_file, filter, limit),
        "mapping_integrity": lambda: _category_mapping_integrity(grouping_statistics_file, filter, limit),
    }

    rows, label = dispatch[category]()

    if not rows:
        return {
            "execution_status": "FAILED",
            "pipeline_status": "WARNING",
            "message": f"No matching results for {label}.",
            "data": None,
            "artifacts": [],
        }

    return {
        "execution_status": "SUCCESS",
        "pipeline_status": "SUCCESS",
        "artifacts": [],
        "message": f"Found {len(rows)} result(s) for {label}.",
        "data": rows,
    }


_METRICS = ("balance", "pct_of_total", "count", "control_totals", "common_size")

_GL_FILTER_COLUMNS = ["report_head", "report_sub", "main_head", "sub_head_1", "sub_head_2", "account_type", "bs_pl", "gl_name"]

_FSLI_FILTER_COLUMNS = ["main_head", "sub_head_1", "sub_head_2", "node_name", "hierarchy_path"]

_COMMON_SIZE_FILTER_COLUMNS = ["main_head", "sub_head_1", "sub_head_2", "node_name", "hierarchy_path"]

_COMMON_SIZE_JOIN_KEYS = ["main_head", "sub_head_1", "sub_head_2"]

def _apply_text_filter__chat_query_fsli_table(df: pl.DataFrame, needle: str, candidate_cols: list) -> pl.DataFrame:
    if not needle:
        return df
    present = [c for c in candidate_cols if c in df.columns]
    if not present:
        return df
    n = needle.lower()
    mask = pl.any_horizontal(
        [pl.col(c).cast(pl.Utf8).str.to_lowercase().str.contains(n, literal=True).fill_null(False) for c in present]
    )
    return df.filter(mask)

def _sort_top_n(df: pl.DataFrame, by: str, sort: str, top_n) -> pl.DataFrame:
    if by in df.columns:
        df = df.sort(by, descending=(sort != "asc"))
    if top_n:
        df = df.head(int(top_n))
    return df

def _metric_count(df: pl.DataFrame, group_by):
    known_cols = set(df.columns)
    requested = [group_by] if group_by else ["gl_code", "main_head", "sub_head_1", "sub_head_2", "account_type"]
    rows = []
    for col in requested:
        if col in known_cols:
            rows.append({"dimension": col, "distinct_count": int(df[col].n_unique())})
        else:
            rows.append({"dimension": col, "distinct_count": None, "note": f"Column {col!r} does not exist in the canonical TB schema."})
    for missing_dim in ("cost_centre", "circle", "division"):
        if group_by in (None, missing_dim) and missing_dim not in known_cols:
            rows.append({"dimension": missing_dim, "distinct_count": None, "note": f"Column {missing_dim!r} does not exist in the canonical TB schema — not tracked at GL grain."})
    return rows

def _metric_balance_or_pct(df: pl.DataFrame, metric, group_by, basis, top_n, sort):
    value_col = "closing_balance"
    head_totals = {}
    if "report_head" in df.columns:
        head_totals = dict(
            df.group_by("report_head").agg(pl.col(value_col).abs().sum().alias("total")).iter_rows()
        )
    basis_total = head_totals.get(basis.strip().title()) if basis else None

    if group_by and group_by in df.columns:
        agg = df.group_by(group_by).agg([
            pl.col(value_col).sum().alias(value_col),
            pl.first("report_head").alias("report_head") if "report_head" in df.columns else pl.lit(None).alias("report_head"),
            pl.len().alias("gl_count"),
        ])
        rows = agg.to_dicts()
    else:
        keep_cols = [c for c in ("gl_code", "gl_name", "report_head", "report_sub", value_col) if c in df.columns]
        rows = df.select(keep_cols).to_dicts()

    if metric == "pct_of_total":
        for r in rows:
            denom = basis_total if basis_total else head_totals.get(str(r.get("report_head") or ""), 0.0)
            r["pct_of_total"] = round(abs(r.get(value_col, 0.0)) / denom * 100, 4) if denom else None
        rows.sort(key=lambda r: (r.get("pct_of_total") is None, -(r.get("pct_of_total") or 0.0)) if sort != "asc" else (r.get("pct_of_total") is None, r.get("pct_of_total") or 0.0))
    else:
        rows.sort(key=lambda r: abs(r.get(value_col, 0.0)), reverse=(sort != "asc"))

    if top_n:
        rows = rows[:int(top_n)]
    return rows

def _metric_control_totals(df: pl.DataFrame):
    totals = control_totals(df)
    return [totals] if totals else []

def _metric_common_size(snapshot_drilldown_file, py_snapshot_drilldown_file, filter_, top_n, sort):
    path = require_file(snapshot_drilldown_file, "Financial snapshot drilldown (snapshot_drilldown.parquet)")
    df = pl.read_parquet(path)
    df = _apply_text_filter__chat_query_fsli_table(df, filter_, _COMMON_SIZE_FILTER_COLUMNS)
    keep_cols = [c for c in ("main_head", "sub_head_1", "sub_head_2", "node_name", "hierarchy_level", "closing_balance", "percent_of_parent", "percent_of_main_head") if c in df.columns]
    df = df.select(keep_cols)

    if py_snapshot_drilldown_file and Path(py_snapshot_drilldown_file).exists():
        py_df = pl.read_parquet(py_snapshot_drilldown_file)
        join_keys = [c for c in _COMMON_SIZE_JOIN_KEYS if c in df.columns and c in py_df.columns]
        if join_keys and "percent_of_main_head" in py_df.columns:
            # fill_null before joining: polars (SQL semantics) never matches null==null, so a
            # node whose sub_head_2 is unset on both sides would otherwise silently fail to join.
            df = df.with_columns([pl.col(k).cast(pl.Utf8).fill_null("") for k in join_keys])
            py_slim = py_df.select(join_keys + ["percent_of_main_head"]).with_columns(
                [pl.col(k).cast(pl.Utf8).fill_null("") for k in join_keys]
            ).rename({"percent_of_main_head": "percent_of_main_head_py"})
            df = df.join(py_slim, on=join_keys, how="left")
            df = df.with_columns(
                (pl.col("percent_of_main_head") - pl.col("percent_of_main_head_py")).alias("percent_of_main_head_change")
            )

    df = _sort_top_n(df, "percent_of_main_head", sort, top_n)
    return df.to_dicts()

@pipeline_tool("chat_query_fsli_table", domain="chat")
def chat_query_fsli_table(
    metric: str = "balance",
    level: str = "gl",
    filter: str = None,
    group_by: str = None,
    basis: str = None,
    top_n: int = None,
    sort: str = "desc",
    canonical_tb_file: str = None,
    fsli_summary_file: str = None,
    snapshot_drilldown_file: str = None,
    py_snapshot_drilldown_file: str = None,
) -> dict:
    """Slice/aggregate the canonical TB (level='gl') or FSLI hierarchy (level='fsli_node')
    by a filter + metric + grouping combination. metric: 'balance' (raw amounts, optionally
    top_n/sort), 'pct_of_total' (% of the matched rows' own report_head total, or of `basis`
    if given, e.g. basis='Assets'), 'count' (distinct-value counts per column, or per
    `group_by` if given), 'control_totals' (sum debit/credit/difference), or 'common_size'
    (reads snapshot_drilldown.parquet's real %-of-parent/%-of-main_head figures; supply
    py_snapshot_drilldown_file too for a PY-vs-CY common-size change). `filter` is a plain
    case-insensitive substring matched against FSLI/account-type/name columns -- it is NOT a
    query language, never pass a SQL-like expression (e.g. "main_head = 'Expenses'"); pass
    just the word itself (e.g. "Expenses"). A gl_name substring match (e.g. filter="vendor")
    only finds GL accounts whose NAME happens to contain that word -- there is no vendor,
    cost-centre, division, or circle dimension in this schema, so a match like that is never
    real vendor/cost-centre-level data. Never present such a match as if it answered a
    vendor/cost-centre/division question; state plainly that dimension does not exist here."""
    if metric not in _METRICS:
        return {
            "execution_status": "FAILED",
            "pipeline_status": "WARNING",
            "message": f"Unknown metric {metric!r}. Valid metrics: {', '.join(_METRICS)}.",
            "data": None,
            "artifacts": [],
        }

    if metric == "common_size":
        rows = _metric_common_size(snapshot_drilldown_file, py_snapshot_drilldown_file, filter, top_n, sort)
        label = "common-size %"
    elif level == "fsli_node":
        path = require_file(fsli_summary_file, "FSLI summary (fsli_summary.parquet)")
        df = _apply_text_filter__chat_query_fsli_table(pl.read_parquet(path), filter, _FSLI_FILTER_COLUMNS)
        df = _sort_top_n(df, "closing_balance", sort, top_n)
        rows = df.to_dicts()
        label = "FSLI node(s)"
    else:
        df = load_canonical_tb(require_file(canonical_tb_file, "Canonical TB (canonical_tb.parquet)"))
        if df is None:
            df = pl.DataFrame()
        df = _apply_text_filter__chat_query_fsli_table(df, filter, _GL_FILTER_COLUMNS)
        if metric == "count":
            rows = _metric_count(df, group_by)
        elif metric == "control_totals":
            rows = _metric_control_totals(df)
        else:
            rows = _metric_balance_or_pct(df, metric, group_by, basis, top_n, sort)
        label = f"GL row(s) [{metric}]"

    if not rows:
        hint = (
            " filter is a plain substring, not a query expression -- retry with just the "
            "bare word/phrase (e.g. \"Expenses\", not \"main_head = 'Expenses'\")."
            if filter and any(ch in filter for ch in "='\"%<>")
            else ""
        )
        return {
            "execution_status": "FAILED",
            "pipeline_status": "WARNING",
            "message": f"No matching {label} found for filter={filter!r}.{hint}",
            "data": None,
            "artifacts": [],
        }

    response = {
        "execution_status": "SUCCESS",
        "pipeline_status": "SUCCESS",
        "artifacts": [],
        "message": f"Found {len(rows)} {label}.",
        "data": rows,
    }
    if metric == "pct_of_total" and top_n:
        pct_sum = sum(r.get("pct_of_total") or 0.0 for r in rows)
        response["combined_share_pct"] = round(pct_sum, 4)
    return response




# ============================================================================
# DOMAIN: comparison
# ============================================================================

_OBSERVATION_TEXT_FIELDS = ["title", "executive_summary", "detailed_observation", "audit_risk", "conclusion"]

_COMPARISON_REASONING_PROMPT_TEMPLATE = """You are a Senior Audit Manager performing audit planning and generating professional, evidence-based audit observations for a Prior Year (PY) vs Current Year (CY) trial balance comparison.

## Objective
Convert the deterministic comparison findings provided below into a professional audit observation following strict audit terminology.

## Design Principles
1. **Evidence-First**: Every statement must originate from the deterministic pipeline outputs provided.
2. **Never Invent**: Do not infer transactions not represented in the payload. Do not invent balances, relationships, account classifications, or findings.
3. **Conservative Language**: NEVER conclude fraud, error, misstatement, or non-compliance. Use conservative phrasing like "may indicate," "could suggest," "requires corroboration," or "warrants investigation." State uncertainty when evidence is insufficient.
4. **No Speculation**: Do not speculate about fraud, management intent, or accounting errors.
5. **Explainability**: Explain what happened, why it matters, possible legitimate explanations, and required corroboration.

## Input Context
**Finding Type**: {{finding_type}}
**Severity**: {{severity}}

**Comparison Evidence (Summarized)**:
```json
{{finding_payload}}
```

## Output Requirements
You must return a raw JSON object strictly matching the schema below. Do not wrap it in markdown block quotes (e.g., no ```json ... ```). Return ONLY the raw JSON.

### Output JSON Schema
{
    "observation_id": "OBS-{{finding_type}}",
    "title": "A concise, professional title for this observation.",
    "executive_summary": "One concise bullet explaining why the auditor should care about this comparison finding.",
    "detailed_observation": "Explain what the deterministic PY/CY comparison detected.",
    "audit_risk": "Explain why this increases audit attention (e.g., continuity, completeness, existence).",
    "affected_assertions": ["Assertion 1", "Assertion 2"],
    "recommended_procedures": ["Explicit audit procedure 1", "Explicit audit procedure 2"],
    "priority": "{{severity}}",
    "conclusion": "Final wrap-up sentence on the required audit focus."
}"""

def _build_comparison_findings(precheck_data: dict, structural_data: dict, variance_rows: list, sign_check_data: dict) -> list:
    """Deterministic, evidence-first extraction of comparison findings from Task 1 artifacts."""
    findings = []

    for check in precheck_data.get("checks", []):
        if check.get("check") == "opening_closing_continuity" and check.get("break_count", 0) > 0:
            findings.append({
                "type": "continuity_break",
                "severity": "High",
                "detail": (
                    f"{check['break_count']} GL code(s) show Opening(CY) does not equal Closing(PY), "
                    "a continuity break that requires corroboration."
                ),
                "evidence": check.get("breaks", [])[:10],
            })
        elif check.get("status") == "HALTED":
            findings.append({
                "type": "control_total_halt",
                "severity": "Critical",
                "detail": (
                    f"{check.get('check')}: debit/credit control totals differ by "
                    f"{check.get('diff_pct', 'n/a')}%, exceeding the tolerance for automatic continuation."
                ),
                "evidence": check,
            })
        elif check.get("status") == "WARNING":
            findings.append({
                "type": "control_total_warning",
                "severity": "Medium",
                "detail": (
                    f"{check.get('check')}: debit/credit control totals differ by "
                    f"{check.get('diff_pct', 'n/a')}%."
                ),
                "evidence": check,
            })

    new_ledgers = structural_data.get("new_ledgers", []) or []
    removed_ledgers = structural_data.get("removed_ledgers", []) or []
    if new_ledgers or removed_ledgers:
        findings.append({
            "type": "structural_delta",
            "severity": "Medium",
            "detail": structural_data.get("message", "PY/CY ledger structure changed."),
            "evidence": {"new_ledgers": new_ledgers[:20], "removed_ledgers": removed_ledgers[:20]},
        })

    high_priority = [r for r in variance_rows if r.get("flag") == "CRITICAL"]
    if high_priority:
        findings.append({
            "type": "material_variance",
            "severity": "High",
            "detail": (
                f"{len(high_priority)} GL code(s) show a PY/CY closing-balance variance exceeding "
                "2x provisional materiality."
            ),
            "evidence": high_priority[:20],
        })

    dropped = [r for r in variance_rows if r.get("flag") == "DROPPED"]
    new_entries = [r for r in variance_rows if r.get("flag") == "NEW_ENTRY"]
    if dropped or new_entries:
        findings.append({
            "type": "balance_appearance_disappearance",
            "severity": "Medium",
            "detail": (
                f"{len(new_entries)} GL code(s) newly carry a balance in CY (zero in PY) and "
                f"{len(dropped)} GL code(s) that carried a balance in PY are zero in CY."
            ),
            "evidence": {"new_entries": new_entries[:20], "dropped": dropped[:20]},
        })

    for flag in sign_check_data.get("flags", []) or []:
        if flag.get("status") == "WARNING":
            findings.append({
                "type": "sign_convention_flag",
                "severity": "Medium",
                "detail": flag.get("message", "Sign convention warning."),
                "evidence": flag,
            })

    return findings

@pipeline_tool("build_comparison_reasoning", domain="comparison")
def build_comparison_reasoning(
    precheck_file: str,
    structural_file: str,
    variance_file: str,
    sign_check_file: str,
    output_dir: str = None,
    llm_client=None,
    **kwargs
) -> dict:
    """Builds comparison_reasoning.json — evidence-grounded audit observations from Task 1 comparison artifacts."""
    errors = []
    artifacts = []

    out_dir = resolve_output_dir(output_dir)
    out_dir.mkdir(parents=True, exist_ok=True)

    def _load_json(path_str, label):
        if not path_str:
            errors.append({"type": "MissingArgument", "label": label})
            return {}
        p = Path(path_str)
        if not p.exists():
            errors.append({"type": "FileNotFoundError", "file": str(p), "label": label})
            return {}
        try:
            with open(p, "r", encoding="utf-8") as f:
                return json.load(f)
        except Exception as e:
            errors.append({"type": "ParseError", "file": str(p), "error": str(e)})
            return {}

    precheck_data = _load_json(precheck_file, "precheck")
    structural_data = _load_json(structural_file, "structural")
    sign_check_data = _load_json(sign_check_file, "sign_check")

    variance_rows = []
    if variance_file:
        var_path = Path(variance_file)
        if var_path.exists():
            variance_rows = pl.read_parquet(var_path).to_dicts()
        else:
            errors.append({"type": "FileNotFoundError", "file": str(var_path), "label": "variance"})

    findings = _build_comparison_findings(precheck_data, structural_data, variance_rows, sign_check_data)

    if not findings:
        reasoning_json = {
            "summary": {"executive_summary": "No comparison exceptions were flagged by the deterministic pipeline."},
            "observations": [],
        }
        out_file = out_dir / "comparison_reasoning.json"
        with open(out_file, "w", encoding="utf-8") as f:
            json.dump(reasoning_json, f, indent=4)
        return {
            "execution_status": "SUCCESS",
            "pipeline_status": "SUCCESS",
            "message": "No comparison findings; wrote empty comparison_reasoning.json.",
            "artifacts": [str(out_file)],
            "errors": errors,
        }

    observations = []
    stats = {"llm_calls": 0, "failures": 0}

    for finding in findings:
        finding_type = finding["type"]
        severity = finding["severity"]

        deterministic_obs = {
            "observation_id": f"OBS-{finding_type}",
            "title": finding_type.replace("_", " ").title(),
            "executive_summary": finding["detail"],
            "detailed_observation": finding["detail"],
            "audit_risk": (
                "This finding may indicate a break in continuity, completeness, or accuracy between "
                "the prior year and current year trial balances and warrants corroboration."
            ),
            "affected_assertions": ["Completeness", "Accuracy"],
            "recommended_procedures": [
                "Obtain and review the underlying ledger/reconciliation supporting the flagged GL code(s).",
                "Corroborate with management explanation and supporting documentation.",
            ],
            "priority": severity,
            "conclusion": (
                f"This {finding_type.replace('_', ' ')} finding requires corroboration before any view is formed."
            ),
        }

        obs_data = None
        if llm_client is not None:
            prompt = _COMPARISON_REASONING_PROMPT_TEMPLATE
            prompt = prompt.replace("{{finding_type}}", finding_type)
            prompt = prompt.replace("{{severity}}", severity)
            prompt = prompt.replace("{{finding_payload}}", json.dumps(finding, indent=2, default=str))
            messages = [{"role": "user", "content": prompt}]

            for _ in range(3):
                try:
                    stats["llm_calls"] += 1
                    response = llm_client.generate(messages, max_tokens=2048)
                    content = response.get("content", "{}") if isinstance(response, dict) else getattr(response, "content", "{}")
                    cleaned = content.strip()
                    if cleaned.startswith("```json"):
                        cleaned = cleaned[7:]
                    if cleaned.startswith("```"):
                        cleaned = cleaned[3:]
                    if cleaned.endswith("```"):
                        cleaned = cleaned[:-3]
                    obs_data = json.loads(cleaned.strip())
                    break
                except Exception:
                    continue

            if obs_data is None:
                stats["failures"] += 1

        observation = obs_data or deterministic_obs
        # Deterministic safe-wording pass -- applies regardless of LLM vs
        # deterministic-template origin, on every free-text field. Disclaimer
        # attached once as a structured field, not mashed into the prose.
        for field in _OBSERVATION_TEXT_FIELDS:
            if observation.get(field):
                observation[field] = apply_safe_wording(observation[field], append_disclaimer=False)
        observation["safe_limitation"] = SAFE_WORDING_DISCLAIMER

        observations.append({"observation": observation, "finding": finding})

    reasoning_json = {
        "metadata": {
            "methodology": "Deterministic PY/CY Comparison Reasoning Engine",
            "llm_used": llm_client is not None,
            "stats": stats,
        },
        "summary": {
            "executive_summary": f"Generated {len(observations)} comparison observation(s) from the PY/CY trial balance comparison."
        },
        "observations": observations,
    }

    out_file = out_dir / "comparison_reasoning.json"
    with open(out_file, "w", encoding="utf-8") as f:
        json.dump(reasoning_json, f, indent=4)
    artifacts.append(str(out_file))

    return {
        "execution_status": "SUCCESS",
        "pipeline_status": "SUCCESS",
        "message": f"Generated comparison reasoning for {len(observations)} finding(s).",
        "artifacts": artifacts,
        "errors": errors,
    }


try:
    from docx import Document
except ImportError:
    Document = None

@pipeline_tool("build_comparison_report", domain="comparison")
def build_comparison_report(output_dir: str = None, **kwargs) -> dict:
    """
    Procedural PY/CY Comparison Report Composition Engine.
    Composes a structured DOCX in the firm's audit-reasoning narrative format (Title
    -> Notice to the Reader -> Executive Summary -> 1. Scope & Inputs -> 2. Data
    Quality & Control Totals -> 3. Provisional Materiality (CY basis) -> 4. FSLI
    Summary — Current Year -> 5. Structural Delta -> 6. PY Closing -> CY Opening
    Continuity -> 7. Variance Analysis -> 8. Sign Convention Consistency -> 9. Risk
    Indicators — Current Year -> 10. Sensitive Account Categories — Current Year ->
    11. Focus Areas -> 12. Suggested Audit Focus Sequence -> 13. Limitations &
    No-Opinion Statement), matching the single-TB report's typography and
    Observed/Reasoning/Implication register. Reads the Task 1 comparison artifacts
    (precheck_results.json, structural_delta.json, comparison_variance.parquet,
    sign_convention_flags.json, comparison_reasoning.json) plus, optionally, the
    current-year single-TB run's artifacts (fsli_summary.parquet, materiality.json,
    sensitive_accounts.json, canonical_tb.parquet — located via cy_output_dir, or
    the sibling "cy" directory by default) for the CY-specific sections. Generates
    TB_Comparison_Audit.xlsx and TB_Comparison_Report.docx.
    """
    errors = []
    artifacts = []

    if Document is None:
        errors.append({"type": "ImportError", "message": "python-docx is not installed."})
        return {"execution_status": "FAILED", "errors": errors}

    out_dir = resolve_output_dir(output_dir)
    out_dir.mkdir(parents=True, exist_ok=True)

    def load_json(base_dir, filename, required=True):
        p = Path(base_dir) / filename
        if not p.exists():
            if required:
                errors.append({"type": "MissingDataWarning", "message": f"File {filename} not found in {base_dir}."})
            return None
        try:
            with open(p, "r", encoding="utf-8") as f:
                return json.load(f)
        except Exception as e:
            errors.append({"type": "ParseError", "file": filename, "error": str(e)})
            return None

    reasoning = load_json(out_dir, "comparison_reasoning.json") or {}
    precheck_data = load_json(out_dir, "precheck_results.json") or {"checks": []}
    structural_data = load_json(out_dir, "structural_delta.json") or {}
    sign_check_data = load_json(out_dir, "sign_convention_flags.json") or {"flags": []}

    variance_rows = []
    var_path = out_dir / "comparison_variance.parquet"
    if var_path.exists():
        try:
            variance_rows = pl.read_parquet(var_path).to_dicts()
        except Exception as e:
            errors.append({"type": "ParseError", "file": "comparison_variance.parquet", "error": str(e)})
    else:
        errors.append({"type": "MissingDataWarning", "message": "comparison_variance.parquet not found."})

    # CY-specific artifacts (FSLI, materiality, sensitive accounts, canonical TB) live in the
    # single-TB CY run's output directory — conventionally the sibling "cy" directory next to
    # this comparison output directory, unless overridden via cy_output_dir.
    cy_dir_override = kwargs.get("cy_output_dir")
    cy_dir = Path(cy_dir_override) if cy_dir_override else (out_dir.parent / "cy")
    if not cy_dir.exists():
        cy_dir = out_dir
    cy_materiality = load_json(cy_dir, "materiality.json", required=False) or {}
    cy_sensitive = load_json(cy_dir, "sensitive_accounts.json", required=False) or {}
    cy_fsli_df = None
    cy_fsli_path = cy_dir / "fsli_summary.parquet"
    if cy_fsli_path.exists():
        try:
            cy_fsli_df = pl.read_parquet(cy_fsli_path)
        except Exception as e:
            errors.append({"type": "ParseError", "file": "fsli_summary.parquet", "error": str(e)})
    cy_canonical_df = _load_canonical_tb(cy_dir)

    def safe_fmt(val):
        try:
            return f"{float(val):,.0f}"
        except Exception:
            return str(val)

    tb_meta_cy = load_json(cy_dir, "tb_metadata.json", required=False) or {}
    manifest_cy = load_json(cy_dir, "processing_manifest.json", required=False) or {}
    py_dir_override = kwargs.get("py_output_dir")
    py_dir = Path(py_dir_override) if py_dir_override else (out_dir.parent / "py")
    tb_meta_py = load_json(py_dir, "tb_metadata.json", required=False) or {} if py_dir.exists() else {}
    manifest_py = load_json(py_dir, "processing_manifest.json", required=False) or {} if py_dir.exists() else {}
    mapping_py = load_json(py_dir, "mapping_summary.json", required=False) or {} if py_dir.exists() else {}
    mapping_cy = load_json(cy_dir, "mapping_summary.json", required=False) or {}

    entity_label, _cy_fy, cy_source = resolve_entity_and_fy(tb_meta_cy, manifest_cy)
    _, _, py_source = resolve_entity_and_fy(tb_meta_py, manifest_py)
    stem = Path(cy_source).stem if cy_source else "Unknown Entity"
    cy_fy_match = re.search(r"FY\s*[\d\-/]+", stem, re.IGNORECASE)
    cy_fy_label = cy_fy_match.group(0).upper() if cy_fy_match else "CY"
    py_stem = Path(py_source).stem if py_source else ""
    py_fy_match = re.search(r"FY\s*[\d\-/]+", py_stem, re.IGNORECASE)
    py_fy_label = py_fy_match.group(0).upper() if py_fy_match else "PY"

    generated_at = _dt.datetime.now().strftime("%d-%b-%Y %H:%M")
    header_left = f"Generated: {generated_at}"
    header_right = f"{entity_label} - {py_fy_label} vs {cy_fy_label}"

    doc = Document()
    _apply_report_styles(doc)
    _setup_page_layout___shared(doc, header_left=header_left, header_right=header_right)

    def add_table(headers, rows):
        return _docx_add_table___shared(doc, headers, rows)

    def add_note(text, style="Body Text"):
        _docx_add_note(doc, text, style=style)

    def add_body(text, style="Body Text"):
        doc.add_paragraph(text, style=style)

    def add_bullets(items):
        for it in items:
            doc.add_paragraph(it, style="List Bullet")

    checks = precheck_data.get("checks", [])
    py_ctrl = next((c for c in checks if c.get("check") == "py_debit_credit_control_totals"), None)
    cy_ctrl = next((c for c in checks if c.get("check") == "cy_debit_credit_control_totals"), None)
    continuity_check = next((c for c in checks if c.get("check") == "opening_closing_continuity"), None)

    cy_materiality_thr = cy_materiality.get("thresholds", {})
    om = cy_materiality_thr.get("overall", 0.0)
    perf_mat = cy_materiality_thr.get("performance", 0.0)
    triv = cy_materiality_thr.get("clearly_trivial", 0.0)
    cy_summ = cy_materiality.get("summary", {})
    cy_sens_cat = cy_sensitive.get("category_summary", {})
    cy_susp = cy_sens_cat.get("suspense_control", {})

    cy_conc_rows = _concentration_rows_from_canonical(cy_canonical_df)
    cy_dormant_rows = _dormant_rows_from_canonical(cy_canonical_df)

    new_ledgers = structural_data.get("new_ledgers", [])
    removed_ledgers = structural_data.get("removed_ledgers", [])
    py_count = structural_data.get("py_count", 0)
    cy_count = structural_data.get("cy_count", 0)

    # Continuity breaks: run_comparison_prechecks.py already excludes expected P&L resets
    # (bs_pl == "PL" accounts with a nil CY opening balance -- they carry no balance
    # forward by design) from break_count/breaks at the source, so continuity_check's
    # `breaks` list here is already the genuine list -- no re-filtering needed.
    #
    # BUG FIX (comparative-analysis QA review): this used to independently re-derive
    # "P&L or not" by string-matching each break's raw main_head label against the literal
    # strings "revenue"/"expenses" -- but main_head holds sub-category labels ("Wages",
    # "Rent", "Auditor fees", ...), never those literal words, so the exclusion almost
    # never matched here (nor in build_comparison_report_markdown.py's identical copy, nor
    # in build_comparison_reasoning.py's independent HIGH-severity finding, which read the
    # same unfiltered break_count directly). Live verification against a real PY->CY
    # comparison (OVRL FY2024-25 -> FY2025-26) found 29 of 30 breaks were ordinary P&L
    # resets wrongly reported as genuine, producing a false HIGH-severity finding that
    # buried the one real (Equity) break under 29 false positives. Filtering once at the
    # source in run_comparison_prechecks.py (using the canonical bs_pl column directly,
    # not a pattern-matched label) fixes all three consumers at once.
    genuine_breaks = []
    expected_reset = 0
    total_breaks = 0
    if continuity_check:
        expected_reset = continuity_check.get("expected_pl_reset_count", 0)
        total_breaks = continuity_check.get("total_raw_break_count", continuity_check.get("break_count", 0))
        name_map = {}
        ref_df = cy_canonical_df if cy_canonical_df is not None else _load_canonical_tb(py_dir)
        if ref_df is not None and "gl_code" in ref_df.columns and "gl_name" in ref_df.columns:
            name_map = dict(zip(ref_df["gl_code"].cast(pl.Utf8).to_list(), ref_df["gl_name"].to_list()))
        for b in continuity_check.get("breaks", []):
            code = str(b.get("gl_code", ""))
            try:
                diff_val = float(b.get("diff", 0) or 0)
            except (TypeError, ValueError):
                diff_val = 0.0
            genuine_breaks.append({
                "gl_code": code, "gl_name": name_map.get(code, ""),
                "py_closing": b.get("closing_balance"), "cy_opening": b.get("opening_balance"),
                "diff": diff_val,
            })
        genuine_breaks.sort(key=lambda x: abs(x["diff"]), reverse=True)

    # "moved by more than twice overall materiality" == CRITICAL; "moved by more than the
    # threshold alone" == HIGH (>=1x overall) -- the new MEDIUM tier (>=performance
    # materiality, a lower bar than overall) is more granular than either of the two old
    # buckets and isn't folded into this narrative's two-tier framing.
    variance_flagged = [r for r in variance_rows if r.get("flag") not in (None, "NO_CHANGE")]
    high_priority = [r for r in variance_flagged if r.get("flag") == "CRITICAL"]
    medium_variance = [r for r in variance_flagged if r.get("flag") == "HIGH"]
    top_movements = sorted(variance_flagged, key=lambda r: abs(r.get("variance") or 0), reverse=True)[:10]

    flags = sign_check_data.get("flags", [])

    # -------------------------------------------------------------------------
    # Title + Notice to the Reader
    # -------------------------------------------------------------------------
    doc.add_heading(f"Trial Balance - ({entity_label}) — PY vs CY Comparative Analysis", 0)
    _docx_add_subtitle(doc, f"{py_fy_label}  →  {cy_fy_label}")
    _docx_add_notice(
        doc,
        "Notice to the reader: this document is a mechanical, evidence-based analytical review "
        "derived solely from the two trial balance files and the GL grouping workbook supplied. No "
        "external documents, confirmations, or entity knowledge were used. It is a risk-assessment "
        "and planning aid only — it contains no audit opinion and no conclusion on misstatement, "
        "fraud, non-compliance, recoverability, or going concern. All figures are shown as supplied, "
        "unscaled and in the original currency; scale (units/thousands/lakh/crore) was not stated in "
        "the source files."
    )

    # -------------------------------------------------------------------------
    # Executive Summary
    # -------------------------------------------------------------------------
    # An empty manifest until the workbook below writes the real one. Sections 4, 5, 9
    # and 11 render before the XLSX half runs, so they carry no inline schedule
    # reference in the comparative report; section 25's appendix -- rendered after the
    # manifest exists -- names every sheet without exception, which is what the
    # cross-referencing guarantee requires.
    manifest = {"workbook": None, "sheet_count": 0, "sheets": [], "unregistered_sheets": []}

    doc.add_heading("1. Executive Audit Dashboard", level=1)
    if py_count and cy_count:
        add_body(
            f"The {entity_label} trial balance {'grew' if cy_count >= py_count else 'reduced'} from "
            f"{py_count} GL accounts in {py_fy_label} to {cy_count} in {cy_fy_label}. Both years are "
            + ("internally self-balanced — debit and credit control totals match exactly in each "
               "period — so the mapping and comparison analytics below rest on a sound base rather "
               "than a data-quality artefact."
               if (py_ctrl and py_ctrl.get("status") == "PASS" and cy_ctrl and cy_ctrl.get("status") == "PASS")
               else "compared below; see Section 2 for the detailed control-total position.")
        )
    highlights = [new_ledgers or removed_ledgers, genuine_breaks, high_priority or medium_variance, flags]
    highlight_count = sum(1 for x in highlights if x)
    add_body(f"Across the two periods, {_NUMBER_WORDS.get(highlight_count, str(highlight_count)).lower()} things stand out:" if highlight_count else "Key observations:")
    if new_ledgers or removed_ledgers:
        _docx_add_lead_bullet(
            doc, "Structural change",
            f"{len(new_ledgers)} account(s) appear only in {cy_fy_label} and {len(removed_ledgers)} "
            f"only in {py_fy_label} — a {len(new_ledgers) + len(removed_ledgers)}-account "
            f"chart-of-accounts change against a base of roughly {py_count or cy_count} (Section 5)."
        )
    if total_breaks:
        _docx_add_lead_bullet(
            doc, "Continuity",
            f"{expected_reset} of {total_breaks} PY-closing-to-CY-opening differences are "
            "Revenue/Expense accounts resetting to nil, which is expected and not a control "
            f"weakness. {len(genuine_breaks)} account(s) carry a genuine, unexplained discontinuity "
            "(Section 6)." if genuine_breaks else
            f"All {total_breaks} PY-closing-to-CY-opening differences are Revenue/Expense accounts "
            "resetting to nil, which is expected and not a control weakness (Section 6)."
        )
    if high_priority or medium_variance:
        _docx_add_lead_bullet(
            doc, "Material movements",
            f"{len(high_priority)} account(s) moved by more than twice the overall materiality "
            f"threshold and a further {len(medium_variance)} moved by more than the threshold alone "
            "— each large enough to corroborate against its underlying schedule (Section 7)."
        )
    if flags:
        _docx_add_lead_bullet(
            doc, "Sign convention",
            "sign-convention screens were run for both periods; see Section 8 for the detailed "
            "per-year comparison — this is a broad screen, not a specific finding."
        )

    add_body("Where to focus first:")
    focus_first = []
    if genuine_breaks:
        top_break = genuine_breaks[0]
        focus_first.append(
            f"Section 6 — obtain the retained-earnings/continuity roll-forward and agree the "
            f"{safe_fmt(top_break['diff'])} movement on GL {top_break['gl_code']}."
        )
    if top_movements:
        top_mv = top_movements[0]
        focus_first.append(
            f"Section 7 — corroborate the largest variance accounts, especially "
            f"{top_mv.get('gl_name', '')} ({safe_fmt(top_mv.get('variance', 0))})."
        )
    if cy_conc_rows:
        top_c = cy_conc_rows[0]
        focus_first.append(
            f"Section 9 — {top_c['gl_name']} is {top_c['pct']:.1f}% of total {top_c['fs_head']} — "
            "disproportionate reliance on one balance being correctly stated."
        )
    add_bullets(focus_first or ["No high-priority focus areas were flagged deterministically in this dataset."])

    # -------------------------------------------------------------------------
    # 1. Scope & Inputs
    # -------------------------------------------------------------------------
    doc.add_heading("2. Scope, Inputs and Limitations", level=1)
    scope_rows = [
        ("Prior Year TB", py_source, str(mapping_py.get("total_tb_rows", py_count or "-")),
         str(mapping_py.get("mapped_rows", "-")), str(mapping_py.get("unmapped_rows", "-"))),
        ("Current Year TB", cy_source, str(mapping_cy.get("total_tb_rows", cy_count or "-")),
         str(mapping_cy.get("mapped_rows", "-")), str(mapping_cy.get("unmapped_rows", "-"))),
    ]
    add_table(["Input", "File", "Rows", "Accounts Mapped", "Unmapped"], scope_rows)
    add_body(
        "Grouping structure: FS Head (Assets/Liabilities/Equity/Revenue/Expenses) was derived by "
        "mapping the supplied grouping workbook's hierarchy to its statement classification, "
        "applied consistently across both periods."
    )

    # -------------------------------------------------------------------------
    # 2. Data Quality & Control Totals
    # -------------------------------------------------------------------------
    doc.add_heading("3. TB Integrity and Reconciliation", level=1)
    if py_ctrl or cy_ctrl:
        add_table(
            ["Check", f"{py_fy_label} (PY)", f"{cy_fy_label} (CY)"],
            [
                ("Total Debit", safe_fmt((py_ctrl or {}).get("total_debit", 0)), safe_fmt((cy_ctrl or {}).get("total_debit", 0))),
                ("Total Credit", safe_fmt((py_ctrl or {}).get("total_credit", 0)), safe_fmt((cy_ctrl or {}).get("total_credit", 0))),
                ("Debit − Credit Difference", safe_fmt((py_ctrl or {}).get("diff", 0)), safe_fmt((cy_ctrl or {}).get("diff", 0))),
            ],
        )
        both_pass = (py_ctrl or {}).get("status") == "PASS" and (cy_ctrl or {}).get("status") == "PASS"
        add_body(
            "Observed: debit and credit control totals "
            + ("match exactly in both periods (zero difference)." if both_pass else
               "do not match exactly in one or both periods — see the status flags above.")
        )
        add_body(
            "Implication: the underlying trial balance extracts are internally consistent before any "
            "grouping logic is applied. This is a necessary precondition for every analytic that "
            "follows — it does not by itself confirm the TB agrees to the general ledger or statutory "
            "accounts, only that the files as supplied are arithmetically sound."
        )
    else:
        add_body("Control totals could not be computed — precheck_results.json was not available.")

    # -------------------------------------------------------------------------
    # 6. PY Closing → CY Opening Continuity
    # -------------------------------------------------------------------------
    doc.add_heading("PY closing to CY opening continuity", level=2)
    if continuity_check:
        add_body(
            f"Observed: {total_breaks} account(s) show a difference between PY closing balance and "
            "CY opening balance beyond a rounding tolerance."
        )
        add_body(
            f"Difference decomposed: {expected_reset} of these {total_breaks} breaks are Revenue and "
            "Expense accounts whose opening balance is nil in both periods — this is the expected "
            "behaviour for P&L accounts, which reset to zero at the start of every financial year "
            "rather than carrying forward a balance, so these do not indicate a continuity problem."
            + (f" Removing them leaves {len(genuine_breaks)} account(s) with a genuine "
               "opening-to-closing mismatch:" if genuine_breaks else " No genuine continuity breaks remain after removing them.")
        )
        if genuine_breaks:
            add_table(
                ["GL Code", "GL Name", "PY Closing", "CY Opening", "Difference"],
                [(b["gl_code"], b["gl_name"], safe_fmt(b["py_closing"]), safe_fmt(b["cy_opening"]), safe_fmt(b["diff"])) for b in genuine_breaks[:10]],
            )
            add_body(
                "Audit concern: a genuine PY-closing-to-CY-opening mismatch outside the P&L reset "
                "pattern is the single most consequential item this comparison can flag, since it sits "
                "directly in opening equity or another carry-forward balance — a common reference "
                "point for both the balance sheet and the statement of changes in equity."
            )
            add_body(
                "Recommended procedure: obtain the entity's roll-forward schedule for each flagged "
                "account (opening balance, current-year movement, any restatement, closing balance) "
                "and agree the difference to it before relying on the CY opening position."
            )
    else:
        add_body("Continuity check data was not available for this comparison run.")

    # -------------------------------------------------------------------------
    # 8. Sign Convention Consistency
    # -------------------------------------------------------------------------
    doc.add_heading("Sign convention consistency", level=2)
    if flags:
        add_table(
            ["Period", "Status", "Detail"],
            [(f.get("year", ""), f.get("status", ""),
              f"debit anchors {f.get('debit_anchors', '-')} ({f.get('debit_positive_pct', '-')}% positive), "
              f"credit anchors {f.get('credit_anchors', '-')} ({f.get('credit_negative_pct', '-')}% negative)")
             for f in flags],
        )
        add_body(
            "Reasoning: this is a broad screen for mixed sign conventions in the source file, run "
            "independently for each period. A stable rate across both periods is more consistent with "
            "a structural feature of the chart of accounts than with a new classification problem "
            "introduced in the current year."
        )
        add_body(
            "Implication: each flagged account should be checked against its expected nature before "
            "being treated as a misclassification — this is a screen, not a defect finding."
        )
    else:
        add_body("No sign convention flags available.")
    _write_front_sections(doc, cy_dir, manifest, add_body, add_note, add_table,
                          add_bullets, safe_fmt, sections=(4, 5))

    # -------------------------------------------------------------------------
    # 3. Provisional Materiality (CY basis)
    # -------------------------------------------------------------------------
    doc.add_heading("6. Materiality Assessment (CY basis)", level=1)
    if cy_materiality:
        add_table(
            ["Basis", "Value"],
            [
                ("Materiality Basis Used", cy_summ.get("benchmark_used", "Unknown")),
                ("Overall Materiality", safe_fmt(om)),
                ("Performance Materiality (75% of OM)", safe_fmt(perf_mat)),
                ("Clearly Trivial Threshold", safe_fmt(triv)),
            ],
        )
        add_note(
            "Provisional only — a mechanical benchmark-based calculation on the current-year trial "
            "balance. Not a substitute for engagement-level materiality judgment.",
            style="Normal",
        )
    else:
        add_body("Current-year materiality was not available for this comparison run.")

    # -------------------------------------------------------------------------
    # 5. Structural Delta — PY vs CY Ledger Composition
    # -------------------------------------------------------------------------
    doc.add_heading("7. Comparative Analytical Review", level=1)
    if structural_data:
        add_body(structural_data.get(
            "message", f"{py_fy_label} ledgers: {py_count}, {cy_fy_label} ledgers: {cy_count}."
        ))
        if new_ledgers or removed_ledgers:
            add_body(
                "Implication: chart-of-accounts change of this magnitude is ordinary for a company "
                "refining its ledger structure year over year. The recommended procedure is "
                "confirmatory rather than investigative: obtain the approved chart-of-accounts change "
                "log (if one exists) and agree the additions/deletions to it."
            )
        if new_ledgers:
            doc.add_heading(f"Sample of accounts added in {cy_fy_label} (not present in {py_fy_label})", level=2)
            add_table(["GL Code", "GL Name"], [(g.get("gl_code", ""), g.get("gl_name", "")) for g in new_ledgers[:15]])
        if removed_ledgers:
            doc.add_heading(f"Sample of accounts removed from {py_fy_label} (not present in {cy_fy_label})", level=2)
            add_table(["GL Code", "GL Name"], [(g.get("gl_code", ""), g.get("gl_name", "")) for g in removed_ledgers[:15]])
        add_note(
            "Full lists of added/removed ledgers are provided in the accompanying Excel workbook "
            "(sheets \"New Ledgers (CY)\" / \"Removed Ledgers (PY)\")."
        )
    else:
        add_body("No structural delta data available.")

    # -------------------------------------------------------------------------
    # 7. Variance Analysis — PY vs CY Closing Balance
    # -------------------------------------------------------------------------
    doc.add_heading("Variance analysis — PY vs CY closing balance", level=2)
    if variance_rows:
        add_body(
            f"Observed: variance is computed for the {len(variance_rows)} account(s) present in "
            f"either period and flagged against materiality. {len(high_priority)} account(s) moved "
            f"by more than twice overall materiality and a further {len(medium_variance)} moved by "
            "more than the threshold alone."
        )
        flag_counts = {}
        for r in variance_rows:
            flag_counts[r.get("flag", "UNKNOWN")] = flag_counts.get(r.get("flag", "UNKNOWN"), 0) + 1
        add_table(
            ["Flag", "Account Count"],
            [(flag, str(count)) for flag, count in sorted(flag_counts.items(), key=lambda x: -x[1])],
        )
        if top_movements:
            doc.add_heading("Top Material Movements (by absolute variance)", level=2)
            add_table(
                ["GL Code", "GL Name", "PY Closing", "CY Closing", "Variance", "Flag"],
                [(r.get("gl_code", ""), r.get("gl_name", ""), safe_fmt(r.get("py_closing", 0)),
                  safe_fmt(r.get("cy_closing", 0)), safe_fmt(r.get("variance", 0)), r.get("flag", "")) for r in top_movements],
            )
            add_body(
                "Implication: none of these, on the trial balance alone, can be confirmed as correctly "
                "stated — only that each has a plausible operational story worth corroborating against "
                "its underlying schedule."
            )
            add_body(
                "Recommended procedure: obtain management's explanation and the supporting schedule "
                "for each CRITICAL-flagged account above before relying on the movement."
            )
    else:
        add_body("No variance data available.")

    # -------------------------------------------------------------------------
    # 4. FSLI Summary — Current Year
    # -------------------------------------------------------------------------
    doc.add_heading("8. FSLI and Ledger-Level Movements (Current Year)", level=1)
    if cy_fsli_df is not None and not cy_fsli_df.is_empty():
        if "hierarchy_level" in cy_fsli_df.columns:
            lvl1 = cy_fsli_df.filter(pl.col("hierarchy_level") == 1)
        else:
            lvl1 = cy_fsli_df
        lvl1 = lvl1.with_columns(pl.col("closing_balance").abs().alias("_abs")).sort("_abs", descending=True)
        fsli_rows = [
            (r.get("main_head") or r.get("fs_head") or r.get("line_item") or "",
             int(r.get("descendant_gl_count") or r.get("leaf_gl_count") or r.get("gl_accounts") or 0),
             safe_fmt(r.get("closing_balance", 0.0)))
            for r in lvl1.iter_rows(named=True)
        ]
        add_table(["FS Head", "GL Accounts", "Closing Balance (CY)"], fsli_rows)
    else:
        add_body("Current-year FSLI summary was not available for this comparison run.")
    _write_front_sections(doc, cy_dir, manifest, add_body, add_note, add_table,
                          add_bullets, safe_fmt, sections=(9,))

    # -------------------------------------------------------------------------
    # 9. Risk Indicators — Current Year
    # -------------------------------------------------------------------------
    doc.add_heading("10. Account-Risk Scoring (Current Year)", level=1)
    doc.add_heading("Concentration — accounts exceeding 5% of their FS Head", level=2)
    if cy_conc_rows:
        add_table(
            ["GL Code", "GL Name", "FS Head", "Closing Balance", "% of FS Head"],
            [(c["gl_code"], c["gl_name"], c["fs_head"], safe_fmt(c["closing"]), f"{c['pct']:.1f}%") for c in cy_conc_rows],
        )
    else:
        add_body("No account individually exceeds 5% of its FS Head in the current-year dataset.")
    doc.add_heading("Dormant accounts (no debit/credit movement in year) with material closing balance", level=2)
    if cy_dormant_rows:
        add_table(
            ["GL Code", "GL Name", "FS Head", "Closing Balance"],
            [(d["gl_code"], d["gl_name"], d["fs_head"], safe_fmt(d["closing"])) for d in cy_dormant_rows],
        )
    else:
        add_body("No dormant accounts with a material closing balance were identified in the current-year dataset.")
    _write_front_sections(doc, cy_dir, manifest, add_body, add_note, add_table,
                          add_bullets, safe_fmt, sections=(11,))

    # Narrated comparison observations, read once. Sections 17 and 22 both consume
    # this, so it is assigned in the enclosing scope rather than inside either closure.
    observations = reasoning.get("observations", [])

    # Rendered inside sections 12, 17 and 22 by _write_phase4_sections. Passed as
    # closures rather than moved, because each reads this function's own locals.
    def _render_sensitive_categories():

        # -------------------------------------------------------------------------
        # 10. Sensitive Account Categories — Current Year
        # -------------------------------------------------------------------------
        doc.add_heading("Sensitive account categories (Current Year)", level=2)
        if cy_sens_cat:
            sens_rows = [(k.replace("_", " "), str(v.get("count", 0)), safe_fmt(v.get("total_balance", 0))) for k, v in cy_sens_cat.items()]
            add_table(["Category", "Accounts", "Combined Closing Balance"], sens_rows)
            add_body(
                "These categories are name-pattern screens over the CY account list, not confirmed "
                "classifications, and each should be verified individually rather than relied upon as a "
                "complete or precise population."
            )
            if cy_susp.get("count"):
                add_body(
                    f"The suspense/control tag carries {safe_fmt(cy_susp.get('total_balance', 0))} "
                    "combined exposure and is the category most worth reconciling first."
                )
        else:
            add_body("Current-year sensitive-account categories were not available for this comparison run.")

    def _render_focus_areas():

        # -------------------------------------------------------------------------
        # 11. Focus Areas
        # -------------------------------------------------------------------------
        doc.add_heading("Narrated focus areas", level=2)
        if observations:
            for i, obs_wrap in enumerate(observations, start=1):
                obs = obs_wrap.get("observation", obs_wrap) if isinstance(obs_wrap, dict) else {}
                sev = str(obs.get("priority", "LOW")).upper()
                title = obs.get("title", "Comparison Finding")
                _docx_add_severity_heading___shared(doc, f"F{i:02d}", sev, title, level=2)
                add_body(f"Observation and Gap: {obs.get('detailed_observation', obs.get('executive_summary', ''))}")
                assertions = obs.get("affected_assertions", [])
                add_body(f"Assertions/Risk Basis: {', '.join(assertions)}. Risk Rating: {sev}", style="Normal")
                procs = obs.get("recommended_procedures", [])
                add_body(f"Evidence Requested: {', '.join(procs) if procs else 'reconciliation, ledger dump'}")
        else:
            add_body("No comparison observations were generated for this dataset.")

    def _render_focus_sequence():

        # -------------------------------------------------------------------------
        # 12. Suggested Audit Focus Sequence
        # -------------------------------------------------------------------------
        doc.add_heading("Suggested focus sequence", level=2)
        add_note("Priority order for planning, driven by risk-ranked findings across both periods.")
        seq_count = 0
        for obs_wrap in observations:
            obs = obs_wrap.get("observation", obs_wrap) if isinstance(obs_wrap, dict) else {}
            sev = str(obs.get("priority", "LOW")).upper()
            if sev not in ("CRITICAL", "HIGH", "MEDIUM"):
                continue
            name = obs.get("title", "")
            reason = obs.get("executive_summary", "")
            doc.add_paragraph(f"{name} — {sev}-rated finding: {reason}", style="List Bullet")
            seq_count += 1
        if seq_count == 0:
            add_body("No High/Medium-rated findings to sequence for audit focus.")


    # The Word document is saved AFTER the workbook below, not here: sections 12-25
    # cross-reference the schedule manifest, and the manifest does not exist until
    # build_comparison_report's XLSX half has written it. python-docx holds the
    # document in memory until save(), so deferring costs nothing.
    docx_path = out_dir / "TB_Comparison_Report.docx"

    # -------------------------------------------------------------------------
    # XLSX — Comparative TB Review (12 sheets), matching TB_Comparative_Review.xlsx
    # -------------------------------------------------------------------------
    excel_path = out_dir / "TB_Comparison_Audit.xlsx"

    try:
        cy_canonical_path = cy_dir / "canonical_tb.parquet"
        py_canonical_path = py_dir / "canonical_tb.parquet"
        if not cy_canonical_path.exists() or not py_canonical_path.exists():
            missing = cy_canonical_path if not cy_canonical_path.exists() else py_canonical_path
            errors.append({"type": "FileNotFoundError", "file": str(missing)})
            return {"execution_status": "FAILED", "errors": errors, "message": "canonical_tb.parquet not found for CY/PY."}

        # Canonical TB (CY)/(PY) sheets show raw joined data, not a computed analytic --
        # _load_canonical_tb_for_report's report_fs_head/report_fsli/report_note labels
        # are the right fit for a full-TB row dump and stay as-is.
        cy = _load_canonical_tb_for_report(cy_canonical_path)
        py = _load_canonical_tb_for_report(py_canonical_path)

        # BUG FIX (comparative-analysis QA review, follow-up): every analytic below used
        # to be independently recomputed here via backend/tools/comparison/_shared.py's
        # private _compute_* engine (11 functions) -- a parallel implementation to the one
        # feeding the DOCX/Markdown report (spine artifacts already loaded earlier in this
        # function: cy_materiality, cy_sensitive, cy_fsli_df, precheck_data,
        # structural_data, variance_rows, genuine_breaks) and, for concentration/dormant/
        # sign-convention, to the already-fixed canonical functions in the MAIN
        # backend/tools/_shared.py (TB-R13/R14/R15). Two non-communicating
        # implementations of the same concept is exactly the TB-R06 pattern from the
        # original defect registry -- confirmed concretely for Variance (Excel showed
        # CRITICAL via _movement_flag_for_report while the report showed NO_THRESHOLD via
        # a completely different, broken vocabulary in run_comparison_variance.py) and for
        # Continuity Breaks (_compute_continuity_breaks had ZERO P&L-reset exclusion, so
        # the Excel "Continuity Breaks" tab never got last session's fix at all). Every
        # sheet below now reads the same spine data the DOCX/Markdown report reads, or
        # calls the same already-fixed canonical functions single-TB reports use.
        cy_classified = load_canonical_tb(cy_canonical_path)
        py_classified = load_canonical_tb(py_canonical_path)

        dq_cy = control_totals(cy_classified) or {}
        dq_py = control_totals(py_classified) or {}

        # om/perf_mat/triv already resolved from cy_materiality_thr earlier in this
        # function for the DOCX section -- reused here, not recomputed.
        conc_rows_xlsx = concentration_rows_from_canonical(cy_classified, clearly_trivial=triv)
        dormant_rows_xlsx = dormant_rows_from_canonical(cy_classified)
        sign_stats_cy = sign_convention_stats(cy_classified) or {}
        sign_stats_py = sign_convention_stats(py_classified) or {}

        sensitive_df_xlsx = None
        sensitive_pq_path = cy_dir / "sensitive_accounts.parquet"
        if sensitive_pq_path.exists():
            try:
                sensitive_df_xlsx = pl.read_parquet(sensitive_pq_path)
            except Exception as e:
                errors.append({"type": "ParseError", "file": "sensitive_accounts.parquet", "error": str(e)})

        # Display-only lookups (gl_code -> report head/name/closing) for spine records
        # that carry only gl_code/gl_name (structural_data's new/removed ledgers) or no FS
        # classification at all (variance_rows) -- not a recomputation of any analytic,
        # just labeling already-computed rows for display.
        head_by_code, closing_by_code = {}, {}
        if cy_classified is not None and "gl_code" in cy_classified.columns:
            head_by_code.update(dict(zip(cy_classified["gl_code"].cast(pl.Utf8).to_list(), cy_classified["report_head"].to_list())))
            closing_by_code.update(dict(zip(cy_classified["gl_code"].cast(pl.Utf8).to_list(), cy_classified["closing_balance"].to_list())))
        py_head_by_code, py_closing_by_code = {}, {}
        if py_classified is not None and "gl_code" in py_classified.columns:
            py_head_by_code.update(dict(zip(py_classified["gl_code"].cast(pl.Utf8).to_list(), py_classified["report_head"].to_list())))
            py_closing_by_code.update(dict(zip(py_classified["gl_code"].cast(pl.Utf8).to_list(), py_classified["closing_balance"].to_list())))

        cy_full_fy = _fy_label(cy_dir / "tb_metadata.json", cy_fy_label)
        py_full_fy = _fy_label(py_dir / "tb_metadata.json", py_fy_label)

        def _short_fy(label):
            m = re.search(r"(\d{2})\D*$", label)
            return f"FY{m.group(1)}" if m else label

        py_label_short = _short_fy(py_full_fy)
        cy_label_short = _short_fy(cy_full_fy)

        registry_problems = validate_registry()

        if registry_problems:

            errors.append({"type": "ScheduleRegistryError", "problems": registry_problems})

            return {"execution_status": "FAILED", "errors": errors,

                    "message": f"Schedule registry invalid: {registry_problems}"}


        wb = Workbook()

        wb.remove(wb.active)


        # Every sheet is created through this helper so the manifest cannot fall out

        # of step with the workbook -- the Word document cross-references the

        # manifest, so a sheet created directly would exist but never be cited.

        sheets_written = []


        def new_sheet(name: str):

            if name not in SCHEDULES:

                raise KeyError(

                    f"Sheet {name!r} is not in backend/tools/_report_schedules.py::SCHEDULES. "

                    "Add it there so the Word document can reference it."

                )

            sheets_written.append(name)

            return wb.create_sheet(name)

        # 1. Data Quality
        ws = new_sheet("Data Quality")
        _write_sheet_title(ws, "Data Quality & Control Totals",
                            "Layer-1 style checks on the raw TB files, prior to any grouping join", 4)
        dq_keys = [
            ("Total Debit", "total_debit"), ("Total Credit", "total_credit"),
            ("Debit − Credit Difference", "difference"), ("Sum of Closing Balances (tie-out)", "sum_closing"),
            ("Duplicate GL Codes", "duplicate_gl_codes"), ("Fully Zero Rows", "fully_zero_rows"),
        ]
        dq_table_rows = [[label, dq_py.get(key, 0), dq_cy.get(key, 0)] for label, key in dq_keys]
        _write_table(ws, 4, ["Check", f"{py_label_short} (PY)", f"{cy_label_short} (CY)"],
                     dq_table_rows, formats=[None, _ACC_FMT, _ACC_FMT])
        ws.freeze_panes = "A5"
        _set_col_widths(ws, {"A": 34, "B": 20, "C": 20})

        # 2. Materiality (CY basis) -- reads cy_materiality (materiality.json), already
        # loaded for the DOCX section, instead of recomputing.
        ws = new_sheet("Materiality")
        _write_sheet_title(ws, "Provisional Planning Materiality",
                            "CY figures, from the CY single-TB run. Not a substitute for engagement-level judgment.", 3)
        mat_rows = [
            ("Materiality Basis Used", cy_summ.get("benchmark_used", "Unknown")),
            ("Overall Materiality", om),
            ("Performance Materiality (75% of OM)", perf_mat),
            ("Clearly Trivial Threshold", triv),
        ]
        _write_table(ws, 4, ["Basis", "Value"], mat_rows, formats=[None, _ACC_FMT])
        ws.freeze_panes = "A5"
        _set_col_widths(ws, {"A": 38, "B": 22})

        # 3. FSLI Summary (CY) -- reads cy_fsli_df (fsli_summary.parquet), already loaded
        # for the DOCX section, instead of recomputing from the raw canonical TB.
        ws = new_sheet("FSLI Summary")
        _write_sheet_title(ws, "FSLI Summary — Current Year", "Aggregated by FS Head / FSLI from the fsli_summary spine artifact", 7)
        fsli_lvl1 = []
        if cy_fsli_df is not None and not cy_fsli_df.is_empty() and "main_head" in cy_fsli_df.columns:
            lvl1_df = cy_fsli_df
            if "hierarchy_level" in lvl1_df.columns:
                lvl1_df = lvl1_df.filter(pl.col("hierarchy_level") == 1)
            fsli_lvl1 = lvl1_df.to_dicts()
        fsli_table_rows = [
            [f.get("main_head") or "", f.get("sub_head_1") or "",
             int(f.get("descendant_gl_count") or f.get("gl_accounts") or f.get("leaf_gl_count") or 0),
             f.get("opening_balance", 0.0), f.get("debit", 0.0), f.get("credit", 0.0), f.get("closing_balance", 0.0)]
            for f in fsli_lvl1
        ]
        _write_table(ws, 4, ["FS Head", "FSLI", "GL Accounts", "Opening", "Debit", "Credit", "Closing"],
                     fsli_table_rows, formats=[None, None, _ACC_FMT, _ACC_FMT, _ACC_FMT, _ACC_FMT, _ACC_FMT])
        ws.freeze_panes = "A5"
        _set_col_widths(ws, {"A": 16, "B": 30, "C": 12, "D": 18, "E": 18, "F": 18, "G": 18})

        def _display_note(r):
            return None if r["report_fs_head"] == "Unmapped" else r["report_note"]

        def _display_status(r):
            return "UNMAPPED" if r["report_fs_head"] == "Unmapped" else "MAPPED"

        def _as_business_area(v):
            try:
                return int(float(v))
            except (TypeError, ValueError):
                return v

        def _write_canonical_sheet(sheet_name, df_period, period_label):
            # Through new_sheet, not wb.create_sheet: a sheet created directly would
            # exist in the workbook but never enter the manifest, and so never be
            # referenced from the Word document. The cross-reference test caught
            # exactly that for these two sheets.
            ws = new_sheet(sheet_name)
            _write_sheet_title(ws, f"Canonical Trial Balance — {period_label}",
                                "Full TB joined to grouping ground truth", 9)
            rows = [
                [r.get("gl_code"), r.get("gl_name"), _as_business_area(r.get("business area")),
                 r["opening_balance"], r["debit"], r["credit"], r["closing_balance"],
                 r["report_fs_head"], r["report_fsli"], _display_note(r), _display_status(r)]
                for r in df_period.to_dicts()
            ]
            _write_table(ws, 4, ["GL Code", "GL Name", "Business Area", "Opening", "Debit", "Credit", "Closing", "FS Head", "FSLI", "Note", "Mapping Status"],
                         rows, formats=[None, None, None, _ACC_FMT, _ACC_FMT, _ACC_FMT, _ACC_FMT, None, None, None, None])
            ws.freeze_panes = "A5"
            _set_col_widths(ws, {"A": 10, "B": 34, "C": 10, "D": 16, "E": 14, "F": 14, "G": 14, "H": 12, "I": 22, "J": 30, "K": 16})

        # 4. Canonical TB (CY)
        _write_canonical_sheet("Canonical TB (CY)", cy, f"{cy_full_fy} (CY)")
        # 5. Canonical TB (PY)
        _write_canonical_sheet("Canonical TB (PY)", py, f"{py_full_fy} (PY)")

        # 6. Variance -- reads variance_rows (comparison_variance.parquet), already loaded
        # for the DOCX section, instead of recomputing. Same flag vocabulary the DOCX
        # report's §7 uses (post run_comparison_variance.py's vocabulary fix), so Excel
        # and DOCX now agree by construction.
        ws = new_sheet("Variance")
        _write_sheet_title(ws, "PY vs CY Variance Analysis",
                            "Common accounts only — materiality-flagged closing-balance movement", 8)
        var_rows = [
            [r.get("gl_code"), r.get("gl_name"), head_by_code.get(str(r.get("gl_code", ""))) or "",
             r.get("py_closing"), r.get("cy_closing"), r.get("variance"), r.get("variance_pct"), r.get("flag")]
            for r in variance_rows
        ]
        _write_table(ws, 4, ["GL Code", "GL Name", "FS Head", "PY Closing", "CY Closing", "Variance", "Variance %", "Flag"],
                     var_rows, formats=[None, None, None, _ACC_FMT, _ACC_FMT, _ACC_FMT, None, None])
        ws.freeze_panes = "A5"
        _set_col_widths(ws, {"A": 10, "B": 32, "C": 12, "D": 18, "E": 18, "F": 18, "G": 12, "H": 12})

        # 7. New Ledgers (CY) -- reads structural_data (structural_delta.json), already
        # loaded for the DOCX section, instead of recomputing.
        ws = new_sheet("New Ledgers (CY)")
        _write_sheet_title(ws, "New Ledgers — Present in CY, Not in PY", None, 4)
        new_rows = [
            [g.get("gl_code"), g.get("gl_name"), head_by_code.get(str(g.get("gl_code", ""))) or "", closing_by_code.get(str(g.get("gl_code", "")), 0.0)]
            for g in new_ledgers
        ]
        _write_table(ws, 4, ["GL Code", "GL Name", "FS Head", "CY Closing"], new_rows, formats=[None, None, None, _ACC_FMT])
        ws.freeze_panes = "A5"
        _set_col_widths(ws, {"A": 10, "B": 40, "C": 14, "D": 18})

        # 8. Removed Ledgers (PY) -- same source as New Ledgers.
        ws = new_sheet("Removed Ledgers (PY)")
        _write_sheet_title(ws, "Removed Ledgers — Present in PY, Not in CY", None, 4)
        removed_rows = [
            [g.get("gl_code"), g.get("gl_name"), py_head_by_code.get(str(g.get("gl_code", ""))) or "", py_closing_by_code.get(str(g.get("gl_code", "")), 0.0)]
            for g in removed_ledgers
        ]
        _write_table(ws, 4, ["GL Code", "GL Name", "FS Head", "PY Closing"], removed_rows, formats=[None, None, None, _ACC_FMT])
        ws.freeze_panes = "A5"
        _set_col_widths(ws, {"A": 10, "B": 40, "C": 14, "D": 18})

        # 9. Continuity Breaks -- reads genuine_breaks, already computed for the DOCX
        # section from precheck_results.json's opening_closing_continuity check, which
        # run_comparison_prechecks.py already excludes expected P&L resets from at the
        # source. The old _compute_continuity_breaks had NO P&L-reset exclusion at all, so
        # this tab previously showed the same false positives the DOCX report used to.
        ws = new_sheet("Continuity Breaks")
        _write_sheet_title(ws, "PY Closing → CY Opening Continuity Breaks (genuine only — P&L resets excluded)",
                            "Common accounts where PY closing ≠ CY opening beyond tolerance, excluding expected P&L resets", 5)
        cont_rows = [[b["gl_code"], b["gl_name"], b["py_closing"], b["cy_opening"], b["diff"]] for b in genuine_breaks]
        _write_table(ws, 4, ["GL Code", "GL Name", "PY Closing", "CY Opening", "Difference"],
                     cont_rows, formats=[None, None, _ACC_FMT, _ACC_FMT, _ACC_FMT])
        ws.freeze_panes = "A5"
        _set_col_widths(ws, {"A": 10, "B": 34, "C": 18, "D": 18, "E": 18})

        # 10. Sign Convention -- calls the same canonical backend/tools/_shared.py::
        # sign_convention_stats() single-TB reports use, called once per period, instead
        # of a comparison-specific reimplementation.
        ws = new_sheet("Sign Convention")
        _write_sheet_title(ws, "Sign Convention Consistency", "Accounts sitting opposite their FS Head normal side", 7)
        sign_rows_tbl = [
            [f"{py_label_short} (PY)", sign_stats_py.get("debit_flip", 0), sign_stats_py.get("debit_total", 0), sign_stats_py.get("debit_flip_pct", 0.0),
             sign_stats_py.get("credit_flip", 0), sign_stats_py.get("credit_total", 0), sign_stats_py.get("credit_flip_pct", 0.0)],
            [f"{cy_label_short} (CY)", sign_stats_cy.get("debit_flip", 0), sign_stats_cy.get("debit_total", 0), sign_stats_cy.get("debit_flip_pct", 0.0),
             sign_stats_cy.get("credit_flip", 0), sign_stats_cy.get("credit_total", 0), sign_stats_cy.get("credit_flip_pct", 0.0)],
        ]
        _write_table(ws, 4, ["Period", "Debit-side w/ Credit Balance", "Debit-side Total", "% Anomalous (Debit)",
                              "Credit-side w/ Debit Balance", "Credit-side Total", "% Anomalous (Credit)"],
                     sign_rows_tbl, formats=[None, _ACC_FMT, _ACC_FMT, None, _ACC_FMT, _ACC_FMT, None])
        ws.freeze_panes = "A5"
        _set_col_widths(ws, {"A": 12, "B": 22, "C": 16, "D": 18, "E": 22, "F": 16, "G": 18})

        # 11. Risk Indicators (CY) -- concentration/dormant now call the already-fixed
        # canonical functions in the main backend/tools/_shared.py (TB-R13/R14 contra-pair
        # netting and denominator-degeneracy guard, TB-R15 estimation-risk tagging), the
        # same ones the DOCX report's §7/single-TB reports use, instead of a comparison-
        # local reimplementation with none of those fixes. Sign anomalies rendered as
        # aggregate stats (sign_stats_cy, already computed above), matching how single-TB's
        # Excel sheet renders this post-Phase-1, instead of a per-account list.
        ws = new_sheet("Risk Indicators")
        _write_sheet_title(ws, "Risk Indicators — Current Year", "Concentration / dormant-balance / sign-convention screens", 6)
        r = _write_section_header(ws, 4, "Concentration (>5% of FS Head)")
        conc_rows = [[c["gl_code"], c["gl_name"], c["fs_head"], c["closing"], c["pct"], c.get("note", "")] for c in conc_rows_xlsx]
        r = _write_table(ws, r, ["GL Code", "GL Name", "FS Head", "Closing", "% of FS Head", "Note"],
                          conc_rows, formats=[None, None, None, _ACC_FMT, _PCT_FMT, None])
        r += 2
        r = _write_section_header(ws, r, "Dormant Accounts (no movement, material balance)")
        dorm_rows = [
            [d["gl_code"], d["gl_name"], d["fs_head"], d["closing"], "ESTIMATION RISK" if d.get("is_estimation_risk") else ""]
            for d in dormant_rows_xlsx
        ]
        r = _write_table(ws, r, ["GL Code", "GL Name", "FS Head", "Closing", "Flag"], dorm_rows, formats=[None, None, None, _ACC_FMT, None])
        r += 2
        r = _write_section_header(ws, r, "Sign Convention Consistency")
        sign_anomaly_rows = [
            ["Debit-side (Assets/Expenses) w/ credit balance", sign_stats_cy.get("debit_flip", 0), sign_stats_cy.get("debit_total", 0), f"{sign_stats_cy.get('debit_flip_pct', 0.0)}%"],
            ["Credit-side (Liabilities/Equity/Revenue) w/ debit balance", sign_stats_cy.get("credit_flip", 0), sign_stats_cy.get("credit_total", 0), f"{sign_stats_cy.get('credit_flip_pct', 0.0)}%"],
        ]
        _write_table(ws, r, ["Screen", "Flagged", "Total in Group", "% Flagged"], sign_anomaly_rows,
                     formats=[None, _ACC_FMT, _ACC_FMT, None])
        _set_col_widths(ws, {"A": 40, "B": 30, "C": 12, "D": 18, "E": 14})

        # 12. Sensitive Accounts (CY) -- reads sensitive_accounts.parquet's real per-account
        # classification (loaded above as sensitive_df_xlsx), the same file single-TB's
        # Excel sheet reads post-Phase-1, instead of a comparison-local keyword re-scan.
        ws = new_sheet("Sensitive Accounts")
        _write_sheet_title(ws, "Sensitive Account Categories — Current Year",
                            "Related party / grant-subsidy / MSME / CSR / statutory-dues / suspense / propriety / deposits / advances / FCY", 4)
        r = 4
        if sensitive_df_xlsx is not None and not sensitive_df_xlsx.is_empty() and "category" in sensitive_df_xlsx.columns:
            for category in sensitive_df_xlsx["category"].unique(maintain_order=True).sort().to_list():
                sub = sensitive_df_xlsx.filter(pl.col("category") == category).sort("gl_code")
                r = _write_section_header(ws, r, str(category).replace("_", " ").title())
                cat_rows = [[a["gl_code"], a["gl_name"], a["balance"], a["priority"]] for a in sub.to_dicts()]
                r = _write_table(ws, r, ["GL Code", "GL Name", "Closing", "Priority"], cat_rows, formats=[None, None, _ACC_FMT, None])
                r += 1
        _set_col_widths(ws, {"A": 26, "B": 40, "C": 18, "D": 12})

        # The current-year leg ran the full single-TB analytics chain, so its Phase-2

        # populations exist in cy_dir. They are carried into this workbook so the

        # comparative report can reference the same complete populations the

        # single-TB report does, rather than sending a reader to a second workbook.

        _cy_population_sheets(new_sheet, cy_dir)


        resolved = []

        for _name in sheets_written:

            _ws = wb[_name]

            resolved.append((_name, max(_ws.max_row - 4, 0)))


        wb.save(excel_path)

        artifacts.append(str(excel_path.resolve()))


        manifest_path = write_manifest(out_dir, resolved, excel_path.name)

        artifacts.append(str(manifest_path.resolve()))

        # Sections 12-25 and the schedule appendix, now that the manifest exists.
        manifest = read_manifest(out_dir)
        _write_phase4_sections(doc, cy_dir, manifest, add_body, add_note, add_table,
                               add_bullets, safe_fmt,
                               render_sensitive=_render_sensitive_categories,
                               render_focus_areas=_render_focus_areas,
                               render_focus_sequence=_render_focus_sequence)
        _write_limitations_section(doc, f"{py_source} and {cy_source}", comparative=True)
        _write_schedule_appendix(doc, manifest, add_body, add_note, add_table)

        try:
            doc.save(docx_path)
            artifacts.append(str(docx_path))
        except Exception as e:
            errors.append({"type": "ExportError", "error": str(e),
                           "traceback": traceback.format_exc()})
            return {"execution_status": "FAILED", "errors": errors,
                    "message": f"Failed to save comparison DOCX: {e}"}
    except Exception as e:
        errors.append({"type": "ExcelError", "error": str(e)})
        errors.append({"traceback": traceback.format_exc()})
        return {"execution_status": "FAILED", "errors": errors, "message": "Failed to create comparison Excel report."}

    return {
        "execution_status": "SUCCESS",
        "pipeline_status": "SUCCESS",
        "message": f"Generated TB_Comparison_Audit.xlsx and TB_Comparison_Report.docx in {out_dir}.",
        "artifacts": artifacts,
        "errors": errors,
    }

_CY_POPULATIONS = [
    ("Findings Register", "finding_records.json", "finding_records",
     ["source_screen", "account", "fsli", "amount", "risk_rating", "regularity_flag",
      "observation", "expectation", "gap", "assertion", "proposed_response",
      "evidence_requested", "valid_reasons"],
     ["Screen", "Account", "FSLI", "Amount", "Risk", "Regularity", "Observation",
      "Expectation", "Gap", "Assertions", "Proposed response", "Evidence requested",
      "Valid reasons"]),
    ("Evidence Requests", "evidence_request_list.json", "evidence_request_list",
     ["record", "audit_area", "highest_risk_rating", "regularity_relevant", "requested_for"],
     ["Record to obtain", "Audit area", "Highest risk", "Regularity", "Requested for"]),
    ("Management Queries", "management_query_list.json", "management_query_list",
     ["subject", "risk_rating", "query", "candidate_explanations"],
     ["Subject", "Risk", "Query", "Candidate explanations"]),
    ("Assertion Map", "assertion_evidence_map.json", "assertion_evidence_map",
     ["account", "account_area", "assertions", "evidence_requested", "previous_generic_evidence"],
     ["Account", "Account area", "Assertions", "Evidence requested", "Previously (generic)"]),
    ("Counterpart Gaps", "counterpart_screen.json", "finding_records",
     ["relationship_id", "source_head", "source_balance", "target_balance", "risk_rating", "gap"],
     ["Relationship", "Source head", "Source", "Counterpart", "Risk", "Gap"]),
    ("Relationship Expectations", "relationship_expectations.json", "results",
     ["id", "name", "status", "observed_ratio", "formula"],
     ["ID", "Relationship", "Status", "Observed ratio", "Formula"]),
    ("Abnormal Signs", "abnormal_sign_screen.json", "finding_records",
     ["account", "report_head", "amount", "normal_balance_expectation", "actual_balance_side"],
     ["Account", "Class", "Balance", "Normal side", "Actual side"]),
    ("Statutory Screen", "statutory_screen.json", "results",
     ["id", "label", "status", "base_balance", "dues_balance", "observed_ratio"],
     ["ID", "Levy relationship", "Status", "Base", "Dues", "Observed ratio"]),
    ("Public Sector Lens", "public_sector_lens.json", "finding_records",
     ["account", "regularity_question", "amount", "risk_rating", "evidence_requested"],
     ["Account", "Regularity question", "Balance", "Risk", "Evidence requested"]),
    ("CARO Indicators", "caro_indicators.json", "finding_records",
     ["fsli", "clause_hint", "amount", "risk_rating", "observation"],
     ["Area", "Clause hint", "Balance", "Rating", "Observation"]),
    ("Override Indicators", "override_indicators.json", "finding_records",
     ["indicator", "account", "amount", "risk_rating", "observation"],
     ["Indicator", "Account", "Amount", "Risk", "Observation"]),
    ("Going Concern", "going_concern_screen.json", "indicators",
     ["indicator", "present", "amount"], ["Indicator", "Present", "Amount"]),
]

def _cy_population_sheets(new_sheet, cy_dir):
    for name, filename, key, columns, headers in _CY_POPULATIONS:
        path = Path(cy_dir) / filename
        if not path.exists():
            continue
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
        except (json.JSONDecodeError, OSError):
            continue
        records = (data or {}).get(key) or []
        if not records:
            continue
        rows = []
        for r in records:
            row = []
            for c in columns:
                v = r.get(c)
                if isinstance(v, (list, tuple)):
                    v = "; ".join(str(x) for x in v)
                elif isinstance(v, dict):
                    v = json.dumps(v, default=str)
                row.append(v)
            rows.append(row)
        ws = new_sheet(name)
        _write_sheet_title(ws, f"{name} — Current Year",
                           "Full population; the comparative report's narrative is capped",
                           len(headers))
        _write_table(ws, 4, headers, rows, formats=[None] * len(headers))
        ws.freeze_panes = "A5"


@pipeline_tool("build_comparison_report_markdown", domain="comparison")
def build_comparison_report_markdown(output_dir: str = None, **kwargs) -> dict:
    """
    Renders the same PY vs CY Comparison report content as build_comparison_report (Executive
    Summary through Limitations & No-Opinion Statement) as a markdown string in `data.markdown`,
    for relaying verbatim in a CHAT_QUERY/COMPARISON final response instead of only pointing at
    the .docx file. Reads the identical comparison artifacts (precheck_results.json,
    structural_delta.json, comparison_variance.parquet, sign_convention_flags.json,
    comparison_reasoning.json) and CY single-TB artifacts as build_comparison_report, so figures
    never drift between the two -- only the rendering target differs.
    """
    errors = []
    out_dir = resolve_output_dir(output_dir)

    def load_json(base_dir, filename, required=True):
        p = Path(base_dir) / filename
        if not p.exists():
            if required:
                errors.append({"type": "MissingDataWarning", "message": f"File {filename} not found in {base_dir}."})
            return None
        try:
            with open(p, "r", encoding="utf-8") as f:
                return json.load(f)
        except Exception as e:
            errors.append({"type": "ParseError", "file": filename, "error": str(e)})
            return None

    reasoning = load_json(out_dir, "comparison_reasoning.json") or {}
    precheck_data = load_json(out_dir, "precheck_results.json") or {"checks": []}
    structural_data = load_json(out_dir, "structural_delta.json") or {}
    sign_check_data = load_json(out_dir, "sign_convention_flags.json") or {"flags": []}

    variance_rows = []
    var_path = out_dir / "comparison_variance.parquet"
    if var_path.exists():
        try:
            variance_rows = pl.read_parquet(var_path).to_dicts()
        except Exception as e:
            errors.append({"type": "ParseError", "file": "comparison_variance.parquet", "error": str(e)})

    cy_dir_override = kwargs.get("cy_output_dir")
    cy_dir = Path(cy_dir_override) if cy_dir_override else (out_dir.parent / "cy")
    if not cy_dir.exists():
        cy_dir = out_dir
    cy_materiality = load_json(cy_dir, "materiality.json", required=False) or {}
    cy_sensitive = load_json(cy_dir, "sensitive_accounts.json", required=False) or {}
    cy_canonical_df = _load_canonical_tb(cy_dir)

    def safe_fmt(val):
        try:
            return f"{float(val):,.0f}"
        except Exception:
            return str(val)

    tb_meta_cy = load_json(cy_dir, "tb_metadata.json", required=False) or {}
    manifest_cy = load_json(cy_dir, "processing_manifest.json", required=False) or {}
    py_dir_override = kwargs.get("py_output_dir")
    py_dir = Path(py_dir_override) if py_dir_override else (out_dir.parent / "py")
    tb_meta_py = load_json(py_dir, "tb_metadata.json", required=False) or {} if py_dir.exists() else {}
    manifest_py = load_json(py_dir, "processing_manifest.json", required=False) or {} if py_dir.exists() else {}

    entity_label, _cy_fy, cy_source = resolve_entity_and_fy(tb_meta_cy, manifest_cy)
    _, _, py_source = resolve_entity_and_fy(tb_meta_py, manifest_py)
    stem = Path(cy_source).stem if cy_source else "Unknown Entity"
    cy_fy_match = re.search(r"FY\s*[\d\-/]+", stem, re.IGNORECASE)
    cy_fy_label = cy_fy_match.group(0).upper() if cy_fy_match else "CY"
    py_stem = Path(py_source).stem if py_source else ""
    py_fy_match = re.search(r"FY\s*[\d\-/]+", py_stem, re.IGNORECASE)
    py_fy_label = py_fy_match.group(0).upper() if py_fy_match else "PY"

    checks = precheck_data.get("checks", [])
    py_ctrl = next((c for c in checks if c.get("check") == "py_debit_credit_control_totals"), None)
    cy_ctrl = next((c for c in checks if c.get("check") == "cy_debit_credit_control_totals"), None)
    continuity_check = next((c for c in checks if c.get("check") == "opening_closing_continuity"), None)

    cy_materiality_thr = cy_materiality.get("thresholds", {})
    om = cy_materiality_thr.get("overall", 0.0)
    perf_mat = cy_materiality_thr.get("performance", 0.0)
    triv = cy_materiality_thr.get("clearly_trivial", 0.0)
    cy_summ = cy_materiality.get("summary", {})
    cy_sens_cat = cy_sensitive.get("category_summary", {})

    cy_fsli_df = None
    cy_fsli_path = cy_dir / "fsli_summary.parquet"
    if cy_fsli_path.exists():
        try:
            cy_fsli_df = pl.read_parquet(cy_fsli_path)
        except Exception as e:
            errors.append({"type": "ParseError", "file": "fsli_summary.parquet", "error": str(e)})

    cy_conc_rows = _concentration_rows_from_canonical(cy_canonical_df)
    cy_dormant_rows = _dormant_rows_from_canonical(cy_canonical_df)

    new_ledgers = structural_data.get("new_ledgers", [])
    removed_ledgers = structural_data.get("removed_ledgers", [])
    py_count = structural_data.get("py_count", 0)
    cy_count = structural_data.get("cy_count", 0)

    # BUG FIX (comparative-analysis QA review): see build_comparison_report.py's identical
    # fix for the full explanation. run_comparison_prechecks.py now excludes expected P&L
    # resets from break_count/breaks at the source (using the canonical bs_pl column, not
    # a pattern-matched main_head label) -- continuity_check's `breaks` here is already the
    # genuine list, no re-filtering needed.
    genuine_breaks = []
    expected_reset = 0
    total_breaks = 0
    if continuity_check:
        expected_reset = continuity_check.get("expected_pl_reset_count", 0)
        total_breaks = continuity_check.get("total_raw_break_count", continuity_check.get("break_count", 0))
        name_map = {}
        ref_df = cy_canonical_df if cy_canonical_df is not None else _load_canonical_tb(py_dir)
        if ref_df is not None and "gl_code" in ref_df.columns and "gl_name" in ref_df.columns:
            name_map = dict(zip(ref_df["gl_code"].cast(pl.Utf8).to_list(), ref_df["gl_name"].to_list()))
        for b in continuity_check.get("breaks", []):
            code = str(b.get("gl_code", ""))
            try:
                diff_val = float(b.get("diff", 0) or 0)
            except (TypeError, ValueError):
                diff_val = 0.0
            genuine_breaks.append({
                "gl_code": code, "gl_name": name_map.get(code, ""),
                "py_closing": b.get("closing_balance"), "cy_opening": b.get("opening_balance"),
                "diff": diff_val,
            })
        genuine_breaks.sort(key=lambda x: abs(x["diff"]), reverse=True)

    # See build_comparison_report.py's identical mapping note: "twice overall materiality"
    # == CRITICAL, "more than the threshold alone" == HIGH (not the new, more granular
    # MEDIUM tier).
    variance_flagged = [r for r in variance_rows if r.get("flag") not in (None, "NO_CHANGE")]
    high_priority = [r for r in variance_flagged if r.get("flag") == "CRITICAL"]
    medium_variance = [r for r in variance_flagged if r.get("flag") == "HIGH"]
    top_movements = sorted(variance_flagged, key=lambda r: abs(r.get("variance") or 0), reverse=True)[:10]
    flags = sign_check_data.get("flags", [])
    observations = reasoning.get("observations", [])

    def md_table(headers, rows):
        if not rows:
            return ""
        lines = ["| " + " | ".join(headers) + " |", "|" + "|".join(["---"] * len(headers)) + "|"]
        for r in rows:
            lines.append("| " + " | ".join(str(c) for c in r) + " |")
        return "\n".join(lines) + "\n"

    lines = []
    a = lines.append
    a(f"# Trial Balance - ({entity_label}) — PY vs CY Comparative Analysis")
    a(f"### {py_fy_label} → {cy_fy_label}")
    a("")
    a("> Mechanical, evidence-based analytical review derived solely from the two trial balance "
      "files and the GL grouping workbook supplied. No audit opinion; risk-assessment and planning "
      "aid only.")
    a("")

    a("## Executive Summary")
    if py_count and cy_count:
        a(
            f"The {entity_label} trial balance {'grew' if cy_count >= py_count else 'reduced'} from "
            f"{py_count} GL accounts in {py_fy_label} to {cy_count} in {cy_fy_label}. Both years are "
            + ("internally self-balanced — debit and credit control totals match exactly in each "
               "period." if (py_ctrl and py_ctrl.get("status") == "PASS" and cy_ctrl and cy_ctrl.get("status") == "PASS")
               else "compared below; see Data Quality for the detailed control-total position.")
        )
    a("")
    if new_ledgers or removed_ledgers:
        a(f"- **Structural change** — {len(new_ledgers)} account(s) appear only in {cy_fy_label} and "
          f"{len(removed_ledgers)} only in {py_fy_label} — a {len(new_ledgers) + len(removed_ledgers)}-"
          f"account chart-of-accounts change against a base of roughly {py_count or cy_count}.")
    if total_breaks:
        a(f"- **Continuity** — " + (
            f"{expected_reset} of {total_breaks} PY-closing-to-CY-opening differences are "
            "Revenue/Expense accounts resetting to nil (expected). "
            f"{len(genuine_breaks)} account(s) carry a genuine, unexplained discontinuity."
            if genuine_breaks else
            f"All {total_breaks} PY-closing-to-CY-opening differences are Revenue/Expense accounts "
            "resetting to nil, which is expected and not a control weakness."
        ))
    if high_priority or medium_variance:
        a(f"- **Material movements** — {len(high_priority)} account(s) moved by more than twice the "
          f"overall materiality threshold and a further {len(medium_variance)} moved by more than "
          "the threshold alone.")
    if flags:
        a("- **Sign convention** — sign-convention screens were run for both periods; see Sign "
          "Convention Consistency below — this is a broad screen, not a specific finding.")
    a("")
    a("**Where to focus first:**")
    focus_first = []
    if genuine_breaks:
        top_break = genuine_breaks[0]
        focus_first.append(
            f"- Continuity — obtain the retained-earnings/continuity roll-forward and agree the "
            f"{safe_fmt(top_break['diff'])} movement on GL {top_break['gl_code']}."
        )
    if top_movements:
        top_mv = top_movements[0]
        focus_first.append(
            f"- Variance — corroborate the largest variance accounts, especially "
            f"{top_mv.get('gl_name', '')} ({safe_fmt(top_mv.get('variance', 0))})."
        )
    if cy_conc_rows:
        top_c = cy_conc_rows[0]
        focus_first.append(
            f"- Concentration — {top_c['gl_name']} is {top_c['pct']:.1f}% of total {top_c['fs_head']} "
            "— disproportionate reliance on one balance being correctly stated."
        )
    a("\n".join(focus_first) if focus_first else "No high-priority focus areas were flagged deterministically in this dataset.")
    a("")

    a("## Data Quality & Control Totals")
    if py_ctrl or cy_ctrl:
        a(md_table(
            ["Check", f"{py_fy_label} (PY)", f"{cy_fy_label} (CY)"],
            [
                ("Total Debit", safe_fmt((py_ctrl or {}).get("total_debit", 0)), safe_fmt((cy_ctrl or {}).get("total_debit", 0))),
                ("Total Credit", safe_fmt((py_ctrl or {}).get("total_credit", 0)), safe_fmt((cy_ctrl or {}).get("total_credit", 0))),
                ("Debit − Credit Difference", safe_fmt((py_ctrl or {}).get("diff", 0)), safe_fmt((cy_ctrl or {}).get("diff", 0))),
            ],
        ))
        both_pass = (py_ctrl or {}).get("status") == "PASS" and (cy_ctrl or {}).get("status") == "PASS"
        a(
            "Debit and credit control totals "
            + ("match exactly in both periods (zero difference)." if both_pass else
               "do not match exactly in one or both periods — see the status flags above.")
        )
    else:
        a("Control totals could not be computed — precheck_results.json was not available.")
    a("")

    a("## Provisional Materiality (CY basis)")
    if cy_materiality:
        a(md_table(
            ["Basis", "Value"],
            [
                ("Materiality Basis Used", cy_summ.get("benchmark_used", "Unknown")),
                ("Overall Materiality", safe_fmt(om)),
                ("Performance Materiality (75% of OM)", safe_fmt(perf_mat)),
                ("Clearly Trivial Threshold", safe_fmt(triv)),
            ],
        ))
        a("*Provisional only — a mechanical benchmark-based calculation on the current-year trial balance. Not a substitute for engagement-level materiality judgment.*")
    else:
        a("Current-year materiality was not available for this comparison run.")
    a("")

    a("## FSLI Summary — Current Year")
    if cy_fsli_df is not None and not cy_fsli_df.is_empty():
        if "hierarchy_level" in cy_fsli_df.columns:
            lvl1 = cy_fsli_df.filter(pl.col("hierarchy_level") == 1)
        else:
            lvl1 = cy_fsli_df
        lvl1 = lvl1.with_columns(pl.col("closing_balance").abs().alias("_abs")).sort("_abs", descending=True)
        a(md_table(
            ["FS Head", "GL Accounts", "Closing Balance (CY)"],
            [
                (r.get("main_head") or r.get("fs_head") or r.get("line_item") or "",
                 int(r.get("descendant_gl_count") or r.get("leaf_gl_count") or r.get("gl_accounts") or 0),
                 safe_fmt(r.get("closing_balance", 0.0)))
                for r in lvl1.iter_rows(named=True)
            ],
        ))
    else:
        a("Current-year FSLI summary was not available for this comparison run.")
    a("")

    a("## Structural Delta — PY vs CY Ledger Composition")
    a(f"{py_count} GL account(s) in {py_fy_label} vs {cy_count} in {cy_fy_label}. "
      f"{len(new_ledgers)} added, {len(removed_ledgers)} removed.")
    a("")

    a("## PY Closing → CY Opening Continuity")
    if continuity_check:
        a(f"{total_breaks} discontinuit(y/ies) found; {expected_reset} are expected Revenue/Expense "
          f"resets, {len(genuine_breaks)} are genuine.")
        if genuine_breaks:
            a(md_table(
                ["GL Code", "GL Name", "PY Closing", "CY Opening", "Diff"],
                [(g["gl_code"], g["gl_name"], safe_fmt(g["py_closing"]), safe_fmt(g["cy_opening"]), safe_fmt(g["diff"])) for g in genuine_breaks[:15]],
            ))
    else:
        a("Continuity check not available.")
    a("")

    a("## Variance Analysis — PY vs CY Closing Balance")
    if top_movements:
        a(md_table(
            ["GL Code", "GL Name", "PY Closing", "CY Closing", "Variance", "Flag"],
            [(m.get("gl_code", ""), m.get("gl_name", ""), safe_fmt(m.get("py_closing", 0)), safe_fmt(m.get("cy_closing", 0)), safe_fmt(m.get("variance", 0)), m.get("flag", "")) for m in top_movements],
        ))
    else:
        a("No material PY vs CY variances were flagged.")
    a("")

    a("## Sign Convention Consistency")
    a(f"{len(flags)} sign-convention flag(s) raised across both periods." if flags else
      "Sign convention could not be assessed or no flags were raised.")
    a("")

    a("## Risk Indicators — Current Year")
    a("**Concentration — accounts exceeding 5% of their FS Head**")
    if cy_conc_rows:
        a(md_table(
            ["GL Code", "GL Name", "FS Head", "Closing Balance", "% of FS Head"],
            [(c["gl_code"], c["gl_name"], c["fs_head"], safe_fmt(c["closing"]), f"{c['pct']:.1f}%") for c in cy_conc_rows],
        ))
    else:
        a("No account individually exceeds 5% of its FS Head in the current year.")
    a("")
    a("**Dormant accounts (current year)**")
    if cy_dormant_rows:
        a(md_table(
            ["GL Code", "GL Name", "FS Head", "Closing Balance"],
            [(d["gl_code"], d["gl_name"], d["fs_head"], safe_fmt(d["closing"])) for d in cy_dormant_rows],
        ))
    else:
        a("No dormant accounts with a material closing balance were identified.")
    a("")

    a("## Sensitive Account Categories — Current Year")
    if cy_sens_cat:
        a(md_table(
            ["Category", "Accounts", "Combined Closing Balance"],
            [(k.replace("_", " "), str(v.get("count", 0)), safe_fmt(v.get("total_balance", 0))) for k, v in cy_sens_cat.items()],
        ))
    else:
        a("Current-year sensitive-account categories were not available for this comparison run.")
    a("")

    a("## Focus Areas")
    if observations:
        for i, obs_wrap in enumerate(observations, start=1):
            obs = obs_wrap.get("observation", obs_wrap) if isinstance(obs_wrap, dict) else {}
            sev = str(obs.get("priority", "LOW")).upper()
            title = obs.get("title", "Comparison Finding")
            a(f"### F{i:02d} [{sev}] {title}")
            a(f"- **Observation and Gap:** {obs.get('detailed_observation', obs.get('executive_summary', ''))}")
            assertions = obs.get("affected_assertions", [])
            a(f"- **Assertions/Risk Basis:** {', '.join(assertions)}. Risk Rating: {sev}")
            procs = obs.get("recommended_procedures", [])
            a(f"- **Evidence Requested:** {', '.join(procs) if procs else 'reconciliation, ledger dump'}")
    else:
        a("No comparison observations were generated for this dataset.")
    a("")

    a("## Suggested Audit Focus Sequence")
    seq_lines = []
    for obs_wrap in observations:
        obs = obs_wrap.get("observation", obs_wrap) if isinstance(obs_wrap, dict) else {}
        sev = str(obs.get("priority", "LOW")).upper()
        if sev not in ("CRITICAL", "HIGH", "MEDIUM"):
            continue
        name = obs.get("title", "")
        reason = obs.get("executive_summary", "")
        seq_lines.append(f"- {name} — {sev}-rated finding: {reason}")
    a("\n".join(seq_lines) if seq_lines else "No High/Medium-rated findings to sequence for audit focus.")
    a("")

    a("## Limitations & No-Opinion Statement")
    a("This review is mechanical and confined entirely to the two trial balance files and the "
      "grouping workbook supplied:")
    a("- No assurance opinion — it does not constitute an audit, review, or any other assurance "
      "engagement under any professional standard.")
    a("- No corroboration performed — no vouching, confirmation, analytical corroboration against "
      "external data, or management inquiry was performed.")
    a("- Grouping not independently verified — classifications rely on the GL Grouping workbook as "
      "supplied and have not been independently verified against statutory financial statements.")
    a("- No rescaling — figures are presented exactly as extracted from source, unscaled.")
    a("")
    a("*This document should be read alongside, not instead of, full substantive audit procedures.*")

    markdown = "\n".join(lines)
    return {
        "execution_status": "SUCCESS",
        "pipeline_status": "SUCCESS",
        "message": "Rendered Comparison report content as markdown.",
        "data": {"markdown": markdown},
        "artifacts": [],
        "errors": errors,
    }


def _require_file__run_comparison_prechecks(path, label: str):
    from pathlib import Path

    p = Path(path)
    if not p.exists():
        raise PipelineFileError(str(p), label)
    return p

@pipeline_tool("run_comparison_prechecks", domain="comparison")
def run_comparison_prechecks(py_canonical_tb: str, cy_canonical_tb: str, output_dir: str = None) -> dict:
    """Run PY/CY continuity and integrity pre-checks on two canonical TBs."""
    out_dir = resolve_output_dir(output_dir)
    out_dir.mkdir(parents=True, exist_ok=True)

    py_df = pl.read_parquet(_require_file__run_comparison_prechecks(py_canonical_tb, "PY canonical TB"))
    cy_df = pl.read_parquet(_require_file__run_comparison_prechecks(cy_canonical_tb, "CY canonical TB"))

    checks = []
    # Opening(CY) == Closing(PY) per GL code — ported from
    # TB_comparison/tools/precheck_tools.py:240 check_opening_closing_continuity
    #
    # P&L accounts correctly reset to a nil opening balance every year (they carry no
    # balance forward by design) -- that is expected, not a continuity break. This is the
    # single source every downstream consumer (build_comparison_report.py,
    # build_comparison_report_markdown.py, build_comparison_reasoning.py's HIGH-severity
    # continuity_break finding) reads break_count/breaks from, so filtering here fixes all
    # three at once. A prior version instead let each of those three files independently
    # re-derive "P&L or not" by string-matching the raw main_head label against the literal
    # strings "revenue"/"expenses" -- but main_head holds sub-category labels ("Wages",
    # "Rent", "Auditor fees", ...), never those literal words, so the exclusion almost
    # never matched. Live verification against a real PY->CY comparison found 29 of 30
    # breaks were ordinary P&L resets wrongly reported as genuine, producing a false
    # HIGH-severity finding that buried the one real (Equity) break under 29 false
    # positives. bs_pl ("BS"/"PL", set once per row from the source data) is the reliable,
    # already-existing signal for this -- no pattern-matching needed.
    cy_select_cols = ["gl_code", "opening_balance"]
    has_bs_pl = "bs_pl" in cy_df.columns
    if has_bs_pl:
        cy_select_cols.append("bs_pl")
    merged = py_df.select(["gl_code", "closing_balance"]).join(
        cy_df.select(cy_select_cols), on="gl_code", how="full", coalesce=True
    )
    # A gl_code present in PY but entirely absent from CY (opening_balance genuinely null,
    # not zero) is a removed ledger -- a structural change already captured by
    # run_comparison_structural.py's removed_ledgers list, not a continuity anomaly.
    # "Did PY's closing balance correctly carry into CY's opening balance" only means
    # something when the account still exists in CY -- excluded here, not folded into
    # break_count under either bucket, so it isn't silently double-counted nor silently
    # dropped from the total.
    merged = merged.filter(pl.col("opening_balance").is_not_null())
    merged = merged.with_columns(
        (
            pl.col("closing_balance").cast(pl.Float64, strict=False).fill_null(0)
            - pl.col("opening_balance").cast(pl.Float64, strict=False).fill_null(0)
        ).abs().alias("diff")
    )
    raw_breaks = merged.filter(pl.col("diff") > 0.01)
    if has_bs_pl:
        is_expected_pl_reset = (
            (pl.col("bs_pl").cast(pl.Utf8, strict=False).str.to_uppercase() == "PL")
            & (pl.col("opening_balance").cast(pl.Float64, strict=False).fill_null(0) == 0)
        )
        expected_pl_resets = raw_breaks.filter(is_expected_pl_reset)
        genuine_breaks = raw_breaks.filter(~is_expected_pl_reset)
    else:
        expected_pl_resets = raw_breaks.head(0)
        genuine_breaks = raw_breaks
    checks.append({
        "check": "opening_closing_continuity",
        "status": "PASS" if genuine_breaks.is_empty() else "WARNING",
        "break_count": int(len(genuine_breaks)),
        "breaks": genuine_breaks.head(50).to_dicts(),
        "expected_pl_reset_count": int(len(expected_pl_resets)),
        "total_raw_break_count": int(len(raw_breaks)),
    })

    # PY/CY debit == credit control totals — ported from
    # TB_comparison/tools/sign_convention_tools.py:51 check_debit_credit_control_totals
    for label, df in (("PY", py_df), ("CY", cy_df)):
        if "debit" in df.columns and "credit" in df.columns:
            total_debit = round(float(df["debit"].cast(pl.Float64, strict=False).fill_null(0).sum()), 2)
            total_credit = round(float(df["credit"].cast(pl.Float64, strict=False).fill_null(0).sum()), 2)
            diff = round(total_debit - total_credit, 2)
            activity_base = max(abs(total_debit), abs(total_credit))
            diff_pct = round(abs(diff) / activity_base * 100, 4) if activity_base > 0 else 0.0
            if diff == 0.0:
                status = "PASS"
            elif diff_pct <= 5.0:
                status = "WARNING"
            else:
                status = "HALTED"
            checks.append({
                "check": f"{label.lower()}_debit_credit_control_totals",
                "status": status,
                "total_debit": total_debit,
                "total_credit": total_credit,
                "diff": diff,
                "diff_pct": diff_pct,
            })

    result_path = out_dir / "precheck_results.json"
    with open(result_path, "w", encoding="utf-8") as f:
        json.dump({"checks": checks}, f, indent=2, default=str)

    any_halted = any(c["status"] == "HALTED" for c in checks)
    any_warning = any(c["status"] == "WARNING" for c in checks)
    # Precheck flags never stop the Comparison pipeline — a check that would
    # otherwise be HALTED-severity is downgraded to WARNING here so
    # can_continue stays true; the underlying per-check "status" field above
    # (still "HALTED" if applicable) is preserved in precheck_results.json
    # for the report to flag.
    pipeline_status = "WARNING" if (any_halted or any_warning) else "SUCCESS"
    return {
        "execution_status": "SUCCESS",
        "artifacts": [str(result_path)],
        "message": f"Ran {len(checks)} comparison pre-check(s); pipeline_status={pipeline_status}.",
        "pipeline_status": pipeline_status,
    }


def _require_file__run_comparison_sign_check(path, label: str):
    from pathlib import Path

    p = Path(path)
    if not p.exists():
        raise PipelineFileError(str(p), label)
    return p

@pipeline_tool("run_comparison_sign_check", domain="comparison")
def run_comparison_sign_check(py_canonical_tb: str, cy_canonical_tb: str, output_dir: str = None) -> dict:
    """Heuristic PY/CY closing-balance sign convention check using normal-side keyword anchors."""
    out_dir = resolve_output_dir(output_dir)
    out_dir.mkdir(parents=True, exist_ok=True)

    py_df = pl.read_parquet(_require_file__run_comparison_sign_check(py_canonical_tb, "PY canonical TB"))
    cy_df = pl.read_parquet(_require_file__run_comparison_sign_check(cy_canonical_tb, "CY canonical TB"))

    # Sign convention heuristic -- ported from
    # TB_comparison/tools/sign_convention_tools.py check_sign_convention.
    # The keyword lists were byte-identical to validate_layer1_tb.py's copy
    # (verified by AST comparison before extraction); both now read the single
    # definition in backend/knowledge/anchors/normal_side_anchors.json so they
    # cannot drift apart.
    debit_kws = debit_anchors()
    credit_kws = credit_anchors()

    def match_side(name):
        n = str(name).lower()
        is_debit = any(kw in n for kw in debit_kws)
        is_credit = any(kw in n for kw in credit_kws)
        if is_debit and not is_credit:
            return "debit"
        if is_credit and not is_debit:
            return "credit"
        return None

    def check_year(df, year_str):
        debit_positive = debit_negative = 0
        credit_positive = credit_negative = 0
        for row in df.iter_rows(named=True):
            try:
                bal = float(row.get("closing_balance", 0.0))
            except (ValueError, TypeError):
                bal = 0.0
            if bal != bal or bal == 0:  # bal != bal is the NaN check
                continue
            side = match_side(row.get("gl_name", ""))
            if side == "debit":
                if bal > 0:
                    debit_positive += 1
                else:
                    debit_negative += 1
            elif side == "credit":
                if bal < 0:
                    credit_negative += 1
                else:
                    credit_positive += 1

        debit_anchors = debit_positive + debit_negative
        credit_anchors = credit_positive + credit_negative
        min_anchors = 3
        threshold = 0.7

        if debit_anchors < min_anchors or credit_anchors < min_anchors:
            return {
                "year": year_str,
                "status": "WARNING",
                "message": (
                    f"Not enough recognizable ledger names in {year_str} to confirm sign convention "
                    f"({debit_anchors} debit-side, {credit_anchors} credit-side anchors found; "
                    f"need {min_anchors} each). Skipping."
                ),
                "debit_anchors": debit_anchors,
                "credit_anchors": credit_anchors,
            }

        debit_agreement = debit_positive / debit_anchors
        credit_agreement = credit_negative / credit_anchors

        if debit_agreement >= threshold and credit_agreement >= threshold:
            status = "PASS"
            message = (
                f"{year_str} closing balances follow the expected debit-positive / credit-negative convention."
            )
        else:
            inv_debit_agreement = debit_negative / debit_anchors
            inv_credit_agreement = credit_positive / credit_anchors
            if inv_debit_agreement >= threshold and inv_credit_agreement >= threshold:
                status = "WARNING"
                message = (
                    f"{year_str} closing balances appear to follow a credit-positive / debit-negative convention, "
                    f"the reverse of what this pipeline assumes."
                )
            else:
                status = "WARNING"
                message = (
                    f"{year_str} closing balance signs are inconsistent relative to normal-side anchors. "
                    f"This may indicate mixed sign conventions in the source file."
                )

        return {
            "year": year_str,
            "status": status,
            "message": message,
            "debit_anchors": debit_anchors,
            "credit_anchors": credit_anchors,
            "debit_positive_pct": round(debit_agreement * 100, 1),
            "credit_negative_pct": round(credit_agreement * 100, 1),
        }

    py_result = check_year(py_df, "PY")
    cy_result = check_year(cy_df, "CY")
    flags = [py_result, cy_result]

    result_path = out_dir / "sign_convention_flags.json"
    with open(result_path, "w", encoding="utf-8") as f:
        json.dump({"flags": flags}, f, indent=2, default=str)

    any_warning = any(f["status"] == "WARNING" for f in flags)
    return {
        "execution_status": "SUCCESS",
        "artifacts": [str(result_path)],
        "message": f"Sign convention check complete; {'warnings present' if any_warning else 'all passed'}.",
        "pipeline_status": "WARNING" if any_warning else "SUCCESS",
    }


def _require_file__run_comparison_structural(path, label: str):
    from pathlib import Path

    p = Path(path)
    if not p.exists():
        raise PipelineFileError(str(p), label)
    return p

def _grouping_delta(py_df: pl.DataFrame, cy_df: pl.DataFrame, column: str) -> dict:
    """Diffs the distinct, non-null values of a grouping column (main_head/sub_head_1/sub_head_2)."""
    if column not in py_df.columns or column not in cy_df.columns:
        return {"py_values": [], "cy_values": [], "new": [], "removed": []}
    py_values = {str(v).strip() for v in py_df[column].drop_nulls().to_list() if str(v).strip()}
    cy_values = {str(v).strip() for v in cy_df[column].drop_nulls().to_list() if str(v).strip()}
    return {
        "py_values": sorted(py_values),
        "cy_values": sorted(cy_values),
        "new": sorted(cy_values - py_values),
        "removed": sorted(py_values - cy_values),
    }

@pipeline_tool("run_comparison_structural", domain="comparison")
def run_comparison_structural(py_canonical_tb: str, cy_canonical_tb: str, output_dir: str = None) -> dict:
    """Compute PY vs CY ledger count delta and new/removed GL codes / FS groupings."""
    out_dir = resolve_output_dir(output_dir)
    out_dir.mkdir(parents=True, exist_ok=True)

    py_df = pl.read_parquet(_require_file__run_comparison_structural(py_canonical_tb, "PY canonical TB"))
    cy_df = pl.read_parquet(_require_file__run_comparison_structural(cy_canonical_tb, "CY canonical TB"))

    # Ledger count delta — ported from TB_comparison/tools/structural_tools.py
    # check_ledger_count_delta
    py_ledgers = {
        str(row["gl_code"]).strip(): str(row.get("gl_name", "")).strip()
        for row in py_df.iter_rows(named=True)
    }
    cy_ledgers = {
        str(row["gl_code"]).strip(): str(row.get("gl_name", "")).strip()
        for row in cy_df.iter_rows(named=True)
    }

    py_codes = set(py_ledgers.keys())
    cy_codes = set(cy_ledgers.keys())

    new_codes = cy_codes - py_codes
    removed_codes = py_codes - cy_codes

    new_ledgers = [{"gl_code": c, "gl_name": cy_ledgers[c]} for c in new_codes]
    removed_ledgers = [{"gl_code": c, "gl_name": py_ledgers[c]} for c in removed_codes]

    delta = len(cy_codes) - len(py_codes)

    # FS-grouping delta — new/removed main_head, sub_head_1, sub_head_2 values,
    # derived on the fly (no persisted hierarchy in the new canonical schema).
    fs_grouping_delta = {
        "main_head": _grouping_delta(py_df, cy_df, "main_head"),
        "sub_head_1": _grouping_delta(py_df, cy_df, "sub_head_1"),
        "sub_head_2": _grouping_delta(py_df, cy_df, "sub_head_2"),
    }

    structural_delta = {
        "check": "ledger_count_delta",
        "py_count": len(py_codes),
        "cy_count": len(cy_codes),
        "delta": delta,
        "new_ledgers": new_ledgers,
        "removed_ledgers": removed_ledgers,
        "fs_grouping_delta": fs_grouping_delta,
        "message": (
            f"PY ledgers: {len(py_codes)}, CY ledgers: {len(cy_codes)}. Delta: {delta}. "
            f"New ledgers: {len(new_ledgers)}. Removed ledgers: {len(removed_ledgers)}."
        ),
    }

    result_path = out_dir / "structural_delta.json"
    with open(result_path, "w", encoding="utf-8") as f:
        json.dump(structural_delta, f, indent=2, default=str)

    return {
        "execution_status": "SUCCESS",
        "artifacts": [str(result_path)],
        "message": structural_delta["message"],
        "pipeline_status": "SUCCESS",
    }


def _require_file__run_comparison_variance(path, label: str):
    p = Path(path)
    if not p.exists():
        raise PipelineFileError(str(p), label)
    return p

@pipeline_tool("run_comparison_variance", domain="comparison")
def run_comparison_variance(
    py_canonical_tb: str, cy_canonical_tb: str, materiality_file: str = None, output_dir: str = None
) -> dict:
    """Compute PY vs CY closing-balance variance per GL code, flagged against materiality thresholds."""
    out_dir = resolve_output_dir(output_dir)
    out_dir.mkdir(parents=True, exist_ok=True)

    py_df = pl.read_parquet(_require_file__run_comparison_variance(py_canonical_tb, "PY canonical TB"))
    cy_df = pl.read_parquet(_require_file__run_comparison_variance(cy_canonical_tb, "CY canonical TB"))

    # Read the shared materiality threshold produced by build_materiality, so comparison
    # variance flagging stays consistent with the single-TB report instead of
    # reimplementing TB_comparison's own PRECHECK_TOLERANCE_PCT. Defaults to the canonical
    # filename in output_dir when not explicitly supplied (matching the pattern used by
    # build_risk_indicators.py etc.) -- makes this tool robust even when called without an
    # explicit materiality_file, rather than silently degrading to NO_THRESHOLD.
    mat_path = Path(materiality_file) if materiality_file else out_dir / "materiality.json"
    overall_mat = None
    performance_mat = None
    if mat_path.exists():
        with open(mat_path, "r", encoding="utf-8") as f:
            mat_data = json.load(f)
        thresholds = mat_data.get("thresholds", {})
        overall_mat = float(thresholds.get("overall", 0.0)) or None
        performance_mat = float(thresholds.get("performance", 0.0)) or None

    # Variance calculation — ported from TB_comparison/tools/variance_tools.py:18
    # calculate_variance
    py_data = {
        str(row["gl_code"]).strip(): {
            "name": str(row.get("gl_name", "")).strip(),
            "bal": float(row.get("closing_balance")) if row.get("closing_balance") is not None else 0.0,
        }
        for row in py_df.iter_rows(named=True)
    }
    cy_data = {
        str(row["gl_code"]).strip(): {
            "name": str(row.get("gl_name", "")).strip(),
            "bal": float(row.get("closing_balance")) if row.get("closing_balance") is not None else 0.0,
        }
        for row in cy_df.iter_rows(named=True)
    }

    all_codes = set(py_data.keys()).union(set(cy_data.keys()))
    rows = []
    for code in all_codes:
        py_bal = py_data.get(code, {}).get("bal", 0.0)
        cy_bal = cy_data.get(code, {}).get("bal", 0.0)
        name = cy_data.get(code, {}).get("name") or py_data.get(code, {}).get("name", "")

        variance = cy_bal - py_bal
        variance_pct = (variance / py_bal * 100) if py_bal != 0 else None

        # BUG FIX (comparative-analysis QA review, follow-up): this used to have its own
        # flag vocabulary (NO_THRESHOLD/HIGH_PRIORITY/MEDIUM/LOW) that never included
        # CRITICAL at all, while the Excel workbook's Variance sheet independently
        # recomputed the same concept via a different function (_movement_flag_for_report
        # in backend/tools/comparison/_shared.py) with a CRITICAL/HIGH/MEDIUM/LOW
        # vocabulary -- two non-communicating implementations, same TB-R06 pattern as the
        # original defect registry. Now uses the single canonical severity function
        # (backend/tools/_shared.py::movement_flag) that both this file's output and the
        # Excel workbook (after the Excel writer is switched to read this parquet directly)
        # agree on.
        if py_bal == 0 and cy_bal != 0:
            flag = "NEW_ENTRY"
        elif py_bal != 0 and cy_bal == 0:
            flag = "DROPPED"
        elif variance == 0:
            flag = "NO_CHANGE"
        else:
            flag = movement_flag(abs(variance), overall_mat, performance_mat) or "LOW"

        rows.append({
            "gl_code": code,
            "gl_name": name,
            "py_closing": round(py_bal, 2),
            "cy_closing": round(cy_bal, 2),
            "variance": round(variance, 2),
            "variance_pct": round(variance_pct, 2) if variance_pct is not None else None,
            "flag": flag,
        })

    rows = sorted(rows, key=lambda x: x["gl_code"])
    result_df = pl.DataFrame(rows)
    result_path = out_dir / "comparison_variance.parquet"
    result_df.write_parquet(result_path)

    critical_count = sum(1 for r in rows if r["flag"] == "CRITICAL")
    return {
        "execution_status": "SUCCESS",
        "artifacts": [str(result_path)],
        "message": f"Computed variance for {len(rows)} GL code(s); {critical_count} critical.",
        "pipeline_status": "SUCCESS",
    }




